/* 平成24年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.h24.committeeSessions.push(...[{"id":"h24-20121023-8","meetingId":"h24-cm10","date":"2012年10月23日","dateIso":"2012-10-23","committee":"建設委員会","time":"午前１１時００分～午後 ３時１９分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を7件整理しています。","topics":[{"id":"topic-01","title":"の１、報告事項を行います。 初めに、(1)第２３回東京都道路整備事業推進大会","agenda":"の１、報告事項を行います。 初めに、(1)第２３回東京都道路整備事業推進大会","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"特に推進していく道路があったら教えていただきたいんですけれども、そういう道路も入っているのかについて、お聞かせほしいと求めました。それともう１つは、またこれから充てられようとしているとか、そういうことがあるかどうかについてもお聞かせほしいと求めました。","respondent":"藤田都市計画課長","answer":"ご案内のとおり、昨年まで三環状等のことが決議文等の中に入っていたということはありますので、今回もその辺がベースになされるのかと考えています。あくまでも道路事業をしっかり進めてほしいといったことを、東京都、国のほうに伝えていくということで考えてあります。","id":"exchange-001"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"復興予算がいろいろなところに利用されるということが本当に大きな問題で、そこら辺のところはぜひ区としてもつかんでほしいと求めました。都市計画道路にしても、進めるということには賛同していませんので、道路大会には参加しません。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-002"}]},{"id":"topic-02","title":"品川区まちづくりマスタープラン（素案）","agenda":"品川区まちづくりマスタープラン（素案）","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そして、区民がこれをいただきたいというときには、提供できるようなことでぜひしていただきたいと思うんですけれども、それが１点です。ぜひこのまちづくりマスタープランについて、少なくとも１３地域センターで説明会をしていただきたいと思うんですけれども、いかがか尋ねました。","respondent":"山崎マスタープラン担当課長","answer":"本マスタープランの方針について、先ほどご説明させていただいたとおり、最終的な策定に向けて動いてまいりたいです。１３地区の説明会ですけれども、説明会等々については、その事業単体で必要に応じて丁寧な説明をしてまいるということで考えてあります。","id":"exchange-003"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"パブリックコメントをするに当たり、この冊子を素案の段階で図書館や文化センターや地域センターに置いていただくということでよろしいんでしょうか。そのためにこれを見たいというときに、お金を取って、その冊子を区民に提供するということになるんか尋ねました。","respondent":"山崎マスタープラン担当課長","answer":"それから、ホームページのほうでは、特にお金を徴収しているというものではありませんので、それは広くダウンロードしやすく工夫すると。一定程度有償頒布の概念も入れて、そうした販売も行うということで、今のところ考えているものです。","id":"exchange-004"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"私が要望していますのは、これからパブリックコメントをするわけですよね。どうしたいという思いがある人だと思いますので、そういう方に提供できるようにしていただきたいと思うんですけれども、お答えいただきたい。","respondent":"山崎マスタープラン担当課長","answer":"区内各所で閲覧する資料と、それから場所のほうはご提供させていただいて、内容を見ていただいて、貴重なご意見を聴取したいという考えです。それから、資料の配布につきましては、あくまでも素案の段階ですので…","id":"exchange-005"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"その確認をお願いしたいと思います。これはカラーでダウンロードするのはかなりのページ数があって大変なことですので、提供できるようにという要望をさせてほしいと求めました。","respondent":"山崎マスタープラン担当課長","answer":"繰り返しになりますけれども、素案のほうはご覧いただくようなことで、素案は置かせていただきます。","id":"exchange-006"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"１回だけでは、なかなかこれを理解するということも大変ですし、また限られた１２０人という会場ですので、ぜひとも１３地域ごとに説明会を開いていただきたいと強く要望させてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-007"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/142731?Template=document&Id=4054#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2012-01-01&TermEnd=2012-12-31"}],"sourceMeta":{"pages":0,"characters":10111,"voices":39}},{"id":"h24-20121105-6","meetingId":"h24-cm11","date":"2012年11月5日","dateIso":"2012-11-05","committee":"区民委員会","time":"午後１時００分～午後２時５４分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を43件整理しています。","topics":[{"id":"topic-01","title":"の区民集会所の利用状況","agenda":"の区民集会所の利用状況","exchanges":[{"speaker":"山内委員","kind":"提案","question":"１０％前後ということで、毎年なんですが、この辺はどういった分析をしているんですか。もちろん利便性が悪いとか、このまま１０％で推移していくということであれば、その辺というのはどういった話を庁内でされているのか説明を求めました。","respondent":"久保田地域活動課長","answer":"やはり検討していかなければならないということで、庁内ではありますけれども、今後の利用については今検討しています。そういった意味では、どういった利用ができるかというところも含めまして検討を進めているといったところです。","id":"exchange-001"},{"speaker":"山内委員","kind":"質問","question":"検討されるということは、この数字を見れば明らかなんでしょうけれど、いつごろからそういうことをしているのか、どれぐらいの期間でやっているのか。これはスクエア荏原ができるとか、どれぐらいの期間、庁内で検討しているのかというのを伺いたいんですが。","respondent":"久保田地域活動課長","answer":"総合区民会館、また荏原第三区民集会所の改築等に合わせて、どうしたらいいかという問題意識を持って検討は進めてきているところです。平成２７年度末までには何らかの検討結果を出さなければならないかなというふうに思ってありますけれども、できるだけ速やかに方針を決めて。","id":"exchange-002"},{"speaker":"武内委員","kind":"意見","question":"今のに関連するんですけれども、そうすると、荏原西区民集会所なんですが、地域の方が運営などをやっていらっしゃるのかなと思うんですけども、予約システムには載っていないということなんですが、運営している方は、限られた方にしか貸さなくて…","respondent":"久保田地域活動課長","answer":"しながわガイドとか、そういうところにも載ってありますので、広く一般の方にご利用いただけるような体制はつくっているところです。","id":"exchange-003"},{"speaker":"武内委員","kind":"質問","question":"ちょっとそこが気になっていたんです。今保育園のほうも併設なんで、まだ耐震の課題があると、そういうことなんか尋ねました。","respondent":"久保田地域活動課長","answer":"保育園については、既に耐震補強は終わってありますので、そうした心配はございませんが、荏原西区民集会所につきましては、構造上の問題とかがありますので、上には乗っている施設ですけれども、荏原西区民集会所には課題があるです。","id":"exchange-004"},{"speaker":"武内委員","kind":"質問・要望","question":"荏原第五区民集会所とか、減額よりも免除のほうが多いところが幾つかあるんですけれども、これはどういう見方をしたらいいんでしょうか。例えば、免除が多いということは、それだけ高齢者の団体が使う率が多い、そういう考え方でいいんか尋ねました。","respondent":"久保田地域活動課長","answer":"この割合から判断しますと、やはり地域によって差はありますけれども、そうした町会とか高齢者の方の利用が高いというふうに考えてあります。例えば区内の企業が使う際には区民料金で使っていますので、そうした利用もあるのかなというふうに分析をしています。","id":"exchange-005"},{"speaker":"武内委員","kind":"質問","question":"今後どういうふうにしていくかというのは別にしても、今全部細かく聞きませんけど、押さえてはいるということなんですよね。それとも、ここはちょっとあくまでも推測ということなんか尋ねました。","respondent":"久保田地域活動課長","answer":"免除団体という形で集計はとっているんですけれども、もう一度改めてそれぞれの申込書等を確認した上でないと正確な数字は出ないということです。そうした中から実際の窓口等で対応している人、担当者の話、また自分の経験等に基づいてご説明をさせていただいたところです。","id":"exchange-006"},{"speaker":"武内委員","kind":"質問・要望","question":"やっぱりそれは何かの形で、ある程度はとっといて、今後どう施策を組むかというときに反映できるようにしたほうがいいんじゃないかと思うんですよね。要望します。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-007"},{"speaker":"大倉委員","kind":"意見","question":"平成２２年度の利用率が全部の傾向として下がっているのはどういう理由なのかというのと、どうしてなのかというのを、精査しているというのがあれば。どうしてその施設が高いのかというのを、その検証を踏まえて…","respondent":"久保田地域活動課長","answer":"ただ、平成２２年度において特別利用率が下がるような要因となる出来事はなかったというふうに認識しています。そう大きく変更はございませんので、分母も多少変更はあったんだと思うんですけども、こういう結果が出たというふうに把握しています。","id":"exchange-008"},{"speaker":"大倉委員","kind":"質問・要望","question":"ぜひその辺は成果というか、調べていただいたほうがいいのかなと、これはぜひ調べていただければという要望で終わります。地域性だったり、いろいろあると思うんですが、どういうふうにとらえているのかというのを教えてほしいと求めました。","respondent":"久保田地域活動課長","answer":"会社の説明会とか、大崎第二区民集会所については、そういったところの分析をしています。広く大人数で使いたいというときには、周辺の地域からこちらを利用されるというふうに私どもは認識しています。","id":"exchange-009"},{"speaker":"藤原委員","kind":"質問","question":"４月から９月という形で半年のこういう資料を出してきていると思うんですけれども、例えば１０月から来年の３月までなんていう半年おきにとか、なぜ今の時期にこういう報告を出したのかをまずお伺いします。","respondent":"久保田地域活動課長","answer":"事務事業概要の中でやってあります。３カ月という形ですけれども、廃止等もありますので、この時期に今の施設の利用状況についてご報告をさせていただいたです。","id":"exchange-010"},{"speaker":"藤原委員","kind":"質問","question":"報告してくださって、ありがとうあります。このぐらいを目標にしていれば、みんな同じではないと思うんですけれども、各集会所において利用率の設定というのはしているんか尋ねました。","respondent":"久保田地域活動課長","answer":"大体５割から６割ぐらいですと、集会所の利用としてはおおむね６割ぐらいがいいのかなと、何かあったときに地域の方がちょっと利用したいというときにも使えるというような数字かなというふうには認識しています。","id":"exchange-011"},{"speaker":"藤原委員","kind":"質問","question":"今説明を伺って、一概には言えないけどという意味において、地域の人が使うためには６割ぐらいがいいんですよという答弁がありましたよね。極端に少ない利用率１２.３％というのは置いといて、地域の人が借りられる６割ぐらいまでに下げとかなきゃいけないという考えもあるんか尋ねました。","respondent":"久保田地域活動課長","answer":"高いものを下げなきゃいけないという考えはございませんで、高いものはそれだけ利用していただいているです。６割程度ですと、そういったことにも柔軟に対応できますので、６割程度でもいいのかなというふうなことでご説明させていただいたところです。","id":"exchange-012"},{"speaker":"藤原委員","kind":"質問","question":"そうすると、ちょっと業種は、シティホテルとかはそうじゃないですか。だから、区としては６割ぐらいがちょうどいいんじゃないかという考えがあるわけですから、上げるという努力はあまりしない方向でいるんですよね。","respondent":"久保田地域活動課長","answer":"すみません、ちょっと私の説明が足りませんでした。そういった評価をしているということのご説明、我々としては６割程度であれば、それが困るということではないです。","id":"exchange-013"},{"speaker":"本多委員","kind":"質問","question":"月に４回借りている町会が、４×１２で４８減るわけですから、大体減っていますよね。多分、町会会館は相当な要因の一つだと思いますので、その辺はいかがか尋ねました。","respondent":"久保田地域活動課長","answer":"例えばある年間に１０個、２０個の会館ができているというところでもございませんので、そういった要因は含まれているとは思っています。その辺のものについても、私どもももう少しというか、もっときちっと精査をして、分析をしていかなければならないというふうに思っておりま…","id":"exchange-014"},{"speaker":"本多委員","kind":"意見","question":"それと、八潮がどうしても利用率が横ばいなんですが、その辺の何か工夫というか、ないのかなと、ちょっと一つだけ取り上げるというのもあれなんですが、八潮について、この横ばいの数字はどうとらえていますかとの意見を述べました。","respondent":"久保田地域活動課長","answer":"なかなか外部から、例えば荏原地区とか、ほかの地区からは利用されない状況があるです。大井第一地区のほうからの利用というようなことで、こうした中で、利用率は大体横ばいの推移になるのかなというふうに思っているところです。","id":"exchange-015"},{"speaker":"石田（ち）委員","kind":"意見","question":"ほかの委員からもありましたけれども、区も利用してもらうように努力してきたということなので、そういった細かい資料もあるといいなと思いました。こうしていこうかというようなものというのは開かれているのか、開かれていれば…","respondent":"久保田地域活動課長","answer":"この利用率が低い施設を検討する会議というものですけれども、何とか検討会議というもので設置はしてございません。これは地域活動課が主管ですので、地域活動課の中で所管する私どもが主体的に検討して、分析しながら検討しています。","id":"exchange-016"},{"speaker":"石田（ち）委員","kind":"質問","question":"そうすると、集会所からの、毎日見ていくということは難しいと思うんですけど、報告なんかを受けているということなんか尋ねました。","respondent":"久保田地域活動課長","answer":"利用実績等につきましては、毎月集計をしていますので、各施設から報告は上がってきてあります。","id":"exchange-017"},{"speaker":"石田（ち）委員","kind":"質問","question":"利用率以外に何かこういった声が多いとか、こうしてほしいという区民の声があるということなんかもあわせて報告されているんか尋ねました。","respondent":"久保田地域活動課長","answer":"各施設において、そういった声があれば、きちんと地域活動課に報告していただいてあります。","id":"exchange-018"},{"speaker":"石田（ち）委員","kind":"質問","question":"使いやすくしていくという改善、そういった問題視しながら進めていくとさっきおっしゃっていたんですけれども、そういった観点での進め方もしていらっしゃるんか尋ねました。","respondent":"久保田地域活動課長","answer":"なかなか難しいところはあろうかと思いますけれども、もうちょっと広い範囲で、面でとらえて検討をしているということはあります。地域センター等を改修して、地域としては非常に施設の改善等には努めているところで、地域全体としての利用の改善には努めているところです。","id":"exchange-019"},{"speaker":"大倉委員","kind":"質問・要望","question":"ちょっと教えていただきたいんですが、ほとんど変わりないのに７６.２％の利用率になっている、これはどう見たらいいのかちょっと教えていただきたい。","respondent":"久保田地域活動課長","answer":"その分は分母から除きますので、そういう意味では、毎年分母が変わるということでご説明をさせていただいたところです。もう一回確認はします。","id":"exchange-020"},{"speaker":"武内委員","kind":"質問・要望","question":"特に品川第一区民集会所なんかは昭和４５年ということで、そういうものも、あと３年ですからやっていかなきゃいけないんじゃないか。とりあえず、どこを改修しなきゃいけないのか、わかっていれば教えていただきたい。","respondent":"久保田地域活動課長","answer":"こちらは民間のマンションと併設ですので、区単独で耐震化ができないということで、こちらが残っているという状況です。荏原西区民集会所が先ほどご説明しましたように、まだ耐震化が終わっていないです。","id":"exchange-021"},{"speaker":"井上副委員長","kind":"質問","question":"先ほど来の議論の中からお伺いをしたいんですけれども、初めから除いているのかどうかということと、区がやるときは当然免除ということで利用されているのかどうかをお伺いしたいと思います。","respondent":"久保田地域活動課長","answer":"そんなに数がたくさんあるということではないというふうに私はとらえてあります。それと、あと区が使うときは免除と、利用料はないということです。","id":"exchange-022"},{"speaker":"井上副委員長","kind":"質問・要望","question":"やっぱり区が主催をしているというふうに、そこはちょっと別に今度集計を出していただけるときには配慮していただきたいというふうに思うんですね。保育園側の要望とか、今現在どういう声が、ちょっと紹介をいただきたいなと思います。","respondent":"久保田地域活動課長","answer":"具体的に保育園側から、この施設を検討するに当たって、こういう意見があるというような要望は今もらってはございません。関係する部署、あとは保育園が併設していますから保育課とかとは打ち合わせ等を行いながら、今後の方針は検討しています。","id":"exchange-023"}]},{"id":"topic-02","title":"の平成２４年度、協働事業提案制度の審査結果","agenda":"の平成２４年度、協働事業提案制度の審査結果","exchanges":[{"speaker":"武内委員","kind":"意見","question":"２団体からの応募ということですが、もうちょっと何か来なかったのかなという気がちょっとするんですね。その辺をどう感じていらっしゃるかということと、いわゆる何件ぐらいを目指していたのかということとか、その辺の状況をどう認識しているのかとの意見を述べました。","respondent":"今井協働・国際担当課長","answer":"説明会には４団体６人の方にご出席いただきまして、ご説明をしたところですけれども、最終的には２団体となりました。まずは区が提起する課題が１件だったということで、三件区から調整をしまして、主管課である協働・国際担当としては働きかけたいと考えています。","id":"exchange-024"},{"speaker":"武内委員","kind":"質問","question":"防災だけじゃないんでしょうけれども、いろんな連携をかけてきたと思うんですけれども、こういうところにも呼びかけられたりしたんでしょうか。その辺をあわせてお伺いします。","respondent":"今井協働・国際担当課長","answer":"今まで企業との取り組みをしていなかったわけではなくて、町会や企業もあわせた、そういうふうな協議会という形で進めているところです。ただ、継続的な取り組みが少ないということから、企業自体の防災時の存続についてというところに一番関心があったというふうに考えておりま…","id":"exchange-025"},{"speaker":"井上副委員長","kind":"提案","question":"その中で、区民が自由提案をするという項目がなくなったことの周知徹底がどうされてきたのか、３年間自由提案がなかったというところで。どういうふうにこれはなくなって、自由提案というものを活かしきれなかったところの評価というのをどうされているのかということをお伺いしますとの意見を述べま…","respondent":"今井協働・国際担当課長","answer":"区からの課題を提起する事業に今は一本化して実施するということで、平成２３年度から区からの課題１本に変更して実施しているものです。その中では、かつＰＲしていくことで今の段階では区民活動を支援していくというふうに考えております。","id":"exchange-026"},{"speaker":"井上副委員長","kind":"提案","question":"６事業、７事業の自由提案があったというふうに思っているんですが、なかなかそういうほかに進むことができないという制度設計があると思うんですね。ここは進めてほしいと求めましたが、並行して改めてというふうに思いますけど、いかがか尋ねました。","respondent":"今井協働・国際担当課長","answer":"区民活動助成制度は、委員ご指摘のとおり区民の皆様からいただいた寄付金を原資にしまして、自主事業に対して助成をしていくものです。区民の方をパートナーとした事業提案を進めていく、その制度については、来年度実施に向けてまた検討してまいります。","id":"exchange-027"},{"speaker":"井上副委員長","kind":"提案","question":"今回企業に向けてというようなメッセージで提案をしているので、そういう意味では区が投げていく提案についても工夫をしていただいて、これをぜひつくっていただきたいなというふうに要望しますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-028"},{"speaker":"山内委員","kind":"質問","question":"これは、今回我々、委員のためにつくって、これを提出しているんですか。この内容、この理由というもの。","respondent":"今井協働・国際担当課長","answer":"この「採択理由および注意事項」と「理由」につきましては、区民委員会への報告ということではなくて、団体の方々に区として今回の事業に対する採択理由および不採択の理由としてお知らせしているところです。","id":"exchange-029"},{"speaker":"山内委員","kind":"意見","question":"下段の「多くの企業」の下のところとかというのは、「十分に踏まえ」「十分協議し」と、何を言いたいのかがいまいち見えてこないんですよね。専門家ではない我々が、これを見てどうやって理解するのかというのが見えてこないので、ちょっとその辺はちゃんとしてほしいんですけどとの意見を述べました。","respondent":"今井協働・国際担当課長","answer":"ですので、そういうふうな企業との連携なども十分に巻き込んだ上で進めていただきたいというふうな内容が１行目にあります。提案団体は地域に実際に実施していますけれども、事業を進める中でも役割分担といいますか、こちらの説明になります。","id":"exchange-030"},{"speaker":"山内委員","kind":"質問・要望","question":"結局よく何を言っているんですかねというようなことにつながって、私だけかもしれないんですけど、そういうとらえ方をしてしまうんですよね。ですから、もう少しわかりやすい言葉で書いていただけると、今後はありがたいかなと思うので、そのあたりをちょっと要望しておきます。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-031"}]},{"id":"topic-03","title":"の地域と在住外国人との交流事業","agenda":"の地域と在住外国人との交流事業","exchanges":[{"speaker":"武内委員","kind":"質問","question":"そういうことなのか、それともある程度下地ができてきたので、これをさらに友好を進めていくというものなのか。どの辺の今状況なのか説明を求めました。","respondent":"今井協働・国際担当課長","answer":"地域と在住外国人との交流促進につきましては、平成２１年度長期基本計画が実施されたことに伴いまして実施しました。インドの方が区民まつり等に出店したり、３月に私どもがこみゅにてぃぷらざ八潮で実施しました協働のイベントとかにも参加するようになって。","id":"exchange-032"}]},{"id":"topic-04","title":"の区立荏原平塚総合区民会館の予約開始と開館記念式典等","agenda":"の区立荏原平塚総合区民会館の予約開始と開館記念式典等","exchanges":[{"speaker":"武内委員","kind":"質問・要望","question":"例えば全員が区民とか、例えば半分が区民とか、何か定義があったら教えてほしいと求めました。(2)、(3)、その辺はどうなんか尋ねました。","respondent":"安藤文化スポーツ振興課長","answer":"そして、コント５５号をやっていたときに品川区のプロダクションに所属していまして、そんな関係で縁がありましてお願いをしたものです。ですから、文化振興事業団の企画でやってあります。","id":"exchange-033"},{"speaker":"武内委員","kind":"意見","question":"に特別何か持ち出しとかをするんじゃなくて、いわゆる通常のチケット販売の範囲でやってもらうと、こういうことでいいのかどうか。どういう取材をするかわからないんですが、そこと連携してやれないのかなと、また考えているかなということなんですけどとの意見を述べました。","respondent":"安藤文化スポーツ振興課長","answer":"そして２点目は、地域の取材ですが、これから、題材に合わせて地域に入っていって取材をしていくと思います。委員ご指摘のように、せっかくやるところですので、大きく商店街を巻き込んだ地域との連携にしていければというふうに考えてあります。","id":"exchange-034"},{"speaker":"井上副委員長","kind":"質問・要望","question":"１月１１日の広報でというお話だったと思うんですが、わかってもらえるような周知方法を工夫してほしいと求めましたが、これがそのまま載るんか尋ねました。","respondent":"安藤文化スポーツ振興課長","answer":"荏原第二、荏原第三の町会長会議におきまして、同じような形でご説明をさせていただきたいと思っています。そして、１月１１日の広報のご案内についても、区民の皆さんにわかりやすいような形でご報告させていただきたいと思っています。","id":"exchange-035"}]},{"id":"topic-05","title":"の文化センターの改修工事","agenda":"の文化センターの改修工事","exchanges":[{"speaker":"山内委員","kind":"質問","question":"旗の台文化センターと東品川文化センター、非常に古いと思うんですけれども、それぞれ何年の開設か尋ねました。","respondent":"安藤文化スポーツ振興課長","answer":"それから、東品川文化センターは１年おくれて、昭和４７年です。ですから、４０年、４１年ほどたってあります。","id":"exchange-036"},{"speaker":"山内委員","kind":"意見","question":"これは古い建物ですけれども、耐震というのはどうなっているのかとの意見を述べました。","respondent":"安藤文化スポーツ振興課長","answer":"東品川文化センターの耐震につきましては、平成２３年度、これも東京都とあわせて実施済みです。実施設計が平成２２年、改修工事が平成２３年ということで、耐震工事が東品川文化センターについては終わってあります。","id":"exchange-037"},{"speaker":"武内委員","kind":"意見","question":"東品川文化センターとシルバーセンターは、工事中も利用可能ということですね。平成２３年度に耐震工事をやったときに、その辺は一緒にやるという考え方はなかったのか、２点との意見を述べました。","respondent":"安藤文化スポーツ振興課長","answer":"工事の業者の進め方等によっては、１日とか、クローズなしで進めします。どうしてもそれが、耐震と外壁の工事というのは非常に難しいという話がありまして、ずらしたです。","id":"exchange-038"},{"speaker":"武内委員","kind":"意見","question":"予算の出ぐあいとか、いろんな関係で難しかったんだなと思っちゃうんだけど、決してそうじゃないんだと。技術的に難しいということで理解しておきますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-039"},{"speaker":"井上副委員長","kind":"質問","question":"１０月１日からきゅりあんの駐輪場の料金改定等が行われていたようなんですけれども、ちょっとその概要を説明いただけるのであればお願いしたいなというふうに、いかがか尋ねました。","respondent":"安藤文化スポーツ振興課長","answer":"お答えをしたと思いますけれども、大井町再開発ビルも、駐輪場については何とかする方向でずっと検討していたところです。よろしくお願いします。","id":"exchange-040"},{"speaker":"井上副委員長","kind":"質問","question":"区の負担が１６０万円ということなんですけど、大体３,０００名の先着ということで、抽選なのか。では予算の、しながわ観光協会の支出もあったりとか、協賛団体の支出等は区だけなのかどうなのか、改めて、その辺はどうなっているんか尋ねました。","respondent":"米田商業・観光課長","answer":"観光まち歩き事業としては、年に３回行っていただくようになっております。その他、共催団体につきましては、金銭等の拠出を含め、さまざまご協力をいただいているところはあります。","id":"exchange-041"},{"speaker":"井上副委員長","kind":"質問","question":"１００円均一でという商店街のイベントがあって、このままいくというお考えではないということもあったと思いますけれども、その辺の検討の必要というのは改めていかがか尋ねました。","respondent":"米田商業・観光課長","answer":"その次につなげるというような取り組みを、ある商店街では、商店街全域を挙げてやっていこうというような動きもあろうかと思います。その中である種区の負担を減らしていくということにつきましては、今後の検討課題とさせていただければというふうに思っております。","id":"exchange-042"},{"speaker":"山内委員","kind":"意見","question":"すごく細かいことだけど、主催がしながわ観光協会で、なぜ問い合わせが横浜なのかというのがよくわからないんですけれどとの意見を述べました。","respondent":"米田商業・観光課長","answer":"その関係で、場所が横浜にあるものですから、電話番号が横浜になっております。そちらのほうでも十分対応ができるようにということは努めておりますが、第一義的な問い合わせ場所というようなことは東急電鉄です。","id":"exchange-043"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/118408?Template=document&Id=2650#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2012-01-01&TermEnd=2012-12-31"}],"sourceMeta":{"pages":0,"characters":35687,"voices":127}},{"id":"h24-20121105-7","meetingId":"h24-cm11","date":"2012年11月5日","dateIso":"2012-11-05","committee":"厚生委員会","time":"午後１時００分～午後３時３０分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を3件整理しています。","topics":[{"id":"topic-01","title":"区立高齢者住宅入居登録者の募集","agenda":"区立高齢者住宅入居登録者の募集","exchanges":[{"speaker":"石田（秀）委員","kind":"確認","question":"１点だけ確認をさせてください。そうすると、３月３１日までにあいた場合は、予備の今年の登録の人はたくさん待っていらっしゃる方がいるのかなというのだけ説明を求めました。","respondent":"白鳥高齢者いきがい課長","answer":"それから、２人用の世帯用のほうですけれども、こちらの方については１０組、今、待機をしていらっしゃるという状況です。来年３月３１日まで、あきが出た場合には、優先的にこちらの方、待機者の方から入居していただくです。","id":"exchange-001"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"登録そのものがやっぱり大変だというお話もよく伺うんですけれども、現状どういう状況なのか、ご説明ほしいと求めました。いわゆる積み上げ方式というんでしょうかね、その辺についてどういう考え方、伺いたいと思います。","respondent":"白鳥高齢者いきがい課長","answer":"住宅あっ旋等のそちらのほうのご案内もあわせて、ご相談がありましたら、そのような丁寧な説明の仕方をさせていただいているところであります。改めて新年度、４月１日からの順位づけをするという、こういうものです。","id":"exchange-002"},{"speaker":"若林委員","kind":"質問","question":"１点だけ。単身用が２０戸、２人用が１０戸、どういう根拠で設定されたかだけ説明を求めました。","respondent":"白鳥高齢者いきがい課長","answer":"このようなことをやはり考えますと、やはり要支援、要介護の方もいらっしゃいます。このようなことを考え合わせまして、単身用２０戸、２人用１０戸というような設定です。","id":"exchange-003"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/594819?Template=document&Id=3338#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2012-01-01&TermEnd=2012-12-31"}],"sourceMeta":{"pages":0,"characters":4513,"voices":19}},{"id":"h24-20121105-8","meetingId":"h24-cm11","date":"2012年11月5日","dateIso":"2012-11-05","committee":"建設委員会","time":"午後１時００分～午後４時１４分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を49件整理しています。","topics":[{"id":"topic-01","title":"の１、報告事項を行います。 はじめに、(1)木密地域不燃化１０年プロジェクト「特定整備路線」候補区間の全ての区間選定","agenda":"の１、報告事項を行います。 はじめに、(1)木密地域不燃化１０年プロジェクト「特定整備路線」候補区間の全ての区間選定","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"新たな選定ということですけれども、この補助２８号線の計画路線上の建物の棟数ですとか商店街、影響を受ける公共施設、町会がどういうところなのか、ちょっと名前で教えていただきたいんですが。","respondent":"藤田都市計画課長","answer":"その中で、棟数としては約９０棟に関係が出てくるかと考えています。町会としては大井三丁目町会、大井倉田町会、大井滝王子町会の３町会が、関連する町会です。","id":"exchange-001"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"どう考えているのかということと、それからこの１ページに「詳細に整備効果の検証を行い」ということで、どういう中身で検証したのかということを教えてほしいと求めました。","respondent":"藤田都市計画課長","answer":"先ほどおおむねかかる９０棟というお話をさしあげましたけれども、ちょっと具体的な計画線を確認していかないとわからないかなと考えています。そういうような結果になったため、今回の路線が選定されたと、そのように聞いているところです。","id":"exchange-002"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"どういう効果があるということで今回こういう選定になったのかというあたりは、区としてはつかんでいらっしゃるんでしょうか。９０棟とかなり大きな、なぜやるのかというあたりは説明をきちんとできるような形にしていただきたいと思うんですけれど、いかがか尋ねました。","respondent":"藤田都市計画課長","answer":"商店街に与える影響が大きいかどうかというのは、この後ももう少し、さまざまな検証をしていく必要があるのかなと考えています。安心のために補助２９号線、放射２号線と同様に整備を進めていくことが、安心につながると考えているところです。","id":"exchange-003"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そういうところで、やはり区としても車両火災ということを求めていくべきだと思うんですけれども、その点が一つです。その点についてもお聞かせほしいと求めました。","respondent":"藤田都市計画課長","answer":"車両火災については今回の検証の中には入っていないのではないかと、基本的な考え方を聞いている中では、私のほうはそういうふうに考えてあります。私は実際に３・１１のとき、道路を直接見に行ったわけではありませんけれども、相当な渋滞があったと聞いているところです。","id":"exchange-004"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"区のほうでも、この都市計画道路を進めていくわけですから、そういう点ではいろいろと調査の方法というのはあると思うんですね。それが４０カ所にわたる出火という想定もされていますから、この渋滞の状況、その点についてお伺いします。","respondent":"藤田都市計画課長","answer":"それから、現状の道路で、避難ですとか被災したところの消火活動をするのに、今のままでも十分ではないというふうに私どもは考えております。そういう面で考えると、もう一つは渋滞にならないように、それらについて十分計画を立てていく必要があるかと考えております。","id":"exchange-005"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"私もこの間、荏原消防署にお話を伺ってきましたけれど、実際に常時動ける、出動できる消防車は６台だと言われたんですね。その消防力の向上ということを同時に進めないと、そういうことにはならないと思うんですけれど、そこら辺はいかがか尋ねました。","respondent":"藤田都市計画課長","answer":"そういう意味でトータルな面で消火力の強化、これを進めているところです。私の立場で申しますと、どうしても基盤整備の話が中心になってしまいますけれども、区としてはそれらの対策を総合的に進めているところです。","id":"exchange-006"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"３・１１のときに品川区内の幹線道路の渋滞の状況がどうだったのかというのは、区としても把握してほしいという、ぜひ把握をしていただきたい。いかがでしょうかということと、ぜひ説明に来てほしいと言われたら、そのことについて説明を求めました。","respondent":"松代防災まちづくり事業部長、藤田都市計画課長","answer":"基本的に車のさばき、交通等の件に関しては、警視庁が交通管理者として対応するという形になっております。環状７号線から中には入れないということを打ち出しましたし、すぐに区議会… 東京都としては、これまでの繰り返しになりますけれども、生活再建のための支援策が出てきた段階で説明に入りたいということを言ってあります。説明会等をぜひ開いてほしいというようなお話があったとしたら…","id":"exchange-007"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"生活しているわけですから、そこを全く離れる、追い出されることになるのが数千世帯という規模になっていくわけですから。そして、その人たちの暮らしそのものがどういうふうになっていくのかということも合わせて。","respondent":"藤田都市計画課長、片田都市環境事業部長","answer":"ちょっと私の説明の仕方も悪かったのかもしれませんけれど、それに加えて輸送路になる、避難路になるというものです。それから生活再建の支援策は、東京都が検討していますので、そういう支援策は通常の都市計画道路の整備とは違って。 いろいろな支援策という部分で、できるだけ早く沿道の方への支援策というものを今、検討しているですので。そこのところをきちっと私どものほうも確認をしながら、地域の中に正しい情報をできるだけ早く伝えてまいりたいと考えておりま…","id":"exchange-008"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"道路上の人、もう６６年間つくられてこなかったわけですから、されないだろうというような思いのままでずっと来ていると思うんですね。そこのところでぜひ、合意を得られるようなまちづくりを進めていただきたいということで、要望しておきます。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-009"},{"speaker":"沢田委員","kind":"意見","question":"補助２８号線も追加になりまして、補助２９号線と同じような内容で、同じようにそこから説明会ができるような状況が整うのかということを説明を求めました。","respondent":"藤田都市計画課長","answer":"１１月、１２月が第３四半期ですので、そういう大きなくくりの中では変更にはなっていないと考えています。１日でも早く発表ができるように、これからも区のほうとしても東京都に求めてまいりたいと考えています。","id":"exchange-010"},{"speaker":"沢田委員","kind":"確認","question":"建築確認をどうされるのかということとか、補助２９号線のほうの建築確認は現状そういうことでとめているのかということと、その辺の対策というのはどんなお考えか尋ねました。","respondent":"藤田都市計画課長","answer":"その辺の動きについても近々、方向性が示されるという形では聞いてあります。東京都のほうにもそういう情報を流しながら、対応できることがあるのかどうか、その辺については考えていきたいと思ってあります。","id":"exchange-011"},{"speaker":"須藤委員","kind":"質問","question":"何時間か車をとめてどうなるとかいうような状況をつくっていると思うので、遮断帯は遮断帯として意識をしていただければいいと思うので。遮断帯にしますよということはもうできているんですから、率先して動くべきだと思うんですけれど、いかがか尋ねました。","respondent":"藤田都市計画課長","answer":"オール都庁としてはなかなか町場に対しての説明は、先ほど申した生活再建のための支援策がないと、一日でも早く説明ができるようにということで。そういうふうな議会のほうも含めまして、前向きに捉えているところです。","id":"exchange-012"},{"speaker":"須藤委員","kind":"質問","question":"ですから、個別にお話をしていってあげるべきだと思うんですけれども、改めてもう一度。それをやっていると今言い出したんですけれど、きちんとできているかどうか。","respondent":"藤田都市計画課長","answer":"具体的な立ち上げのための説明を前回行いまして、この８日にはそのＰＴの立ち上げも行います。地域センターとかそういったところのメンバーも入れながら具体的な検討を進めて、これについては区のほうとして考えながら、進めているところです。","id":"exchange-013"},{"speaker":"須藤委員","kind":"質問・要望","question":"昭和２１年から計画道路になっているとか、判断できるような、それから説明会できちんと質問ができるような状況をつくってあげていただきたいと。これは改めて要望しておきます。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-014"},{"speaker":"浅野委員","kind":"質問・要望","question":"これが最後の追加分ということで伺っておりますけれども、じゃあ次はどこが来るのかなということで、ある程度の想定というものはあったのかどうか。そこら辺、お話しできる範囲で結構ですので、教えてほしいと求めました。","respondent":"藤田都市計画課長","answer":"そのときの説明の中では、三ツ又の交差点のところから滝王子までですと。東京都から、ここを指定しますというような形での説明があったというものです。","id":"exchange-015"},{"speaker":"浅野委員","kind":"質問","question":"今お伺いしたのはまさにそこの部分で、先がまた細いというんでしょうか、私も非常に気になるなと。もし次の項目ですということであれば次にしますけれど、もしお答えいただけるんだったら教えてほしいと求めました。","respondent":"山崎マスタープラン担当課長","answer":"今回の補助２８号線につきましては、地区別のほうでは大井地区に該当します。整備を推進していくというようなことを加筆したバージョンで、今後のパブリックコメントに対応してまいりたいと考えています。","id":"exchange-016"},{"speaker":"浅野委員","kind":"意見","question":"ぜひとも、都市計画審議会でもいろいろあったと思いますけれども、何とか入れられる方向でお願いしたいと思います。それと、さっきの南側のほうの説明会とかそういうことについて、答弁願いたいと思いますとの意見を述べました。","respondent":"藤田都市計画課長","answer":"皆さんのところは指定しなくても安心なんですよというような形での説明が、必要になってくる場面があるかと思いますので、東京都と十分調整をさせていただきたいと思います。","id":"exchange-017"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"そういうまつりの問題ですとか、町会の活動のやり方、また地域のきずな、そこら辺のところについて、区としてどう考えられているか。それが５分の１ぐらいにわたる町会に影響を与えるということについてはとの意見を述べました。","respondent":"藤田都市計画課長","answer":"補助２９号線、放射２号線、それと本日追加で説明させていただいた補助２８号線の３路線です。６路線と言われているものの中には、区のほうとしてこれから整備を進めていくということで、ちょっと先にその説明をします。","id":"exchange-018"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"合わせて６０メートル、８０メートルということになるわけですから、きずなはそれでは壊されないだろうでは済まされないと思うんですね。私はそこら辺のところもしっかりと目を向けてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-019"}]},{"id":"topic-02","title":"品川区まちづくりマスタープラン（素案）","agenda":"品川区まちづくりマスタープラン（素案）","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"１２０人の定員が満杯になったというのをお聞きしたんですけれど、まだ参加したいという方は、ちょっとお聞かせほしいと求めました。いつから置かれているのか、どの施設に置かれているのか、そのところを教えてほしいと求めました。","respondent":"山崎マスタープラン担当課長","answer":"申し込まれても当日急遽ご都合ができてというようなこともありますので、柔軟にその辺は対応してまいりたいです。区政資料コーナーなどに冊子を置かせていただいて、ごらんになっていただけるような手配を進めて、１１日からということで思っております。","id":"exchange-020"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"いかがでしょうかということと、もうちょっと詳しく教えていただける、説明をしていただけるということはあるんか尋ねました。","respondent":"山崎マスタープラン担当課長","answer":"概要をスライドなどを使って工夫して説明する予定で、そのスライドをコピーした資料編というか、そういうものを来場した方に配布する予定です。広報誌でこれからＰＲしますけれども、そうした問い合わせ先も含めて、きっちり明確にお伝えしてまいりたいという考えでおります。","id":"exchange-021"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そこのところだけでもコピーしてもらいたいという要望には、ぜひ応えていただきたいと思うんですけれども、その点はいかがでしょうか。今回は素案ですけれども、区議会ではなくて都市計画審議会のほうで決定されることになっていくのか、そこら辺の仕組みを説明を求めました。","respondent":"山崎マスタープラン担当課長","answer":"先ほどご説明をしたメーンページ、そうした説明の際には必要な資料をコピー等々、必要であればそういった対応はします。それから区議会のほうにも本日報告をさせていただいて意見を聴取する、こういった仕組み、検討体制で行わせていただいているものです。","id":"exchange-022"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"都市計画審議会とかの機関で決定されるというのではなくて、策定委員会という、そこが決定機関になるということで確認をしていいでしょうか。１２の鉄道駅周辺というところで、2)下神明駅などその他の駅周辺のまちづくりということで、ＪＴ跡地と考えていいんか尋ねました。","respondent":"山崎マスタープラン担当課長","answer":"まず区としての考え方をまとめて、東京都と考えをすり合わせるような、これからしてまいりたいです。ただ、相手があるものでして明確に決まっておりませんので、表現につきましては、マスタープラン上はこうした具体の表現は避けているという状況です。","id":"exchange-023"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"福祉避難所もあわせてあそこにできたら、ぜひそういうふうにしてほしいと求めましたが、その点をお聞かせほしいと求めました。２２９ページの５番の3)のところですが、どこら辺にどういうものを考えられているのかについても、お聞かせほしいと求めました。","respondent":"大串住宅担当課長、山崎マスタープラン担当課長","answer":"都営住宅の関係ですが、都営住宅は基本的に、ご案内のように東京都のほうの設置、運営、管理ということで行っているところです。都営住宅の配置といったものはあくまでも東京都のほうの考えですので… 詳細なものは本編の８９ページのほうに、防災機能拠点の整備検討ということでございまして、まだまだ整備検討という段階です。こうした考えを照らし合わせて検討していくこととするということで…","id":"exchange-024"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"ちょっと教えていただきたいのと、ぜひともなくさないでいただきたいと思うんですけれども、その点お聞かせほしいと求めました。もう一つお聞かせいただきたいのが２１２ページの補助２７号線なんですけれど、そういう見込みとかもありましたら、お聞かせほしいと求めました。","respondent":"山崎マスタープラン担当課長","answer":"東京都のほうで順次、耐震化について計画を立てて実施をしているということでございまして、あるいは予定があるとかという話は聞いてございません。より効果が高まるということが見込まれる部分については、そうした整備も合わせてやってまいりたいというような考えを…","id":"exchange-025"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それとその補助２７号線なんですが、これも木密の防災上の観点から、ほかの路線と同じような目的で整備をしていくという考え方なんでしょうか。あったらどういうことになっているのか、都の路線と基本的には同じ考えでいくのか、そこら辺のところをお聞かせほしいと求めました。","respondent":"山崎マスタープラン担当課長","answer":"計画を立てております地域防災計画などと連携を図りながら検討していくということで、例えば災害対策本部の機能は、区役所に一極集中するわけです。先ほど大井地区のまちづくり方針の２１０ページで、そこについては整備の実現に向けた取り組みなども…","id":"exchange-026"},{"speaker":"浅野委員","kind":"質問","question":"今、屋上に太陽光パネルとかそういうものをつけるようなことも、この中には含まれているのかどうかということを一つお伺いしたいのと。４番のところの東八潮ですね、さらにさらに先のことなのでこのような書き方をされているのか、この２点について説明を求めました。","respondent":"山崎マスタープラン担当課長","answer":"国の運輸政策審議会のほうでも検討を要すべき路線だということで、そうしたエリアで新たな事業の検討ということで、今。そうしたこともあって、利活用方法も検討していく必要があるだろうということで、４番にその記述をさせていただいているような次第です。","id":"exchange-027"},{"speaker":"浅野委員","kind":"質問・要望","question":"５７ページのところ、２００８年までの数字が載っていますけれども、たしか今年の春の時点で２００９年までの数字が出ているかと思うんですね。可能かどうかは別といたしまして、検討しなければならないことはあるかと思いますので、ぜひとも検討してほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-028"},{"speaker":"吉田委員","kind":"質問","question":"このマスタープランの素案自体についてお伺いしたいんですけれど、その辺のご質問に関してはどのようにお答えしていくのか、お聞きしたいです。","respondent":"山崎マスタープラン担当課長","answer":"一番大きな課題と整備方針ということで対応できて、見やすくわかるような概要版というものをつくる予定です。先ほどの地区別方針の、そのような説明をしてご理解をいただけるように、丁寧に努めてまいりたいというように考えております。","id":"exchange-029"},{"speaker":"吉田委員","kind":"質問・要望","question":"例えば、今はわからない、完成予定がわからなかったり、またこれから外とのすり合わせとかあると思うんですよね。は計画が進んでいくに当たって、そのことに関してはどのように周知を、区民の皆さんにしていくのかを教えていただきたいんですが。","respondent":"山崎マスタープラン担当課長","answer":"今後１０年あるいは２０年先を見据えたまちづくりの方向性ですので、このまちづくりの方針に則して、予定はしてございません。ただ１０年、２０年先ですので、予定をしています。","id":"exchange-030"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そこに災害対策基本法の精神をしっかりと明記をして、常にその立場で進めていただきたい。そういう意味からもそれを明記してほしいと思うんですけれど、いかがか尋ねました。","respondent":"山崎マスタープラン担当課長","answer":"要は、ハード整備のための方針です。ただ区民の方の生命、両計画に連携する部分については、現在もそうした連携のもとに双方の計画を策定しているというような状況です。","id":"exchange-031"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"自助・共助・公助ということは書いてあるわけですから、その姿勢を明記していただきたいと、これは強く要望させてほしいと求めました。財産を守る、そういう耐震化というのがまず位置づけられることが重要なのではないかと思うんですけれど、そのお考えについてもいかがか尋ねました。","respondent":"山崎マスタープラン担当課長","answer":"素案の８４ページに、防災まちづくりの整備方針体系図ということでお示ししているものですが、課題が７つありますよということです。スタンドパイプを設置したり、記述していますので、よろしくご理解をお願いいたします。","id":"exchange-032"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"ぜひとも基本的な立場として生命、身体、財産を守るという、その姿勢を貫いていただきたいということからも、ここに明記をしていただきたいということを強く求めたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-033"}]},{"id":"topic-03","title":"の大崎駅周辺地域イベントの開催等","agenda":"の大崎駅周辺地域イベントの開催等","exchanges":[{"speaker":"吉田委員","kind":"質問","question":"特別点灯ということでバレンタインの日にちとちょっとずれているんですけれど、どうしてか尋ねました。","respondent":"溝口都市開発課長","answer":"本来、ご指摘のとおり２月１４日がバレンタインということですが、今回は平日ということなので、よりお客さんに来てもらうために、金曜日から土曜日、日曜日の３日間を点灯するということで考えております。","id":"exchange-034"}]},{"id":"topic-04","title":"環境経営セミナーの開催","agenda":"環境経営セミナーの開催","exchanges":[{"speaker":"浅野委員","kind":"質問","question":"助言者、この方についてはやはりクール・ネット東京からの派遣というんでしょうか、そういうルートで来られるのかどうかということ。それともクール・ネット東京の中から、今回これが適するだろうという形で選ばれたのか、その点について説明を求めました。","respondent":"野呂瀬環境課長","answer":"延長したとしても期間が近々ですので、集まらなくても今現在の約６０事業所で、開催は考えております。講演は２つですけれども、そういうことをしていただきたいということで、環境課のほうからお願いしたところです。","id":"exchange-035"},{"speaker":"沢田委員","kind":"質問","question":"この環境経営セミナーですけれども、区がやっている環境ＩＳＯの助成事業とか、エコアクション２１とか、そういう助成事業との関係というか関連は、どういったことがあるんか尋ねました。","respondent":"野呂瀬環境課長","answer":"区内の事業者を募って講演会とか説明会をやっているところで、切り口は環境経営というか、環境に対して事業者を呼んでということで。ＣＯ２の削減について取り組んでいただきたいということで、事業者に対しての支援の一つというふうな形で、このセミナーは考えているところです。","id":"exchange-036"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"５番目の参加案内を送付された３カ所というのは、それぞれ何点ぐらいずつあったのか説明を求めました。","respondent":"野呂瀬環境課長","answer":"一昨年は８１名の参加ということですので、もちろんダブって昨年も一昨年も来ている人もありますけれども、そういう人に対してというところです。現在５０事業所程度、５１か５２ぐらいですので、大体５０事業所ぐらいです。","id":"exchange-037"}]},{"id":"topic-05","title":"の（仮称）鮫洲入江埋立公園整備工事","agenda":"の（仮称）鮫洲入江埋立公園整備工事","exchanges":[{"speaker":"浅野委員","kind":"質問","question":"犬を連れていってもいいというような話もちょっと伺っているんですけれど、その辺をどうお考えになっているのかということを一点お伺いします。利用状況によってさまざまな使い方もあるのかなと思うんですけれど、この点についてもお伺いします。","respondent":"多並公園課長","answer":"説明会等でもいろいろ皆様のご意見をいただきまして、そのようなところは今後推移を見ながら検討してまいりたいと、そのように考えているところです。都市公園法の設置許可と申しまして、公園施設ですから民間の業者に管理を任せるような形態で…","id":"exchange-038"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"ここの地権者はたしか８０何世帯だったと思うんですけれど、そういうことはないまちになっているのか、その点について説明を求めました。","respondent":"溝口都市開発課長","answer":"権利者数につきましては８８名で、ちょっと詳しい数字がありませんけれど、権利変換で入っているというふうに聞いております。そういったものを活用して、災害時には飲料水として活用するとか、そういった浄化する手押しのポンプといったものも備えている地区になってあります。","id":"exchange-039"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"いろいろな整備になっているというふうには聞いたんですけれど、ここの地域が断水するかどうか、そういうことはわからないでしょうか。今でもまだ販売し切れていない部分があるのか、あるのであればどれぐらいなのか、そこら辺もわかったら教えてほしいと求めました。","respondent":"溝口都市開発課長","answer":"道路整備等周辺道路も行いますので、一緒になって下水道管、そういったことで地区周辺については更新しているというふうに聞いているところです。ただ、民間のそれぞれの権利者の方が、ご都合により分譲でさらに売っているという状況はあるというふうに聞いております。","id":"exchange-040"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"このマンションは３９階建てでしたっけ、かなりの超高層だと思うんですが、長周期地震動に対しての対策というのはどのようにとられていたのか。それと昨年の３・１１でも、揺れというのはどうだったのか、把握されていたら説明を求めました。","respondent":"溝口都市開発課長","answer":"これまでも近辺の再開発事業につきましては当然、建物を建てているというふうに聞いておりますので、対策はとられているというふうに聞いています。３・１１のとき、物が落ちたとかそういったことは特にないというふうに、私のほうは聞いているところです。","id":"exchange-041"},{"speaker":"須藤委員","kind":"質問","question":"危険度が少なくなったよというふうな結果にはなったんだけれど、まちの人たちはどのように考えていらっしゃるのか、そのあたりを教えてください。それから反対運動がいろいろあったとき、どの程度丁寧に説明をされて、その苦労がどうだったのかということも説明を求めました。","respondent":"溝口都市開発課長","answer":"そういった快適な機能空間、また下におりることなく、お住まいの方については非常に快適に住まれているという評価を聞いているところです。そういったものを説明していく中で、そういった形で、説得というのは進めてきたようです。","id":"exchange-042"},{"speaker":"須藤委員","kind":"意見","question":"個人の権利ばかりどうのこうのとか、きずながどうのこうのと言っていると、そういう思いでやはりぶつかっていってもらいたいと思うので。これはお願いですとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-043"},{"speaker":"浅野委員","kind":"質問","question":"この地域の人口というんですか、居住者の人数というのはどのぐらい変化があったのかお伺いしたいのと、その前後についてお伺いできればと思います。","respondent":"溝口都市開発課長","answer":"自治会は、町会に入らず新たに１,０００人規模の人たちが住んでいるような形になりますので、町会組織をつくっているというのが現状です。ただそうでないところにつきましては、開発事業の中ではなるべく町会等に参加していただきたいとか…","id":"exchange-044"},{"speaker":"浅野委員","kind":"意見","question":"人口もこのエリア全体で３,０００人プラスということで、まちとしての活性化、また品川区の活性化につながると考えています。そうならないような、大きな建物の中でのまちづくりも、人のつながりという意味で進めてほしいと求めました。","respondent":"溝口都市開発課長","answer":"改めさせていただきまして、平成２３年度には１万６,０００人、ですから大体４,０００人程度の人口増があったという形の統計データが出ております。申しわけありませんでした。","id":"exchange-045"},{"speaker":"木村委員","kind":"質問","question":"それで、これは高層ビルですから、高さがどれぐらいあるのか。よく鈴木委員が言いますけれど、風害と言うんですか、そういうものは出ているかどうか。","respondent":"溝口都市開発課長","answer":"これまでも再開発事業を説明していく中で、当然計画段階での検証等を行って進めてきておりますので、そういったことは私どもの耳には入っていません。ですから地盤面でいきますと、坂になっていますので一概にはあれですけれど、約１４０メートルの高さになっております。","id":"exchange-046"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"所管事務調査で、建設委員会で建物の耐震化、不燃化のところをやってきたと思うんですけれど、品川区地域防災計画が今度、素案が出されますよね。この委員会として耐震化についての、地域防災計画に反映させてもらうようなまとめというのを…","respondent":"稲川委員長","answer":"最終の閉会中の委員会が２回ありますので、その中である程度の着地点は生み出していかなければいけないという思いでは進めておりますので、当委員会の……。","id":"exchange-047"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"震災対策特別委員会の中では耐震化のことは外して、それ以外のところということで進められてきましたので、耐震化についてはこの建設委員会で。反映させていくようなまとめをするとしたら、この委員会しかないかなと思いますのでとの意見を述べました。","respondent":"稲川委員長","answer":"そのまとめも含めて、ご意見としていただいて、正副で協議しますので。","id":"exchange-048"},{"speaker":"須藤委員","kind":"質問","question":"これは早くわかって、早く判断してくれたと思うんですけれど、実際に５,０００平方メートル以上で、申し込みというのは現実的にあったんですか。そのあたりの対応はどうしたのか。","respondent":"品川防災整備担当課長","answer":"実際に改修、除却等について、現在のところ申し込みをされたところはございません。ただ事前に相談という形で１件来ておりまして、その方については、今後丁重にこのことを説明しながら、進めていきたいと考えています。","id":"exchange-049"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/142731?Template=document&Id=4056#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2012-01-01&TermEnd=2012-12-31"}],"sourceMeta":{"pages":0,"characters":54109,"voices":152}},{"id":"h24-20121105-9","meetingId":"h24-cm11","date":"2012年11月5日","dateIso":"2012-11-05","committee":"文教委員会","time":"午後１時００分～午後７時１５分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を117件整理しています。","topics":[{"id":"topic-01","title":"の(1)、子ども文化財散策ツアー（新規）の実施","agenda":"の(1)、子ども文化財散策ツアー（新規）の実施","exchanges":[{"speaker":"伊藤委員","kind":"意見","question":"すばらしい取り組みだと思います。１点だけですけれども、品川区の１３地域とか、今後のことについてのお考えをぜひ聞かせてくださいとの意見を述べました。","respondent":"齋藤庶務課長","answer":"主体はあくまで庶務課文化財係で行いました。大井第一地区に限らず、来年度以降はつなげていきたい、子育て支援課と連携しながら広げていきたいというふうに考えております。","id":"exchange-001"},{"speaker":"鶴委員","kind":"確認","question":"今、関連してなんですけれども、今後いろいろな地域でやりますと、これ、予算の関係で１地域ずつという話になるんですかね。その辺の確認と、どういう歴史があるのかなということを知ってもらうためにも、そこで新たないろいろな声とかが出てくるわけですね。","respondent":"齋藤庶務課長","answer":"予算的には、１カ所ですので、来年、荏原地区、特に平塚の碑がありますので、あそこで実施できればなというふうに今のところ考えています。国を愛する心ということでつながっていくと思いますので…","id":"exchange-002"},{"speaker":"阿部委員","kind":"質問","question":"どんどん広がっていけばいいなと思うんですが、２点教えてください。そうすると、複数校あるいは複数回やってもいい事業なのかなと思うんですが、その辺のお考えを説明を求めました。","respondent":"齋藤庶務課長","answer":"すまいるスクールというのも、やはりすまいるスクールという事業の中で取り組みたいというのが私の庶務課長としての思いがありました。時間の制約がありますので、可能な限りポイントを広げてできればいいんですけれども、少しずつ広げていきたいというふうに考えております。","id":"exchange-003"},{"speaker":"阿部委員","kind":"質問","question":"スタートしたばかりですから、また慣れていけば増えていくのかなと、その辺は期待したいと思います。こういう事業にそもそも参加する権利がないというのも、何か寂しいことだなと思うんですが、いかがか尋ねました。","respondent":"齋藤庶務課長","answer":"日程も土曜日の午後ということの実施の事業で、すまいるスクールに通ってくださっている子どもさんたちでないと、なかなか参加し難い。ただ、今後の参加の募り方については、ご提案もありましたので、どういった方法がいいかはちょっと考えします。","id":"exchange-004"},{"speaker":"南委員","kind":"質問","question":"いろいろと工夫していけば、十分にすべての子どもを対象にできるのではないかなと思います。こういう企画をしたことの返し方というんですか、どういう成果があって、その辺はどういうふうに考えているのか。","respondent":"齋藤庶務課長","answer":"２点いただいた質問のうちの二つ目、指導員のほうから話があってということで、参加したいわという声もあったと聞いております。事故があったときの対応、９人も勝島運河倶楽部の方に来ていただいて対応していますけれども、それは今後の検討課題にさせていただきたいと思います。","id":"exchange-005"},{"speaker":"南委員","kind":"質問・要望","question":"どういうふうに自分は感じたとかということも含めて、後々にいろいろな参考になるような、ぜひそれもやってほしいと求めました。今説明を伺っていたんですけれども、それはそれとして大事にしていただきたいなというふうに思いますので、よろしくお願いしたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-006"},{"speaker":"高橋委員","kind":"確認","question":"そこの確認と、万が一あれだとあると思うんですけれども、その辺について。","respondent":"齋藤庶務課長","answer":"登録時当初に６５０円ご負担いただいて保険に入っていただいていますが、すまいるスクールの事業活動に伴うものということで整理していますので、外に出て授業を行って何か事故が起きた場合には、保険の対象になるです。","id":"exchange-007"},{"speaker":"渡部副委員長","kind":"確認","question":"子ども未来事業部のほう、すまいるスクールを見ている子ども未来事業部のほうが事業主体になっていくのか、そこだけ一つ確認させてください。","respondent":"齋藤庶務課長","answer":"できれば、すまいるスクールのほうを対象として実施したいというふうに考えております。勉強しながら検討させていただきたいと思っています。","id":"exchange-008"},{"speaker":"南委員","kind":"確認","question":"そのあたりはどうだったのかというのが１点と、安心だということで確認されて実施したんだろうというふうには思うんですけれども、それも聞きたいと思います。","respondent":"和氣学務課長","answer":"７年生１４校となっていますが、東海中学校はそもそも８年生で移動教室を実施していますので、このために７年生は１４校という形になっております。従来から東海は７年生ではなくて８年生で移動教室を実施しているです。","id":"exchange-009"},{"speaker":"南委員","kind":"質問","question":"口に出して言えないというか、言いにくい雰囲気があるとか、そういうふうなことも聞くわけですね。どういう形で、どういうふうに提供されたのか、そこもちょっとあわせて説明を求めました。","respondent":"和氣学務課長","answer":"基本的に学校は行く際に説明会を開きますので、その中で線量等についてもご説明を差し上げて、やはり個別に私どもにもお問い合わせがありますので、その際には、私どもがきちんと測った線量についてお知らせをして、その上でご判断いただきたいということで回答しています。","id":"exchange-010"},{"speaker":"南委員","kind":"質問","question":"大丈夫だったという判断で、そういう具体的な数値も示したわけですよね。その上で心配で参加を見合わせたという方はいたのかどうか、そこだけ最後に伺って終わりにしたいと思います。","respondent":"和氣学務課長","answer":"数名程度だという話は聞いてあります。ただ、はっきりとそれが理由でというよりも、今回は欠席しますということで聞いてあります。","id":"exchange-011"},{"speaker":"伊藤委員","kind":"確認","question":"やはり磐梯高原に行けない理由もわかるんだけれども、それを教育委員会としてこれからどういうふうに考えていくんですか。やはりそのことを確認しておかないと、施策に合致していくと思うんだけれども、教育委員会の考え方をぜひ説明を求めました。","respondent":"和氣学務課長","answer":"磐梯高原は、私自身も今年行かせていただきまして、線量を測ってまいりました。総合的にまだ考える点もありますけれども、私どもとしては、その際にももう一度改めて私どもで安全を確認した上で認めてまいりたいという考えです。","id":"exchange-012"},{"speaker":"伊藤委員","kind":"質問","question":"今、お考えを聞きましたけれども、ぜひ検討してくださるようお願いしておきます。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-013"},{"speaker":"大西委員","kind":"質問","question":"これ、非常に私は外に出て宿泊を伴うことで、子どもたちにとってはよい経験になると思いますけれども、子どもたちからのこのことに対する反応というんですか、そういったものについてはどのように捉えておられますか。","respondent":"和氣学務課長","answer":"子どもたちは非常にこれを楽しみにしてございまして、宿泊行事というのは子どもにとって学校生活の中でもかなり大きな思い出に残る部分でございまして、今回につきましても、ほぼ満足していただいている、子どもたちも満足しているという声を聞いているところです。","id":"exchange-014"},{"speaker":"大西委員","kind":"質問","question":"３泊、１泊と違うような状況のものもあるように感じているんですけれども、この辺の掌握と実態はどのようになっているかちょっと教えていただけますか。","respondent":"和氣学務課長","answer":"基本はこの移動教室が中止、あとは、夏、夏期施設が中心ですが、一部の学校で冬に実施している学校があります。今年度予定しているのは５校ございまして、基本的にすべて日光光林荘に泊まって冬の体験をするです。","id":"exchange-015"},{"speaker":"大西委員","kind":"質問","question":"先ほどの一つ目の質問で、教育委員会のほうでこれを推進するんではないかと思うんですけれども、その辺はどうか尋ねました。","respondent":"和氣学務課長","answer":"それぞれの学校で年間行事、さまざまな形で子どもたちにとっての楽しいこともあれば、子どもたちに必要なことも含めて実施しております。それぞれの学校の子どもたちの様子を見ながらご判断をいただいているところです。","id":"exchange-016"},{"speaker":"大西委員","kind":"質問・要望","question":"１泊から、１泊から始まったものを、保護者が非常にいいということから２泊につながっていったということを聞いております。少し要望として申し上げておきますけれども、教育委員会として、推進のほうを要望として申し上げておきます。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-017"},{"speaker":"阿部委員","kind":"質問・要望","question":"例年と比べてどうであったのか、多かったか少なかったかという、どのくらいであったかということ確認させてください。いや、そういうものは今年はなかったとか、そういった状況をちょっと教えてほしいと求めました。","respondent":"和氣学務課長","answer":"ですから、今年も２回なり３回行ってありますので、そのたびに測ってきているということで確認をさせていただいています。誤解がないように。","id":"exchange-018"},{"speaker":"南委員","kind":"質問・要望","question":"私、先ほど、質問し切れなかったんですけれども、調査をして放射線量を測ったということなんですが、具体的にどの程度の数値だったのか、問題ないということで終わってしまったんですけれども、具体的な数値を教えてほしいと求めました。","respondent":"和氣学務課長","answer":"地点によって違いますけれども、私ども区の基準である年間０.０２３に達しない数字、すべての場所がそういう数値です。ですから、０.０１９であるとか、その程度の数値です。","id":"exchange-019"},{"speaker":"南委員","kind":"確認","question":"年度初め、年度途中、そして何回か測っているそのすべてが０.０２３以下だったというふうに確認していいんか尋ねました。","respondent":"和氣学務課長","answer":"ご指摘のとおりです。","id":"exchange-020"}]},{"id":"topic-02","title":"の平成２４年特別区人事委員会勧告の概要","agenda":"の平成２４年特別区人事委員会勧告の概要","exchanges":[{"speaker":"南委員","kind":"確認","question":"ちょっとその辺を改めて確認したいと思うんですけれども、私はとりわけ、非常に大事なのではないかなというふうに実感しています。そういう事例があるのではないかというふうに思っているんですけれども、そのあたりはいかがなんか尋ねました。","respondent":"齋藤庶務課長","answer":"学校に実施を徹底するように指導を行っておりまして、９９.６％、ほぼ１００％の教職員は健康診断を受けております。これもよそでは岡山県や石川県の県レベルでやっているものを区レベルで実施しております。","id":"exchange-021"},{"speaker":"南委員","kind":"質問","question":"その辺についての見解はどうなんですか。がんは含むとはおっしゃっても、そういう状況をどういうふうに区としては、教育委員会は見ているのかというところをもう一度伺いたいと思います。","respondent":"齋藤庶務課長","answer":"５人、０.４％、民間も含めてこの発症率というのは高いものではありません。仕事量が多い、事務量が多いということではないということは、改めて認識をお願いいたします。","id":"exchange-022"},{"speaker":"南委員","kind":"質問・要望","question":"ですから、ぜひその辺は、ないというふうに言い切らないで、きちんと手当てをするべきだと思います。その辺は要望として受けとめてほしいと求めました。","respondent":"田村教育次長","answer":"あるいは過重労働というものを検討していますので、ご存じだと思いますが、中身が労使合意なんですね。ここで説明するのに個人情報の最たるものですからお話しできないですけれども、東京都の共済のほうでは健診のときに２年前からやっているんですね。","id":"exchange-023"},{"speaker":"南委員","kind":"質問・要望","question":"８年あたりからですか、４０代男性の先生、そういう状況があるわけですよね。やはりそれは事実ですから、職員の方々の健康管理の問題だとか取り上げて、しっかりと健康管理をしてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-024"},{"speaker":"伊藤委員","kind":"確認","question":"確認したいのが、いわゆる品川区の教職員の人数は、今、全体で何名いるのでしょうか。平成２２年度が４名であると報告されたんですけれども、どうも数字が一人歩きするので、全体の教員数を改めて説明を求めました。","respondent":"齋藤庶務課長","answer":"平成２１年度からです。今現在、教員の数が１,００７人、都費も含めて、都費負担のケースワーカーが７７人、平成２４年度は合計１,０８４人です。","id":"exchange-025"},{"speaker":"伊藤委員","kind":"意見","question":"そういう数字をとらまえていくと、決してこれだけが突出していると私は思わないです。そういうことは私は踏襲したことではないと思うんだけれども、今の含めて、改めて教育委員会の見解をお願いいたしますとの意見を述べました。","respondent":"齋藤庶務課長","answer":"委員ご指摘のとおり、繰り返しそのことをご答弁申し上げておりますが、なかなかご理解いただけないのは残念です。","id":"exchange-026"},{"speaker":"伊藤委員","kind":"意見","question":"私たち一人一人は、問題はそれをきちんとフォローできるシステムがあるかどうかということのほうが、私は影響するんだと思う。ここで大切なことは、そういう教職員個々の健康管理の意識の向上をどう促していくかということと、改めて教育委員会の見解をお願いいたしますとの意見を述べました。","respondent":"齋藤庶務課長","answer":"引き続き健康診断の充実、メンタルヘルス面でのチェックの仕組み、産業医につなげて、一人でも多くの方を関係医療機関につなげていく、こういった取り組みを続けてまいりたいと思います。","id":"exchange-027"},{"speaker":"伊藤委員","kind":"意見","question":"要は、学校現場もそうだけれども、すべての職員の方々が安心して働ける品川区をつくっていっていただきますようにお願いしておきますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-028"},{"speaker":"阿部委員","kind":"質問・要望","question":"ちょっと数字を確認させていただきたいんですけれども、最初のご説明の中で幼稚園教諭計３４人中１０人が管理職ということでよろしいですか。保育課長がいらっしゃるので、保育園は保育士は何人ぐらいで、そのうち管理職は何人いるんか尋ねました。","respondent":"立川保育課長","answer":"保育園につきましては、今、数字はないんですけれども、現在、大体７００名、管理職はゼロ。","id":"exchange-029"},{"speaker":"阿部委員","kind":"確認","question":"この話はこれ以上突っ込むとちょっと話が長くなってしまいますので、それだけの確認です。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-030"},{"speaker":"阿部委員","kind":"質問","question":"今回の選考から日程をずらしたかなと思うんですが、ちょっと参考までに、前回、前々回の候補者の全体数を教えてください。それから、今回の受験者数の中で、新卒と、現職の方も今回はいらしたんですが、内訳を教えてほしいと求めました。","respondent":"太田指導課長","answer":"昨年度は、第一次選考が８月２８日、第二次選考が１０月２日、そして最終面接が１１月１５日で、こういった日程で行われております。選考状況につきましては、今年度、最終的に内定６名のうちですけれども、経験者が３名、一般の受験が３名というような内訳です。","id":"exchange-031"},{"speaker":"阿部委員","kind":"質問・要望","question":"今回、申込者と受験者数ともに、かなり減少の変化になったと思うんですけれども、その辺は教育委員会としてどのように捉えていらっしゃるか。辞退者はどのような理由で辞退されたのか、わかれば教えていただきたい。","respondent":"太田指導課長","answer":"そして第一次受験者が４９名、最終合格者が６名ということで８.２倍ということで、実質的な倍率はここ３年あまり変わっておりません。他の自治体の採用試験も合格しているということで、品川区と悩んだんだけれども、そちらのほうの採用に行くということでの辞退が１名出たです。","id":"exchange-032"},{"speaker":"阿部委員","kind":"質問","question":"私、今後このような理由で結果がさらに減るということはないと考えていいのでしょうか。要は、２回、３回と機会があれば、いろいろ受けられると思うんですけれども、そうした時期はもう終わっていて、ほぼこの６人は確定か尋ねました。","respondent":"太田指導課長","answer":"今のところはそういうふうに考えております。","id":"exchange-033"},{"speaker":"伊藤委員","kind":"質問・要望","question":"今聞いたと思うんですが、改めて、区の固有教員の採用する上限、ここまで、先ほどおっしゃいましたよね。その計画を改めて伺わせていただきたいのと、その先生たちをどういうふうに学校に配置をしていくか、改めてそのお考えを聞かせてください。","respondent":"太田指導課長","answer":"配置につきましては、それぞれ品川区が推進している小中一貫教育を進めるに当たって、適正に配置をしてまいりたいと。学校の力を上げるといいますか、そういうために区の固有教員を活かしていけるように適正配置をしていきたいというふうに考えております。","id":"exchange-034"},{"speaker":"伊藤委員","kind":"質問・要望","question":"より品川区のことを理解していただいて、さまざまな教育改革をすすめていただきたいと思ってされていたと思うんです。区固有教員の方々に対してこんなことをお願いしていきたいとか、そういうようなものもすごくあると思うので、そういうことを説明を求めました。","respondent":"太田指導課長","answer":"そういったような形で、区の核となって働いていくような教員として育成していきたいと考えております。今年度より区の独自教員、区の固有教員としての誇りとか、そういったことについても持たせるような形で研修を進めているところです。","id":"exchange-035"},{"speaker":"伊藤委員","kind":"質問・要望","question":"この方々はまさに品川区の税金だけで採用しているわけですから、ある意味、区民の皆さんの希望に的確にこたえていくことをだれも願われるはずです。品川区の教育改革を進めていくまさに原動力となっていただくような教員に育てていただきたいということをお願いいたします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-036"},{"speaker":"南委員","kind":"質問","question":"区費で採用した教員も都費の教員も同じ子どもを教育するいわゆる教師という役割ですよね。全然違いはないというふうに思うんですけれども、その辺についての認識をまず伺いたいと思います。","respondent":"太田指導課長","answer":"全くかわりはございませんけれども、一つ、都の教員はおおむね６年程度で区から離れるということがありますけれども、区の固有教員はそういうことがございません。","id":"exchange-037"},{"speaker":"南委員","kind":"確認","question":"そうすると、今でも１年生から中学３年生、いわゆる９年生までは、その学年に応じたカリキュラムに基づいて教育指導を行うということですよね。６年たったら別の場所に行く行かないは全然別として、都費であろうと同じだということだというふうに思うんですけれども、その確認。","respondent":"太田指導課長","answer":"そのとおりです。","id":"exchange-038"},{"speaker":"南委員","kind":"意見","question":"設定をした、何を目的にそういう研修を設定しているのか、その辺を知りたいと思いますとの意見を述べました。","respondent":"太田指導課長","answer":"まさに先ほどお話があったように、区固有教員は区民の方々の血税で給料が支払われておりますので、その教員たちに区として研修するのは当然でありますし、また、都の教員は、都での研修がありますので、そういった形でやっております。","id":"exchange-039"},{"speaker":"南委員","kind":"質問","question":"そうすると、区の職員は都の行う研修には参加できないんですか。どういう目的でそういう研修を設定しているのか、そのあたりを知りたいんですけれども。","respondent":"太田指導課長","answer":"そういったような研修を行うのは、ある意味、必要で当然かというふうに考えています。","id":"exchange-040"},{"speaker":"南委員","kind":"確認","question":"私は、さっきも確認したように、都費の教員だろうと、区費の教員だろうと、やる仕事は同じですよね。なぜ区費の教員だけ、そういうものを教えて、都の教員にはそういうことを教える必要はないというふうに考えているんか尋ねました。","respondent":"田村教育次長","answer":"先ほど申し上げたように、中核になって品川区の教育を担ってもらうということで、改めて横のつながりも含めて研修を実施する。副校長、その辺の若手のころから横のつながりを持って中核として活躍してほしい、そういう思いから研修を実施しているものです。","id":"exchange-041"},{"speaker":"南委員","kind":"質問","question":"品川区の教育を実践してもらいたいのであれば、同じようにやればいいではないですか。私はむしろやめるべきだというふうに思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-042"},{"speaker":"渡部副委員長","kind":"質問・要望","question":"いろいろやはり品川区に就職をいただいたわけですから、当然区のこともわかっていただかなければならない。こういう機会ですから、これからまた５名の方が入られる、新たに品川区に来ようとされている方に呼びかけをされていた。","respondent":"太田指導課長","answer":"そういったところ、今少しずつやはりそうやって、その先生たちの顔が各学校で見えつつあるときではないかなというふうに思っております。そういったところに非常にメリットを感じているところです。","id":"exchange-043"},{"speaker":"渡部副委員長","kind":"質問・要望","question":"これはいいことですし、何か３０年に向けて、また今まで入ってこられた方が出ていってしまうことがないように頑張っていってほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-044"},{"speaker":"阿部委員","kind":"確認","question":"１点だけ確認させてください。固有教員の方、いろいろな形で都費の教員と同じような機会を与えられていたと思うんですけれども、管理職登用についてはどうなっていたんか尋ねました。","respondent":"太田指導課長","answer":"それから教員と管理職をつなぐような役割の主幹教諭、そこまでは今、都と同じように承認していける制度が区内にもできております。今後、副校長、校長というようなところで道を目指せるように制度をつくっていかなければいけないというふうに考えております。","id":"exchange-045"},{"speaker":"阿部委員","kind":"質問","question":"今、この区費の方の一番経験の長い方といいますか、年齢の高い方はお幾つぐらいの方なんか尋ねました。","respondent":"太田指導課長","answer":"４５歳です。","id":"exchange-046"},{"speaker":"阿部委員","kind":"意見","question":"４５歳となると、もし検討について、何かもう少し踏み込んで説明していただければありがたいとの意見を述べました。","respondent":"田村教育次長","answer":"平成２４年、教員の方は４５歳の方が今年主幹になったということなので、やはり大きな課題なのかなというふうに考えています。","id":"exchange-047"},{"speaker":"高橋委員","kind":"意見","question":"算数、先生方がなかなか教えにくいというのがあって、そういうことに対応するために模擬授業を二次選考でやっている自治体もあります。模擬授業の、わずかな時間でもそういった模擬授業を面接の中に、今後その点についてどう検討されているかとの意見を述べました。","respondent":"太田指導課長","answer":"子どもに対してどういうふうに対応する力があるかとか、そういったようなことがあらわれるような、そういった集団面接を行ってやっておるところです。考え方であるとか、そういったことを見たいということで、そういった形の集団面接を今年度行ったところです。","id":"exchange-048"},{"speaker":"高橋委員","kind":"質問・要望","question":"当然すぐ４月から授業をやるわけですので、その点について今後検討の中に入れていただくかどうか検討していただければということで、要望で。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-049"}]},{"id":"topic-03","title":"のいじめ等の調査状況","agenda":"のいじめ等の調査状況","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"委員長、その前に、これだけの分厚い資料が今配られたんですけれども、でき上がったのはいつだったんでしょうか。そのあたりのことをちょっと説明していただきたいのと、それは配られるのかどうかということと、そのあたりを。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-050"},{"speaker":"南委員","kind":"質問","question":"私は、できるだけ早く手元にいただきたかったと、こういうふうに思います。それで、今度は教育委員会に伺いたいんですけれども、これができ上がったのは、何月何日の何時ごろだったのか、少なくとも……。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-051"},{"speaker":"南委員","kind":"質問・要望","question":"最初に聞きたいです。そこも答弁していただきたい。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-052"},{"speaker":"南委員","kind":"意見","question":"では、そこもお願いしたいということをお願いしますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-053"},{"speaker":"伊藤委員","kind":"質問・要望","question":"何点かお伺いさせていただきたいのですが、だけれども、ご遺族の意向を品川区としてどういうふうに考えていらっしゃるのか。さまざまな想いがあると思われますが、まずやはり確認したいのが、ご遺族は今後のこと等についてどういうようなお考えをお持ちなんか尋ねました。","respondent":"太田指導課長","answer":"ご遺族の意向、そういったことを明らかにしてほしいというようなことがまずございまして、いろいろそういったことに我々も対応してきたところです。広く品川区の全体の中で、こういったいじめ、そういったことがなくなるようにというのがご意向です。","id":"exchange-054"},{"speaker":"伊藤委員","kind":"質問・要望","question":"品川区教育委員会としてこんなことをぜひやっていただきたいとか、頭を下げましたけれども、それはある意味許されないことと私は思うわけなんです。だから、確認したいのは、ご遺族がこれからどういうことを望んでおられるかということをぜひお伺いしたいんです。","respondent":"田村教育次長","answer":"説明の中に、２点目でお話ししたように、真実を可能な限り明らかにしてほしいというご遺族の考え方です。少年法の妥当性の考え方も、また新たな検討組織を設ける場合には、ぜひ申し送りしてほしい。","id":"exchange-055"},{"speaker":"伊藤委員","kind":"確認","question":"それから１０月３１日、１１月２日、初めてこの報告書をいただいたんです。ただ、記事に書かれていることもそれとしてありますので、そのことについての事実確認をお願いしたいと思います。","respondent":"太田指導課長","answer":"この一連のマスコミに対する対応につきましては、私、指導課長が窓口一本ということで対応してまいりました。その際、ここに書かれているような内容、委員会の審議内容、審議日程等も含めてですが、私の口から申し上げたことはございません。","id":"exchange-056"},{"speaker":"伊藤委員","kind":"質問・要望","question":"ですから、やはりそのことについての情報管理といったらいいんですか、特にこれは非常に重要な話ですから。情報の管理について。","respondent":"太田指導課長","answer":"委員のおっしゃるとおりでございまして、特にこういったような内容につきまして、情報管理については、電子、それから文書等も含めまして、これからも徹底してまいりたいというふうに思っております。","id":"exchange-057"},{"speaker":"伊藤委員","kind":"確認","question":"入学から半年間続いたこのいじめが、自殺へつながったと判断したということはすべての新聞に、これが１１月２日です。これがやはり問題だということは指摘をせざるを得ませんので、これ以上やってもあれでしょうけれども、この点だけ確認をお願いします。","respondent":"田村教育次長","answer":"既にこの案件については３回非公開で実施しておりますが、決して審議内容が漏れたり、聞かれるような状況は一切ない形で審議を進めてまいったです。接触も含めて把握した上でマスコミ対応して…","id":"exchange-058"},{"speaker":"伊藤委員","kind":"確認","question":"だけど、確認したいのが、そういう認識でいたんですか。やはりこのことは確認しておかなければならないでしょう。","respondent":"太田指導課長","answer":"今回、当該校の担任及びその他の教員も含めまして、そういったような指摘されているような状況であるということは自覚しておりませんでした。今回ここで初めて指摘されて突きつけられているという状況です。","id":"exchange-059"},{"speaker":"伊藤委員","kind":"質問","question":"大変なことが起こってしまったわけだから。これからどうするかということについてやはり考えていくと、それから、これを教育委員会はどうしていくのかということをぜひお伺いしたいんですが。","respondent":"太田指導課長","answer":"そういったところで、実際のところ、この報告書で具体的にいろいろな対策等もご提言いただいております。要は、それがどのように学校で行われているのか、このご提言が本当に形だけにならないように真摯に対応してまいりたいというように考えております。","id":"exchange-060"},{"speaker":"伊藤委員","kind":"質問","question":"つまり、Ａ君のことも含めて、さまざまな関係する子どもたちがいるわけではないですか。そういう子どもたちの家庭状況を把握した上で指導を一体的にしていくことを、されていたんか尋ねました。","respondent":"太田指導課長","answer":"家庭訪問についてはしておりませんでした。今までも学校等いろいろ、三者面談であるとか、そういったことにもいろいろ状況に応じて対応してきているところですけれども。","id":"exchange-061"},{"speaker":"伊藤委員","kind":"質問","question":"というふうに一体的な視点からこの問題がいつまでたっても言葉で終わってしまうような気がしてならないんです。ですから、改めてこういう一体的な指導の中の一環として、家庭訪問について説明を求めました。","respondent":"太田指導課長、田村教育次長","answer":"子どもがどういう家庭で生活しているか、状況を知るということは生徒理解の一つの非常に大切なことだと思いますので、家庭訪問……。 そういうような疑わしきは消さないと、あるいは継続していく、考えていくというような意識を学校全体に持つということがすごく重要だと思います。保護者との連携を強めながら、再発防止に努めていくということも大変重要な観点だと…","id":"exchange-062"},{"speaker":"伊藤委員","kind":"質問","question":"そういう加害児童・生徒に対するフォローと言ったらいいでしょうか、逆にそのことによって、今度はまた別な形でいじめが発生する可能性がある。だから、指導というのは大切な要素となってくると思うんですけれども、そのことについての見解を説明を求めました。","respondent":"太田指導課長","answer":"統括指導主事、指導主事も学校訪問をして、その様子の把握にも努めております。例えば、そういった具体的な策を練りながら、そういった子どもたちにも対応していきたいと考えています。","id":"exchange-063"},{"speaker":"伊藤委員","kind":"質問・要望","question":"やってほしいのだけれども、心の中を見ると言ったらいいんでしょうか、突き詰めてそこに行くと私は思うんです。ですから、把握をしていく、スクールカウンセラーを派遣して拡げていく。","respondent":"太田指導課長","answer":"やはり子どもに対して教員が必ずいじめに対して見逃さないぞという、そういったような意識を育てることも必要かなというふうに思っております。システムだけでもだめですし、意識だけでもだめなので…","id":"exchange-064"},{"speaker":"伊藤委員","kind":"質問・要望","question":"やはりそのことはもう思いは伝わっていると思いますので、常に対処していっていただきたいとお願いしておきます。それから、今度は、いじめ防止に関する手引書の扱いは、これからどうされていくんですかということの確認だけお願いいたします。","respondent":"太田指導課長","answer":"この品川区のいじめ防止の対策の一つの大きな形でありますので、あれをいかに教員の中に浸透させていくかというようなところに、研修等も含めて力を注いでいきたいというふうに思っております。","id":"exchange-065"},{"speaker":"伊藤委員","kind":"意見","question":"せっかく手引書を、８月２０日に文教委員会でご報告いただいていましたから、今後は十分に活用していっていただきますように徹底をお願いします。議会がどんなに頑張っても…","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-066"},{"speaker":"南委員","kind":"質問・要望","question":"３６ページのところ、見落としてしまう、そういうことにやはりなって繰り返されてしまうのではないかということを感じます。ＣＡＰをやれだとか、そういうことでは私は決して根本的な解決にならないと思いますけれども、その辺の見解はいかがか尋ねました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-067"},{"speaker":"南委員","kind":"質問・要望","question":"その辺についての分析は教育委員会としてどのように見ているのでしょうか。ぜひまとめて伺いたいと思います。","respondent":"太田指導課長","answer":"調査対策委員会でまとめたものを私どもが報告を受け、さらに私どもが文教委員会に報告をしていると、そういうことです。ですから、この中身については、ますは調査対策委員会でご検討いただいたその内容ですので、そこを押さえていただければなと考えています。","id":"exchange-068"},{"speaker":"南委員","kind":"質問","question":"教育委員会がこれを受けて、しかも事務局を教育委員会が担っていたわけですから、その間の検討の推移というのは当然把握しているわけでしょう。そこがされていなかったのか、していたのか、ちょっとそこだけでいいですから答弁してください。","respondent":"太田指導課長、田村教育次長","answer":"一つは、この内容を真摯に受けとめたです。短期間で全部がこちらのほうとして対応を具体的にやれるような、本当に非常に深い内容ですので、そこら辺は……。 ２９日に最終回が終わりましたけれども、学識経験者も、いろいろな意見が出ました。指導課長が説明したんですけれども、２９日が最後と言いつつ、学識経験者にオーケーして今日に至ったです。","id":"exchange-069"},{"speaker":"南委員","kind":"質問","question":"それはここに書いてあるではないですか。そこについてはどうなんですかというふうに聞いているんです。","respondent":"太田指導課長","answer":"内容につきましては、本当にその内容のとおりだと考えていますし、それを真摯に受けとめております。","id":"exchange-070"},{"speaker":"南委員","kind":"質問","question":"その発言があったときにどういうふうに受けとめて、真摯に受けとめたんだったら、教育委員会の事務局の中で検討したことはあったんですか。真摯に受けとめたというそこのところは具体的にどういうことなのか説明を求めました。","respondent":"太田指導課長","answer":"報告書の２６ページにもありますけれども、事実、そういったことに対して行政指導が十分になされていなかったということについて真摯に責任を感じているところです。","id":"exchange-071"},{"speaker":"南委員","kind":"意見","question":"そうであるならば、どういうふうにこれからしていかなければいけないと考えているのか、まだ検討がされていないのだったら、いつの時点でそういう検討をしていきたいと思っているのか、そこについてもお知らせしてくださいとの意見を述べました。","respondent":"田村教育次長","answer":"即対応しないと、学校は学校で取り組まなければならないことというのも、これもいじめの体制で２７ページからいっぱい載っています。それとか、例えば９月５日の手引書の説明会でも、担任によるチェック項目というのを２２項目ありますよね。","id":"exchange-072"},{"speaker":"南委員","kind":"質問","question":"これを１枚１枚丁寧に見ていけば、そういうことも含めてあるのであれば、私は丁寧に見て読み込んでいけると思うんです。それが気にしなかった、見落としてしまった、そこは何というふうに教育委員会は見ているんか尋ねました。","respondent":"太田指導課長","answer":"そこについては、報告書の言葉をかりれば、教員のいじめに対する認識の低さ、そういったところになるのではないかなと思っています。印を見落としたわけではございません。","id":"exchange-073"},{"speaker":"南委員","kind":"質問","question":"見落としていないというふうにおっしゃるけれども、何をもって、どこにどういうふうに書いてあるんですか。もう１回さっきのさらっとした説明では私はちょっとわからないので説明を求めました。","respondent":"太田指導課長","answer":"大丈夫という回答を得る、大丈夫であるという本人回答と、いじめの報告からも除外したと書いてあるとおりです。","id":"exchange-074"},{"speaker":"南委員","kind":"質問","question":"やはり直後に一定程度の働きかけがあってしかるべきですし、しかし、そういうことがあっての声かけであるということも否めないわけではないですか。本当に数だけ上げなければいけない、集計を早くしなくてはいけない、その辺については教育委員会としてはそういうふうに見ていないわけか尋ねました。","respondent":"太田指導課長","answer":"多いとか何とかではなくて、それは教員としてやるべきことなんです。ですから、そうご理解いただきたいと思います。","id":"exchange-075"},{"speaker":"南委員","kind":"質問","question":"最後のほうの子どもは、３０秒ぐらいのやりとりで、ああ、大丈夫だというふうに判断しなくてはいけない。そういう実態をご存じなんですか、教育委員会としては。","respondent":"太田指導課長","answer":"いじめということで緊急性があったので、本当に、例えば２日でもやってくださいということで学校にそれを出したわけです。すべての文書をそんなような状況で出しているわけではもちろんありませんので、逆に言うと、そういうふうにご理解いただければと思います。","id":"exchange-076"},{"speaker":"南委員","kind":"質問","question":"そうしたら、７月のときのアンケートは、自宅に帰り、家族と一緒に書きなさいというふうにおろしたということですけれども、何日かけて報告を出しなさいというふうになったんか尋ねました。","respondent":"太田指導課長","answer":"特にいじめられている子が、いじめている子がいるところでそういったことは書きづらい、そういう配慮もあって家庭に持ち帰って書くようにということで指示を出しているところです。","id":"exchange-077"},{"speaker":"南委員","kind":"質問","question":"いくら退職校長先生を配置したり、スクールカウンセラーを配置しても、やはりいじめはなくならないというふうに思います。そういう認識はないか尋ねました。","respondent":"田村教育次長","answer":"例えば、いじめだとか、交通事故だとか、転落死だとか、他の自治体なり自分の自治体であったときには、緊急調査、緊急対応というのは常識です。最優先で対応するのが教育委員会としての責務だと、そのように考えておりますので、ぜひご理解いただきたいと思います。","id":"exchange-078"},{"speaker":"南委員","kind":"質問・要望","question":"いろいろな職員を配置する、こんなことをしても基本的な仕事量が解消されていかない限り、そこに携われる時間がとれなくなるわけではないですか。ですから、そこをぜひ協力して教育委員会は対応していただきたいということを強くお願いしておきたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-079"},{"speaker":"阿部委員","kind":"質問・要望","question":"子ども理解、それぞれの学級でどう取り組んでいくのかというところから考えてほしい、学校としてやっていただきたいと考えています。これを読んでいますと、７年生の学年教員集団が特に閉鎖的であったかのように記述としては読めたんですけれども、これはそうだったんか尋ねました。","respondent":"金野委員長、太田指導課長","answer":"副委員長と、今後どうするかというのは検討させていただきたいと思いますので、一旦これは預からせていただきたいと思います。よろしいでしょうか。 ですから、そういったような目をもって、そのそれぞれの子どもの局面に対応するということが大切だったのかなということを感じています。３点目については、自殺の防止の対応についてどうかということですけれども…","id":"exchange-080"},{"speaker":"阿部委員","kind":"質問・要望","question":"中学校へ入っていろいろ壊されたときにはどういう指導をすべきだったのか、あるいはこれからされるつもりなんですかということを聞いているんです。だから、少なくともこの対応を見る限りでは、結局どんな仕組みをつくっても見逃されてしまうのではないのという危惧があるからそれを伺ったんです。","respondent":"太田指導課長","answer":"学校も、また教育委員会も酌み取って、それに対応していくということだと思っています。特に第５のいじめの対応の課題とか、それに対する対応も第６に出ておりますので、非常に分析的にいろいろと出ておりますので。","id":"exchange-081"},{"speaker":"阿部委員","kind":"質問・要望","question":"もうこれは要望ですね。できていないものをこれからつくっていくにはどうしたらいいのかということをきちんと具体的に検討してほしいと求めました。","respondent":"太田指導課長","answer":"それで、例えば、学年間の中学年団で５・６年と７年がなかなかフロアで、教師コーナーがあっても連絡がとれない。そういったことで具体的にこういったところで解決策というか、対策が出ておりますので、そこのところでご理解いただけないかと思います。","id":"exchange-082"},{"speaker":"阿部委員","kind":"質問・要望","question":"今のは要望にしておきます。８月の文教委員会で、あれ、ぜひ見直してほしいというようなことを言ったと思います。","respondent":"太田指導課長","answer":"改めて読みました。","id":"exchange-083"},{"speaker":"阿部委員","kind":"質問・要望","question":"やはり学校の先生にあれもやってほしい、これもやってほしいと、この日に何でも投げてしまうと。教員に対していろいろと、もう１回振り返ってほしいことはあるんですけれども、ぜひ真剣に精査して取り組んでいただきたいなと考えています。","respondent":"太田指導課長、齋藤庶務課長","answer":"配置しておりますので、そこで教員のそういった、これは教員にも当たるということ。それから、事案発生後については、例えば……。 産業医の先生もいらっしゃいますので、精神的な問題で、多忙感のある先生については、こういうふうにケアをしていきたいというふうに考えています。","id":"exchange-084"},{"speaker":"阿部委員","kind":"質問・要望","question":"当然、ストレスが出てくるのでしょうし、抑鬱状態等々についてもぜひ気をつけてほしいと求めました。そこは一方で。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-085"},{"speaker":"鶴委員","kind":"質問・要望","question":"各委員からいろいろ何度も同じような確認とかがあったかもしれませんけれども、どういうふうに受け止めたのか、もう一度だけ教えてほしいと求めました。","respondent":"太田指導課長","answer":"例えば校長に直接電話をして指導主事がヒアリングをしたりということを７月３１日の通知でも行っているところなんですけれども、そこのところはやはり私どももいろいろなことを見直す、見つめ直していかなければいけないかなと思っています。","id":"exchange-086"},{"speaker":"鶴委員","kind":"質問","question":"あわせて、今、アンケートをとって、もう一つがこの調査報告書、こういうことを書いていただいているということです。そこについてはどうか尋ねました。","respondent":"田村教育次長","answer":"成長の過程で十分あり得ることですから、ほんとうにサインを見逃さないというのが、やはり学校とすれば一番大事と。私たちも工夫しなければいけない部分があったんだと思うので、その辺も踏まえて再発防止を図っていきたい、そのように考えてあります。","id":"exchange-087"},{"speaker":"鶴委員","kind":"質問","question":"手を尽くしていって、それで終わり、それでいいということはないと思うので、それは今、ご答弁いただいたことに尽きると思うんですが。ただ、本当に残念ながらというか、やはりこれ、資料編についても含めていいか尋ねました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-088"},{"speaker":"鶴委員","kind":"質問・要望","question":"ですから、ここをとにかく外さずやっていただきたいということを、該当校以外でも決して同じことを起こさないという話がありました。活かす場所はいろいろあると思いますけれども、当事者を活かすという部分では、ちょっとどういう意見があるか説明を求めました。","respondent":"太田指導課長","answer":"そういった当事者の方のお話などもより心に響いて子どもたちのいろいろな前に向く力になると思うので、そういった状況も踏まえながら、そういったことも考えてまいりたいというように思っています。","id":"exchange-089"},{"speaker":"鶴委員","kind":"質問・要望","question":"当然タイミングの問題があるんですが、そこをしっかりと参考に、そこも生かしてほしいと求めました。これからも進めていただきたいし、また充実させていただきたい、このように思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-090"},{"speaker":"大西委員","kind":"確認","question":"一つ確認をしておきたいんですけれども、教育次長に家庭訪問についての質問をし、それはちょっと考え直すべきではないかと。そして家がどういう環境の家であるかということを承知して学校での教育に生かしていくということで、それとも、ちょっと確認しておきたいんです。","respondent":"太田指導課長","answer":"家庭訪問を実施している学校もありますし、各学校は必ずそういった児童・生徒の家には家庭訪問をして対応するということはありますけれども、それは学校任せで学校の判断というような形でやっているところです。","id":"exchange-091"},{"speaker":"大西委員","kind":"質問・要望","question":"要望等も入れておきます。この定義３の報告書の中で、これに対して教育委員会はどのような対応をしたのかということについてお尋ねしたいんですが、いかがか尋ねました。","respondent":"太田指導課長","answer":"３ページの４月から６月のですけれども、当該校においては、あえてということではございません。それで、教育委員会のほうも、それについては該当がなかったという理解をしたです。","id":"exchange-092"},{"speaker":"大西委員","kind":"質問・要望","question":"そのための皆さんに大いなる決心をしてほしいと求めました。答弁をお願いします。","respondent":"太田指導課長","answer":"委員おっしゃるように、それぞれの段階でというお話がございました。しっかり対応して、学校だけに任せるのではなくて、我々もそういったところで前向きに取り組んでいきたいというように思っています。","id":"exchange-093"},{"speaker":"大西委員","kind":"質問・要望","question":"逆にこういう学校だったらどうなったんだろうか、大いなる恐怖を感じます。それが二人とも知らないと言ったら、これは事件は顕在化しない、芽を摘むということに大いなる努力をお願いして私の質問と要望を終わります。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-094"},{"speaker":"高橋委員","kind":"質問・要望","question":"この先どうなっているかちょっとわからないんですが、小学校時代のことについて、ある程度また聞き取りをしたりするのでしょうか。来年度の予算に関して、こういったことを踏まえて、区費のカウンセラーについての要望みたいなものは定例会のほうに出していくのかということ。","respondent":"太田指導課長","answer":"他校の対応ですけれども、まずこれをどういうふうな形で実施していくかというのは、教育委員会に課せられたことだと考えています。ご質問、ご要望等、そういったことにも学校として対策を練りながら対応していくというようなことになろうかと思います。","id":"exchange-095"},{"speaker":"高橋委員","kind":"質問","question":"非常に重要な事態だというので、今お話にあったことを進めていってほしいと求めました。２９ページでしょうか、その点についてだけ回答を、済みません。","respondent":"太田指導課長","answer":"そういった先ほどからお話し申し上げているようないじめに対する認識の低さみたいな部分が出ておりますので、特異なケースであろうが、子どもが苦しんでいるという状況を救うということが教員としてそういう面をしっかり持たせるように指導していくことが必要と考えています。","id":"exchange-096"},{"speaker":"阿部委員","kind":"確認","question":"１０月２９日に調査対策委員会が開かれた内容の中で、本調査対策委員会はこれで解散ということになるんですか。誰に対して、ちょっと独立したシーンとして、責任を持って洗っていくというようなことは考えていらっしゃいますか尋ねました。","respondent":"田村教育次長","answer":"アンケートで３回、かなりの短期間で集中的にヒアリング等を実施したので、あんまり可能性としては出てこないのかなというふうに考えています。調査対策委員会の中でも委員長の挨拶で事務局の長である教育長のご挨拶で、一応、一つの区切りがついたです。","id":"exchange-097"},{"speaker":"阿部委員","kind":"意見","question":"今、最初に検証する仕組み等もありましたけれども、検証する仕組みというのはどういうものを考えていらっしゃるのか、具体のところに実行部隊が活動していくであるとか、検証する仕組みというイメージだと思うんですけれども、そこに関してはどのような形で望まれるのかとの意見を述べました。","respondent":"田村教育次長","answer":"これを見ると、対象校と自校を相互評価する仕組みなどが考えられるということで、なかなか現実的にはこれからいろいろ検討する必要があります。専門家を集めて、目安箱を直接回収して対応するというような…","id":"exchange-098"},{"speaker":"阿部委員","kind":"質問・要望","question":"学校単位というか、教育委員会全体としてそれぞれ必要な仕事とその検証をするようやってほしいと求めました。それについては、また今後もお聞きしたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-099"},{"speaker":"伊藤委員","kind":"質問","question":"同時に、この６人がまた将来にわたって自分の人生を切り開いていくように指導することが必要。この指導はすごく難しい感じがするんだけれども、やはり教育委員会の考え方をぜひお伺いしたいんですが、いかがか尋ねました。","respondent":"太田指導課長","answer":"そういったような教育相談的な側面とか、あとはやはり行為で言えば、生活指導的な側面をあわせて指導を継続していく。８年生、９年生と義務教育の中でそういった力が培われるように、周りの大人で指導して見守っていくという体制が必要かと考えています。","id":"exchange-100"},{"speaker":"伊藤委員","kind":"質問","question":"この６人の子どもたちの、三歳でしょうから、これからのことももちろん教育的に配慮していくことがある。だから、そのなんていうか、的確に、また厳格に、厳しく指導して導いていく、それもまた教育委員会の責務だと思うのですが、いかがか尋ねました。","respondent":"太田指導課長","answer":"先ほど申し上げたんですけれども、学校に我々も出向いていって、実際に加害生徒の様子とかも見ています。学校と連携して、そういった形で関わっていけるような、何かそういったような形でこの子たちの指導にも関わっていきたいというふうに思います。","id":"exchange-101"},{"speaker":"南委員","kind":"質問・要望","question":"だから、そういう状況をつくり出した子どもたちの部分にしっかり目を向けて、そういう子どもにさせないための対策が求められると思うんです。このまとめとして出ているものだけに、どうかというふうに教育委員会が認識しているのか、まずそれを伺いたいと思います。","respondent":"太田指導課長","answer":"最初に、この報告書をまとめたのは、教育委員会ではなくて……。","id":"exchange-102"},{"speaker":"南委員","kind":"意見","question":"そんなこと知っています。教育委員会の見解はないかと聞いているんですとの意見を述べました。","respondent":"太田指導課長","answer":"いや、委員がそうやっておっしゃったので、今、そこだけは押さえておきたいと思います。","id":"exchange-103"},{"speaker":"南委員","kind":"質問・要望","question":"私はそういう答弁を求めたわけではないです。こういうばらばらな状況を教育委員会としてはどう見て、どういうふうにそれを改善しようとしているのかということを聞いているんです。","respondent":"太田指導課長","answer":"ですから、学校の中がばらばらだというのは、どういう状況なのかと、要するに、学年の組織がばらばらなのか、教員個々がばらばらなのか、そのときのそういう状況を見極めて、適切な対応を求めていくということが教育委員会としては必要かと考えています。","id":"exchange-104"},{"speaker":"南委員","kind":"質問","question":"３１ページに、(3)で教員間の情報交換というところ、そういうことが書いてあるわけですね。そこについての教育委員会としての認識はどうなのかと、心配するので、これについての見解を伺いたいというような質問をしているんです。","respondent":"太田指導課長","answer":"そういう状況があるので、それは非常によくない、それは改善をしていくというスタンスです。","id":"exchange-105"},{"speaker":"南委員","kind":"質問","question":"事実は事実としてあるわけですから、そこをしっかり受けとめなければ、学校にも反映できないですよ。私のさっきの質問で、教育委員会自身の認識がそこになければ、うまく機能なんかしないではないか尋ねました。","respondent":"田村教育次長","answer":"ここにも、調査対策委員会のところにも書いてあるんですけれども、やはり小・中学校の、４２ページです。７年生なので生徒会と書いてありますけれども、そのように受けとめていますので、教育委員会としても学校とともに努力していきたいと考えています。","id":"exchange-106"},{"speaker":"南委員","kind":"質問・要望","question":"同時に、やはり品川の教育の方針、そこに照らして深めていただきたいと思うんです。したがって、ぜひ深めていただく視点に品川区の教育方針、ここに基づいて深めていただきたいということを強くお願いしておきます。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-107"},{"speaker":"鶴委員","kind":"質問・要望","question":"これは要望的なところなんですが、本人が訴えたかったこと、ここに１冊としてまとめられているのかなと思うんです。これは要望です。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-108"},{"speaker":"渡部副委員長","kind":"質問・要望","question":"教育委員会がどう生かしていくということだと思いますので、細かいところはまだまだわからないんですけれども、まず改めて伺うところは伺います。要望だけ入れします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-109"},{"speaker":"阿部委員","kind":"質問・要望","question":"言いたいことはたくさんあるんですけれども、１個だけ要望させてください。私の要望はそれだけです。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-110"},{"speaker":"阿部委員","kind":"質問","question":"この施設ですけれども、これは４月１日ということは、既存の園と同様のタイミングで募集するのか尋ねました。","respondent":"伊崎待機児童対策担当課長","answer":"募集につきましては、１２月１日の広報で皆様にご案内いたします。既に保育園のお申し込みをいただいている方には、個別の通知もあわせていたします。","id":"exchange-111"},{"speaker":"南委員","kind":"質問・要望","question":"第２項のところは、認定こども園とか、家庭的保育事業の直接契約ということで、自治体が保育を確保する努力を求めている。確認、しっかり信頼を持って見ていいのかどうかという、そのあたりをちょっと説明を求めました。","respondent":"伊崎待機児童対策担当課長","answer":"第１項で、次項に定めるところによるほか、こちらの児童福祉法上では実施義務と確保技術が同一でされているというふうに認識はしております。これはどちらも努力をしていくべきと考えております。","id":"exchange-112"},{"speaker":"南委員","kind":"質問","question":"そうすると、地方自治体が、どんな場合でも、どんな子どもでも保育は責任を持ちますよ、きちんと受け入れて保育をします、保証しますよというふうに理解していいんか尋ねました。","respondent":"伊崎待機児童対策担当課長","answer":"子育て支援を総合的に決める新しい法律をつくっていくということになっておりますが、これから国の子ども・子育て会議の中で検討されまして、それに従って判断をしていきたいと考えております。","id":"exchange-113"},{"speaker":"南委員","kind":"質問","question":"民自公のところの３党合意でこういうことを持ち出して、数の力で進めてきたという点については、本当に不満だと思います。その点について、この辺の父母の要求というのはどういうふうに信頼を持って品川区に申請をし、認定をしてもらったらいいのか尋ねました。","respondent":"伊崎待機児童対策担当課長","answer":"必要性の認定の基準はこれから出てまいりますので、市町村は変更を行うというのは、今までとこれは変わりません。お使いいただくという仕組みは、今、一本化されるというイメージです。","id":"exchange-114"},{"speaker":"南委員","kind":"質問・要望","question":"私は、結果的には待機児解消につながっていかないというふうに、今のご答弁を伺ってもそう思うんです。消費税がどんどん上がっていく、こういう仕組みになるわけですから、こういうところに財源を求めるということも間違っていると思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-115"},{"speaker":"阿部委員","kind":"質問","question":"この資料自体は、いろいろなところでこれまで見ているものですけれども、国としての方針ということなんですが、お伺いしたいのは、都のほうで今後どのように認証保育所などをどのように扱って、何か現段階で情報があれば説明を求めました。","respondent":"伊崎待機児童対策担当課長","answer":"これを今のタイミングでご説明しましたのは、１０月に市町村に対する説明会が内閣府主催で行われまして、その結果を受けてのご説明です。要望をしているということだけは聞いております。","id":"exchange-116"}]},{"id":"topic-04","title":"の２、所管事務調査","agenda":"の２、所管事務調査","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"今日はこんな時間ですから。そういうことは絶対に起こしてはならないわけですから、きちんと環境は守っていただきたいということを改めてお願いしておきたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-117"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/162678?Template=document&Id=4774#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2012-01-01&TermEnd=2012-12-31"}],"sourceMeta":{"pages":0,"characters":110617,"voices":272}},{"id":"h24-20121105-5","meetingId":"h24-cm11","date":"2012年11月5日","dateIso":"2012-11-05","committee":"総務委員会","time":"午後０時５９分～午後２時４２分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を39件整理しています。","topics":[{"id":"topic-01","title":"はじめに(1)の「（株）南東京ケーブルテレビへの東急電鉄（株）の運営参画」","agenda":"はじめに(1)の「（株）南東京ケーブルテレビへの東急電鉄（株）の運営参画」","exchanges":[{"speaker":"飯沼委員","kind":"質問・要望","question":"南東京ケーブルテレビ自体の会社の概要というか、株もパーセンテージはここに出ているんですが、どのくらい、資産とかその辺も大雑把に教えていただきたいのと、具体的に参画をするということは、この株式の所有状況がどういうふうに変わっていくのか、その辺を説明を求めました。","respondent":"柏原行財政改革担当課長","answer":"こちらは先ほどの資料とあわせてご覧いただきますと、４７社がその株を所有しているといったところです。今後の協議によりまして、東急電鉄のほうも株式の取得も視野に入れながらですので、今後の協議の中で決まってくるところです。","id":"exchange-001"},{"speaker":"飯沼委員","kind":"質問","question":"あわせてお伺いしたいのと、５万株ということで、この品川区の持ち株の中からという理解でいいんでしょうか。もうちょっとその辺の、東急電鉄が参画をすることでの住民への影響や変化があったら、もうちょっと具体的に説明を求めました。","respondent":"柏原行財政改革担当課長","answer":"社員としましては４１名の社員が勤めてあります。そういったメリットもあるだろうということで、具体的に協議に入っていこうです。","id":"exchange-002"},{"speaker":"飯沼委員","kind":"質問","question":"これからというところで、あまりよく見えないんですが、東急電鉄との関係というか、東急電鉄の影響が、沿線が多いという意味では品川区に対しての影響が強まるという捉え方でいいんか尋ねました。","respondent":"日下部企画部長","answer":"お互いに連携・協力することによって、サービスの向上をしっかりと図っていこうと。その辺が出発点だということで、ご理解をいただきたいと思います。","id":"exchange-003"},{"speaker":"阿久津委員","kind":"質問・要望","question":"どこがどういう関係にあるのか、情報を把握していれば教えていただきたいということ、具体例を挙げて教えていただきたいということが１つ。きれいに３等分されていますので、そこら辺をちょっとお聞きしたいと思いまして、お尋ねしました。","respondent":"柏原行財政改革担当課長","answer":"世田谷区の一部、２３区で言うとこういったところがエリアになってございまして、主に東急線の沿線がそのエリアということでだと。いろいろ民間の企業等々がほとんどで、自治体的なところでは品川区だけでございまして、あとは一般の企業が名を連ねているです。","id":"exchange-004"},{"speaker":"阿久津委員","kind":"質問","question":"そういうほかの自治体の情報が得られるというのは、非常にメリットだと私は考えております。運営参画といって通常どこまで出しているのかというのはわからないんですが、もしまた後ほどわかれば、教えてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-005"},{"speaker":"鈴木（真）委員","kind":"質問","question":"南東京ケーブルテレビの資本の移動の関係で、設立時と、たしか増資していますよね。その辺の状況と、品川区の当初の持ち分と、今のはわかりますけれども、増資の状況をまず説明を求めました。","respondent":"柏原行財政改革担当課長","answer":"平成７年１２月、３,５００株をこちらも買ってございまして、持ち株の比率にしますと７％といったところです。その３,５００株からさらに１万３,５００株と増資をいたしまして、そのときに持ち株の比率としては２７％になったといった状況です。","id":"exchange-006"},{"speaker":"鈴木（真）委員","kind":"質問","question":"これは当然上場していないから、評価は１株５万円になると思いますけれども、今後の展開の中で、こういう株式を品川区が一部売却するようなことになったときには、この評価というのはやはりその元の金額で評価することになるんか尋ねました。","respondent":"柏原行財政改革担当課長","answer":"当初の５万円というのは多分基本にはなってくるかと思うんですけれども、こちらを売却する際に、改めて評価が入ってくるところでございまして、そのままの金額ということではなかろうかと思います。","id":"exchange-007"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"各放映、その辺の今を低下させない、区にとって質の低下にならないようなことをぜひお願いしたいということを要望しておきます。要望としては、ぜひ品川の区民にとってメリットが残るような形でしていただきたいということを、検討の中でつけ加えておいてください。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-008"},{"speaker":"須貝委員","kind":"質問","question":"日本電気が３３％ということでいるんですが、やはり何だかんだ言っても株式会社でしょうから、品川区の影響というのはやはり下がってくる。区の情報をそこから発信してもらっていますが、やはり放映権料の値上げということも、これは企業ですからそういうこともありますよね。","respondent":"日下部企画部長","answer":"だからそういった意味では、これからいろいろな検討の要素はあろうかと思いますけれども、やはりこの辺のところをしっかりと大きな柱にしていく。これはもうどのような形になろうと、やはり一番大事なところだと認識しております。","id":"exchange-009"},{"speaker":"飯沼委員","kind":"質問","question":"２番の株式の所有のところなんですが、役割というか、制作担当をしているんですか。ちょっとそこの中身を説明を求めました。","respondent":"日下部企画部長","answer":"日本電気は、先ほど柏原行財政改革担当課長のほうから鈴木（真）委員のご質問にお答えさせていただきました。そういうことでご参加をいただいているというものです。","id":"exchange-010"},{"speaker":"飯沼委員","kind":"質問・要望","question":"そうすると、今後のことがいろいろとあると思うので、ぜひ注視していきますので、変化があったときなど、ご報告をほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-011"}]},{"id":"topic-02","title":"の「『品川区史』編さんについて」","agenda":"の「『品川区史』編さんについて」","exchanges":[{"speaker":"石田（慎）委員","kind":"確認","question":"品川区史編さん検討委員会の２つの委員会があって、裏面の平成２５年度は、レイアウト作成して最終的な確認を１年でやるのかなと。もう平成２４年度で品川区史編さん検討委員会は終了して、その辺の委員会の構成が平成２５年度以後どのようになっていくのか、お知らせください。","respondent":"武内総務課長","answer":"こういう掲出していくものの方針的なものを確認していただいて、商業の部分だったらこういうのもあるよだとか、そういうご意見をもらう。品川区史編さん検討委員会というのは内部の会議ですので、ものづくり・経営支援課長だとか、品川区史編さん検討委員会というのは。","id":"exchange-012"},{"speaker":"飯沼委員","kind":"質問","question":"平成２３年度から４年をかけて、４０８ページというかなりすごくボリュームもある内容なんですけれども、予算の総額は幾らぐらいかかるのか。平成２４年度の予算書は見たんですけれども、最終的にどのくらいを予定しているのかというのが１点、説明を求めました。","respondent":"武内総務課長","answer":"作成から製本からということをやっていただきますので、委託料としましてはトータルで５,６００万円支払います。それと同時に、こういう委員会を開催しますので、若干報償費等がかかりますので、そのような金額で予定しております。","id":"exchange-013"},{"speaker":"飯沼委員","kind":"質問","question":"発行部数が１,５００部ということと、ＤＶＤも添付だから一緒ですね。実際にこれがどう活用されるのか、手に入れたい場合、価格がどうなるのかあたり、どういうところに行けば見られるのかも説明を求めました。","respondent":"武内総務課長","answer":"それが１,５００部という数の中で一般の区民に頒布ということも当然行うんですけれども、検討中ということで、最終的な金額はまだ決めておりません。","id":"exchange-014"}]},{"id":"topic-03","title":"の「大井競馬場における中央競馬の発売計画について」","agenda":"の「大井競馬場における中央競馬の発売計画について」","exchanges":[{"speaker":"飯沼委員","kind":"質問","question":"ご説明いただいたんですが、これはいつから行われるのでしょうか。車両も増えるということで、近隣に与える影響があるかと思うんですが、この説明会というのはいつごろ行われるのかも説明を求めました。","respondent":"武内総務課長","answer":"平成２５年度の４月からですけれども、実際日曜日に大井競馬場でやっているのは夏ぐらいでないとやっていないもので、そういう予定になっています。ちなみに、それは１２月中旬が開催予定になっていますので、そこで正式にこの案件が出てくるというふうには聞いております。","id":"exchange-015"},{"speaker":"鈴木（真）委員","kind":"質問","question":"今、連合町会長というお話がありましたけれども、そこには行っていても、逆に地域、一般区民までは周知していない。人数が増えるということで気にする方もいらっしゃるでしょうから、その辺だけ、お願いしたいと思いますが。","respondent":"武内総務課長","answer":"１０月２０日ぐらいにお見えになりまして、まだ言われるとおり、あそこの周辺住民の全ての方についてはまだ報告がしていない。１１月に入りましたら、早急に町会連合会あるいは自治会を通じて、地域周辺の方に周知していきたいという話を聞いております。","id":"exchange-016"}]},{"id":"topic-04","title":"の「平成２４年特別区人事委員会勧告の概要について」","agenda":"の「平成２４年特別区人事委員会勧告の概要について」","exchanges":[{"speaker":"飯沼委員","kind":"質問","question":"どう読んだらいいのか、比較した職員数のここの数字をどう見たらいいのか、教えてください。これはどういうことなのかなとちょっとわからないので。","respondent":"堀越人事課長","answer":"そちらの１ページの表ですけれども、職員数につきましては、さまざまな職種がありますけれども、その職種、再任用職員等を除きました形でのすべての合計が５万９,４５１人という形で調査をしたです。","id":"exchange-017"},{"speaker":"飯沼委員","kind":"質問","question":"ということは、いつもそういう比較の仕方をしている、事務と技術系ということで、特別区のところは全員ということで、違いはどういうところにあるのか説明を求めました。","respondent":"堀越人事課長","answer":"全体の給料の調査という意味で、全職員５万９,４５１人という数字を。全体の５万９,４５１人、４０万３８４円というのが平均給与月額という形で出ているという結果を、特別区人事委員会では持っております。","id":"exchange-018"},{"speaker":"飯沼委員","kind":"質問・要望","question":"今、伺ったのは、民間のほうに入っていなくて、特別区の職員に入っている職種、その辺の違いをひとつ教えてほしかったのが１点です。全国とか東京都、２３区比較すると、特別区の職員の給与自体が低くなっているという表現が文章にあったので、その辺を教えていただきたい。","respondent":"堀越人事課長","answer":"統計調査の手法として規模による層化の無作為抽出によって実施調査を行っておりまして、調査としては非常に精度の高いものだと感じております。税金という形で区民の負担により我々の給料が賄われている観点から…","id":"exchange-019"},{"speaker":"飯沼委員","kind":"意見","question":"年間１万３,０００円の減ということで、この間、やはり比較するところもきちんとした比較をしてほしいと思うところがあります。これは意見で終わりますけれども、ありがとうありますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-020"},{"speaker":"鈴木（真）委員","kind":"質問","question":"どのように対応しているのか、その辺の区の考え、検討状況等を教えていただければと。その辺を中心に教えてもらえればありがたいです。","respondent":"堀越人事課長","answer":"そういったことに対応するという形で、また新たな研修を入れたりですとか、そういうこともやっております。それから２３区全体の課長会での意見も持っておりますし、人材の育成に向けて、区としても積極的に取り組んでいるところです。","id":"exchange-021"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"あまり受けたがらないという傾向があるということもお聞きしているので、制度的にも頑張っていただきたいと思っています。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-022"},{"speaker":"阿久津委員","kind":"質問・要望","question":"３ページの職務・職責が的確に反映された給与制度、それにちょっと関連して、管理職および係長職について改善を図ることが必要であると。確認をさせていただきたいんですけれども、２３区として、そこのところを教えてほしいと求めました。","respondent":"堀越人事課長","answer":"そういった部分によって、例えば仕事を効率的に進めるというやり方、ノウハウ等を研修の中で進めていくということもしております。心身の健康を保ちつつ、その部分については、区としても引き続き進めていきたいと考えております。","id":"exchange-023"},{"speaker":"阿久津委員","kind":"質問・要望","question":"その前の２０１１年度も年間１,０００時間時間外勤務をされた方が１１２人もいたということで、１,０００時間を超えるような残業があるのかどうか。もし、今、資料があれば教えていただきたいんです。","respondent":"堀越人事課長","answer":"職分の仕事のやり方も指導していきますし、もちろん当然のことながら、所属の課長についてもしっかり話をしながら進めていっております。要はしっかりと仕事をするための必要な部分ですので、そういう形でできるようにしていきたいと考えています。","id":"exchange-024"},{"speaker":"阿久津委員","kind":"質問","question":"１名いるようなご答弁いただきましたけれども、ただ、いろいろな理由があって多分そういうことだと思いますので、一概にこれは何とも悪いとは一言では言えないところもあると思いますので、人事のほうのお仕事もしっかりとお願いします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-025"},{"speaker":"須貝委員","kind":"質問","question":"一般の区民の方も、新聞報道等でそういう数字は目にしているんですが、実際、これはどこがどう違うのか。この６６０万円ということは、この数字ということに関してどのようにお考えなのか、説明を求めました。","respondent":"堀越人事課長","answer":"８,２４０事業所から、なおかつ無作為抽出によって事業所を抽出したということで、統計的には有意な方法で調査をしていると考えております。私ども品川区の職員として公務に従事するという、それは民間企業も同様ですので…","id":"exchange-026"},{"speaker":"須貝委員","kind":"質問","question":"ならば、ここの資料というのは公表されているのか、どこか見れば一般の区民の方が見ることができるのか、その辺はどうなんでしょうか。なかなかこうだああだと言っても片一方は数字が出ているわけで、なかなかちょっと説明しにくいところがあるので、その辺どうなんか尋ねました。","respondent":"堀越人事課長","answer":"議長宛てに勧告をされているものですから、資料については、統計については人事委員会のデータとしてご覧いただけるようになっていると思っています。きちんと個人単位で対応させる形での比較をとっておりますので、繰り返しで恐縮ですが…","id":"exchange-027"},{"speaker":"須貝委員","kind":"確認","question":"確認だけですけれども、今のことで、議長のほうに報告されているという話ですが、それは例えば企業名なんかは列挙されているんですか。それだけ。","respondent":"堀越人事課長","answer":"全体の民間企業、いろいろな職種等があります。事務・技術系職種、学歴等で全体を比較して、概要として統計的な処理を加えて、報告させていただいているです。","id":"exchange-028"}]},{"id":"topic-05","title":"の「（仮称）鮫洲入江埋立公園整備工事請負契約」","agenda":"の「（仮称）鮫洲入江埋立公園整備工事請負契約」","exchanges":[{"speaker":"鈴木（真）委員","kind":"確認","question":"確認です。ここの公園整備のときに、これはほとんど品川区の計画となって、東京都は絡んでいないんでしたか。","respondent":"本城企画財政課長","answer":"この工事につきましては、もっぱら品川区の一般財源で賄った工事です。下のポンプ場のほうは東京都の関係の工事ですが、今回の公園整備につきましては品川区の財源ということで、ご理解いただければと思います。","id":"exchange-029"},{"speaker":"鈴木（真）委員","kind":"確認","question":"実は東京都が次にやる公園だと自分が勘違いしていたので、全部これは品川区がやって、今後も品川区が管理していくということでいいわけですか。そこの確認だけ。","respondent":"本城企画財政課長","answer":"お話のとおり、この公園についてはもっぱら区立公園という位置づけで、整備について区の財源で賄って、ここも区の公園として管理していくという立場です。","id":"exchange-030"},{"speaker":"飯沼委員","kind":"質問・要望","question":"この契約の相手方の東光園緑化株式会社品川営業所ということなんですけれども、本社はどこなのか。品川区での営業の実績もあったら教えていただきたいのと、予定価格とこの開きをどう考えたらいいのか、説明を求めました。","respondent":"平澤経理課長","answer":"こちらの現在の工事なんですけれども、平成２３年度におきましては、例えば中延五丁目の防災広場とか等々で５カ所工事実績があります。契約金額につきましては、８２％ということで落札したということなんですけれども、開きというか…","id":"exchange-031"},{"speaker":"飯沼委員","kind":"質問","question":"本社が渋谷区ということで比較的近いということ、あと品川区で既に何カ所もやっていて実績があるという受けとめ方でよろしいんでしょうか。契約の８２％ということなんですけれども、この３,０００万円の開きというのは、その辺をもう一回お願いします。","respondent":"平澤経理課長","answer":"繰り返しで恐縮ですが、品川区におきまして平成２３年度５回の工事をしているということで、信頼のおける業者と考えています。ですので、こちら８２％というところで、きちんとした利益が出る形の見積もりをされたと確信しています。","id":"exchange-032"}]},{"id":"topic-06","title":"の「第３回定例会第７１号議案 旧荏原平塚中学校跡地多目的広場整備工事請負契約に関する議案の撤回について」","agenda":"の「第３回定例会第７１号議案 旧荏原平塚中学校跡地多目的広場整備工事請負契約に関する議案の撤回について」","exchanges":[{"speaker":"石田（慎）委員","kind":"確認","question":"１点だけ確認したいんですが、これは品川区の基準で３カ月の指名停止ということですが、現在何らかの措置はとられているわけですよね。罰則があると思うんですけれども、その法というのは、その点をちょっと教えてほしいと求めました。","respondent":"平澤経理課長","answer":"支店に対して指名停止処分ということになります。ただ、ちょっと考えにくいんですけれども、本社が仮に単独で入札したとしても、それはお受けできませんということになります。","id":"exchange-033"},{"speaker":"阿久津委員","kind":"質問","question":"前にももしかしたらご説明があったかもしれないんですけれども、これを第４回定例会で上程されて、仮の話で申しわけないんですが、これがまた新たな入札ということになった場合、どれくらい工期がおくれるのかということ、とりあえず先にそれをお聞きします。","respondent":"平澤経理課長","answer":"入札のスケジュールで申しますと、議会の日程ですが、議決が１２月上旬になるということになってありますので、２カ月のおくれということになります。完成予定もその旨、おくれるということになるわけです。","id":"exchange-034"},{"speaker":"阿久津委員","kind":"質問","question":"ないとは思うんですけれども、影響があるのかどうかということ。解体作業、撤去作業についてのスケジュールというのは、現段階ではスケジュールどおり進んでいるのかどうかをお聞きしたいです。","respondent":"小林施設整備課長","answer":"現在、解体工事のスケジュールについては、予定どおり行っております。それと、今、この工事の関係で影響があるかというのは、それについては解体とは影響はございません。","id":"exchange-035"},{"speaker":"阿久津委員","kind":"質問・要望","question":"確認したかったのは、近隣の方がそれだけ確認をしてほしいということがあったものですから、それを確認させてほしいと求めました。そもそもそれをちょっとお聞きしたい。","respondent":"平澤経理課長","answer":"工事につきましては予定どおり行われているですので、それほど期間があくということは予定していないです。","id":"exchange-036"},{"speaker":"阿久津委員","kind":"意見","question":"うまく調整をしていただいて、間があくのがいいのか、そのままスムーズにいくのがいいのか、そこは工期が短いほうが、近隣の方への粉じんとか振動とか、そういった点で影響があると思いますので、そういうところは近隣の方のご意見を聞いてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-037"},{"speaker":"飯沼委員","kind":"質問","question":"１点だけ。第４回定例会で議決があるわけですけれども、具体的にこのでき上がりのおくれというのはどのくらいと考えたらよろしいか尋ねました。","respondent":"平澤経理課長","answer":"公園課のほうで、この日程で行った場合ということで試算をしていますが、８月の終わりまでには何とかということで、今、調整しています。","id":"exchange-038"},{"speaker":"飯沼委員","kind":"質問","question":"事業者の処分のところに指名停止３カ月とありますけれども、この辺の影響に対する被害に対しては、この３カ月の指名停止処分だけで終わるということなんか尋ねました。","respondent":"平澤経理課長","answer":"そういったところで、今後当然あってはならないですので、事業者に対して十分な注意をしていくです。","id":"exchange-039"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/579213?Template=document&Id=1928#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2012-01-01&TermEnd=2012-12-31"}],"sourceMeta":{"pages":0,"characters":30979,"voices":109}},{"id":"h24-20121106-14","meetingId":"h24-cm11","date":"2012年11月6日","dateIso":"2012-11-06","committee":"行財政改革特別委員会","time":"午後１時００分～午後２時４６分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を31件整理しています。","topics":[{"id":"topic-01","title":"旧第一日野小学校校舎等の解体","agenda":"旧第一日野小学校校舎等の解体","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"参加者からどのような要望が上がり、区がどういうふうに対応するのか、そこをご説明ほしいと求めました。学校の貸付期間そのものの変更はないのか、改めて旧第一日野小学校のＴＯＣの貸し付けはいつ終わるのか、そこを伺いたいと思います。","respondent":"柏原行財政改革担当課長","answer":"こちらの説明以外でもお話が出たんですけれども、登下校の時間帯、工事会社もその辺は配慮してなるべく進めていきたいというお話は聞いてあります。説明会は若干、今後どういった作業工程で何が出てくるかというのはありますけれども…","id":"exchange-001"},{"speaker":"中塚委員","kind":"質問・要望","question":"なぜしつこく伺うかといいますと、対象もまだ決まらず、未払いのまま学校移転が既に終わっている。なので、おおむね８年間とはどこに明記されているのか、改めて伺いたいと思います。","respondent":"柏原行財政改革担当課長","answer":"今後の説明会関係ですけれども、説明会という形では、仮設店舗を建てるときに説明会は行う予定です。こちらもＴＯＣ側が主催とはなりますけれども、説明会という形ではまずそういった機会があります。","id":"exchange-002"},{"speaker":"中塚委員","kind":"質問・要望","question":"それと、学校跡地の仮店舗ですけれども、現在ＴＯＣで営業されている方全てに仮店舗への入居希望等の有無を確認するのかどうか伺いたいと思います。ビル建て替えに伴い店舗を借りる契約の解除、つまりは退去を求められたと伺っておりますが、これは本当か尋ねました。","respondent":"柏原行財政改革担当課長","answer":"先ほどもご説明しましたように、そういったところを含めて全体の工事の８年間という計画を組んですので、担保はできていると思ってあります。仮店舗のお話ですけれども、ＴＯＣ側が仮店舗への移転…","id":"exchange-003"},{"speaker":"中塚委員","kind":"質問・要望","question":"つまり、おおむね８年を越えたらこれをＴＯＣに請求するのかと、そこについて答弁がなかったので、しっかりとお答えほしいと求めました。最後に、現時点でＴＯＣビルはどんなビルに建て替わるのか、いつ始まるのか、何も決まっていないじゃないか尋ねました。","respondent":"柏原行財政改革担当課長","answer":"こちらの事業用定期借地権設定合意書です、契約書ですけれども、第１５条、第１６条の規定です。新しい建物については現時点で変更云々ということよりは、ＴＯＣ側で検討していますので、現段階で何か言えるという部分ではないといったところです。","id":"exchange-004"},{"speaker":"中塚委員","kind":"質問・要望","question":"結局、違反があれば求めるんだと。私は何もＴＯＣに公有地貸し付けではなくて、住民要望の強い特養ホームや防災広場など、住民要望に沿った活用こそ強く求めたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-005"},{"speaker":"西本委員","kind":"確認","question":"確認だけします。それは今後どういうふうにされるのかということ、この点をお聞きします。","respondent":"柏原行財政改革担当課長","answer":"ですから、住所等を見ますと近隣の方々がほとんどですので、一般の住民の方々がほとんどであろうと考えています。そういった工事側の説明があったりであるとか、我々も聞いていて思いますけれども一つずつ丁寧な形で対応していただいていると思っています。","id":"exchange-006"},{"speaker":"西本委員","kind":"質問・要望","question":"意見、要望については対応をちゃんとされているよという理解でよろしいでしょうか。質問を受けただけだと納得いかないと思うので、丁寧にやっていただきたいなと思いますので、今後とも。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-007"},{"speaker":"石田（秀）委員","kind":"確認","question":"わからないことと、１点は確認したいことがあります。土とか、そこら辺のところをどのように話をしているのか、どういうふうにこれは対応したのかだけを教えてほしい。","respondent":"柏原行財政改革担当課長","answer":"その答えをお話ししますと、２月に入ってから２週間程度を予定しますというご回答と、その場で随時測定はしますというお話。騒音、振動が７５デシベルというような説明がされたのですが、そういうものは随時言っていただきたいというような対応をその場でしていたところです。","id":"exchange-008"},{"speaker":"石田（秀）委員","kind":"意見","question":"これ、どういう杭が入っているか知らないけれども、そこら辺のところというのはやはり絶対私は音より振動だと思う。そこら辺の対応は、何かあったら区も指導ぐらいはしっかりするべきだと思いますので、それはお願いしておきますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-009"},{"speaker":"鶴委員","kind":"質問・要望","question":"工事そのものが８時からスタートするんだろうなと思うんですけれども、準備も含めて、その辺の説明というのはこの場所であったのかどうか。これを教えてほしいと求めました。","respondent":"柏原行財政改革担当課長","answer":"時間につきましはして、先ほども委員から出ましたが午前８時から午後６時ということで、当然それよりも事前には作業員が入ってくるです。こちらにも書きましたけれども、そこをよく配慮してほしいということで、それについては配慮するようにということでのやりとりがあったです。","id":"exchange-010"},{"speaker":"鶴委員","kind":"質問・要望","question":"当然朝礼とかを含めれば７時半ちょっと前ぐらいからだんだん作業員の方々、配慮をということなので、きちんと強く要請していただきたいなと思います。先ほど、とにかく絶対この周辺で事故がないように配慮していただくように、しっかりと行政は強くやってほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-011"}]},{"id":"topic-02","title":"の２、特定事件調査","agenda":"の２、特定事件調査","exchanges":[{"speaker":"塚本委員","kind":"質問","question":"幾つかお伺いしたいんですけれども、今現在どうも財務省の管理になって、そういうのはこの表でいうと２ページ目の普通財産の住宅敷地に入るんですか。それとも、4)の「未利用国有地」に入るべきものが、細かいところまでは載っていないという。","respondent":"柏原行財政改革担当課長","answer":"国のほうが判断してどういう使い方もできないと判断するのであれば、未利用国有地ということで最終的にはなってくるんだと思うんですね。ただ、国で判断して、どこにも使えないということであれば未利用国有地ということに最終的には落ち着いてくるんだろうと思われます。","id":"exchange-012"},{"speaker":"塚本委員","kind":"質問","question":"今現在は空き家みたいになってしまっているんですね、そこは。そうすると、それはやはり除去して更地にしてからみたいなことが手続上、手続上というか、財産管理上、前提条件となってくるんか尋ねました。","respondent":"柏原行財政改革担当課長","answer":"一定程度の手続きを踏んで、判断をして、どういったカテゴリーに入れるかということになってくるんだと思います。申しわけございません、細かい手続きまでは承知していないので、申しわけございません。","id":"exchange-013"},{"speaker":"塚本委員","kind":"質問","question":"Ａ３の資料で、一番右の「西大井６丁目第３区営住宅」というのは建替時都営住宅区移管事業というのを使って、これを使ってやられた。一方で「大井林町高齢者住宅」のほうはそういう形になっていないのはどうしてかということをお伺いしたいんですけれども。","respondent":"柏原行財政改革担当課長","answer":"その場で、その当時の戸数が７２戸だったんですけれども、建築の関係上７２戸の戸数をつくるのは難しいということもあったようです。当時の判断では、単純に移管制度を使うのは難しいだろうという判断だったと聞いてあります。","id":"exchange-014"},{"speaker":"塚本委員","kind":"確認","question":"では、確認なんですけれども、この制度を使うには、同じ規模で建て替えないといけないという前提があるということか尋ねました。","respondent":"柏原行財政改革担当課長","answer":"結果的に「公営住宅法」の縛りがありますので、公営住宅として使うときにはどうしてもそこに引っかかってしまう。公営住宅として建てるときにはその規模をというラインがありますので、そこに引っかかってくる。","id":"exchange-015"},{"speaker":"稲川委員","kind":"質問","question":"３、品川区としてはどういう方向性でお考えなのか、そのままなのかどうなのかということ。バースというんですか、事務所が建っていたりするんですが、それは品川区としては把握されていないということでよろしいか尋ねました。","respondent":"柏原行財政改革担当課長","answer":"先ほども申しましたように国が調査というんですか、監査の中で境界を確定していないとか、すぐの処分は難しいという判断をしていると聞いてあります。細かくどういう用地かというのは、細かく例えば２０番は何と、これは何とかいうのは現段階では把握できていないところです。","id":"exchange-016"},{"speaker":"稲川委員","kind":"質問・要望","question":"８分の１なのか、何があるかというのは把握しておくべきだと僕は思うんですが、その点をお聞かせいただきたい。東京都のあれなので詳しいことはわからないと思いますけれども、その辺をお伺いしたいです。","respondent":"柏原行財政改革担当課長","answer":"先ほど１つ例として詳細が未確定というようなお話もしたんですが、個々に今、そういった状況があるので国としてはそういう判断をしているです。ちょっと申しわけありません、そういったところもあわせて今後、引き続き調査をしていきたいです。","id":"exchange-017"},{"speaker":"中塚委員","kind":"質問・要望","question":"国と東京都が保有する財産を売り払うときに、必ず品川区に連絡が来るという、その辺の仕組みを伺いたいと思ったんです。単純に「公有地の拡大の推進に関する法律」と言われるものだけなのか、そこをご説明ほしいと求めました。","respondent":"柏原行財政改革担当課長","answer":"それから、ただ、地元の区ということで一定程度ご配慮はいただいているのではないかと思ってあります。それから、東京都についても地元の区に、決まりかどうかというのはあれですけれども、地元の区にお話しいただいているケースが多いです。","id":"exchange-018"},{"speaker":"中塚委員","kind":"質問・要望","question":"土地の大小にかかわらず必ず１度は地元に意向を伺うという仕組みになっているということなのか、そこだけもう一度確認させてほしいと求めました。もう一つ、耐震化を掲げていながら耐震化の計画が立っていないものというんでしょうか、全体的なことですけれども特徴をご説明いただきたい。","respondent":"柏原行財政改革担当課長","answer":"先ほども、自分たちで使っているというようなこともおっしゃっているようですので、なかなかそれをどう判断するかというのは難しいところがあります。売るなりというところの話はできるかと思うんですが、行政財産につきましてはなかなかそれを把握するのは難しいところがありま…","id":"exchange-019"},{"speaker":"中塚委員","kind":"質問・要望","question":"どういうルールづくりがあるのか、そこはまた説明していただきたいなと、これは要望しておきます。西大井６丁目の第３区営住宅、そういう対象となるものがそもそもあるのかということと、その辺の考えを伺いたいと思います。","respondent":"柏原行財政改革担当課長","answer":"先ほど言いましたように都営住宅が１００戸よりも小さい住宅ですね、耐震にしても、全てにおいて区が負担をするです。一個一個、これを今どうするというのはお話しできる状況ではないんですけれども、区とするとそういうところがタイミングであろうと思ってあります。","id":"exchange-020"},{"speaker":"石田（秀）委員","kind":"質問","question":"そこら辺の考え方を教えてほしいのと、こちらが意識をして、ここにこれだけの敷地があると。私は、そこら辺の考え方、調べるということをしていらっしゃるのかということを改めて教えてもらえますか。","respondent":"日下部企画部長","answer":"例えば区民が接するようなスペース、エリアを考えることはできないかとか、区長もよくそういう話をされておりますけれども。ただ、あるいは国、東京都に対して物を申し上げていくことは可能なのかどうかということも含めて検討させていただきたいと思います。","id":"exchange-021"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"逆にあそこをどういうふうにと言ったら、そういう情報があるじゃないですか、区にも上がると思うので。もし、これは国税局の考え方があれだったら、答弁をお願い。","respondent":"日下部企画部長","answer":"大事なことだと考えていますし、南品川４丁目のお話もありましたけれども、その辺の確認はしていきたいと思っています。大分方針も変わってきておりますので、積極的な姿勢で臨んでいきたいと、このように考えております。","id":"exchange-022"},{"speaker":"鶴委員","kind":"確認","question":"言葉の整理というか扱いの確認なんですけれども、１０.３４m2で非常に小さいんですけれども、東京都が例えば品川区に土地を使わせますよね。ごめんなさい、その辺の整理の仕方というんですかね、どういう扱いになるのか教えてもらいたいんですけれども。","respondent":"平澤経理課長","answer":"そういった表示になるべくしてなっていないのかもしれませんから、その辺のところは調査していただきたいと思っているところです。委員ご指摘のとおり、国・東京都につきましては土地は普通財産、区としましては行政目的で使用する建物であれば行政財産という区分になります。","id":"exchange-023"},{"speaker":"鶴委員","kind":"質問・要望","question":"それについてはまた、わかり次第で結構なので、ぜひ教えてほしいと求めました。なので、その辺のすみ分けがどうなのかなと、今後の参考のために教えてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-024"},{"speaker":"西本委員","kind":"質問","question":"それをどういうふうな扱いで区がやっていくのか、２ページの「無償貸付財産」があるんですけれども、期限はあるんですか。それは必要だから返してほしいと言われてしまうと、大もととしてどういう取り決めをなされているのかなということについてお聞きしたいと思います。","respondent":"平澤経理課長","answer":"１番の「わかくさ公園」ということになってありますけれども、もともと昭和４５年、５年ごとに更新していくということになってあります。国につきましてはほかも全て５年間の更新でやっております。","id":"exchange-025"},{"speaker":"西本委員","kind":"質問","question":"管理については、それぞれがやるんですよということでわかるんですが、迅速さというのはどうなんですか。公園なんかもかなり整備して使っているわけですから、そうすると５年後で、その考え方についてお聞きしたい。","respondent":"平澤経理課長","answer":"直ちに対応できるですが、すぐ対応するようにお話し申し上げるということで対応させていただきたいというふうに思っているところです。こちらにつきましてもいきなり契約を解除というのは考えにくいところでございまして、十分に話し合いを持ちたいと思っているところです。","id":"exchange-026"},{"speaker":"西本委員","kind":"質問","question":"ちょっと私もよくわからないんですが、そこも道路の整備があるので返してほしいということで返して、野球場を整備したという経緯があると思うんです。あったりしますので、そこら辺はいかがか尋ねました。","respondent":"平澤経理課長","answer":"マイガーデン東五反田は東五反田２丁目１８番のところではないかと思うんですけれども、これは三井不動産販売株式会社が貸主、所有者でございまして、再開発に伴う合意解除ということで、私どもが合意して解除したという土地です。","id":"exchange-027"},{"speaker":"西本委員","kind":"意見","question":"やはり将来的にそこをどうしていくのかというのが、それも含め今後、私も考えてみたいと思っていますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-028"},{"speaker":"中塚委員","kind":"質問","question":"そこはどうお考えかということと、西大井６丁目の、結局何年もずっとそのままなんですよね。そういったところどう把握されているのかというのと、もし今わかれば、西大井６丁目の都営住宅の伊藤町アパート、あそこはもう区に来たんですかね。","respondent":"日下部企画部長","answer":"防災広場として整備をするということで、たしか今もう既に準備を進めております。どうも東京都の内部調整で、東京都の内部調整でちょっと時間がかかったということで承知しております。","id":"exchange-029"},{"speaker":"山内副委員長","kind":"質問","question":"ただし、情報としては自治体に最初におりてくるということ、これ、わかりました。これが東京都の財産を今度、何か、インセンティブがどんな形であるのかということを伺いたいんですけれども。","respondent":"日下部企画部長","answer":"時価に対して３分の１を東京都が減額して区に対して払い下げをしたということで、東京都についてはそういう減額の措置も残っております。いろいろお金の減額の話なんかもスムーズにいかないとか、そういう事例が最近出て来ているというようなことで承知しております。","id":"exchange-030"},{"speaker":"山内副委員長","kind":"質問","question":"これは必要なものだからやっていこうという方向性なんだけれども、今後、品川区の財政にも非常に響いてくるという流れになってきますよね。その辺は既に庁内で、今後のそういった考え方、払い下げに対しての品川区の対応をどのように考えているのかということを伺いたいですね。","respondent":"日下部企画部長","answer":"以前、公共施設の有効活用プランということで、内容についてご説明させていただきました。公共施設の有効活用プランのときにもご説明させていただきましたけれども、そういう視点も大事ではないかと、このように考えております。","id":"exchange-031"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/931720?Template=document&Id=5934#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2012-01-01&TermEnd=2012-12-31"}],"sourceMeta":{"pages":0,"characters":34759,"voices":72}},{"id":"h24-20121107-17","meetingId":"h24-cm11","date":"2012年11月7日","dateIso":"2012-11-07","committee":"震災対策特別委員会","time":"午後１時００分～午後３時４９分","status":"正式会議録","sourceType":"formal","overview":"震災対策特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を58件整理しています。","topics":[{"id":"topic-01","title":"特定事件調査","agenda":"特定事件調査","exchanges":[{"speaker":"渡辺委員","kind":"質問・要望","question":"では、２点伺いたいと思います。１年のスパン、あるいは２年スパンとか、その辺のお考えを１つ伺いたいことがあります。","respondent":"鈴木防災課長","answer":"新しい情報なり、３年から５年程度でやるのが費用対効果、もしくは内容の更新という意味ではよいのではないかということで現在考えているところです。ご指摘いただきましたように、地図本体が、本来の情報が読み取りやすいような形に改善したいと考えておるところです。","id":"exchange-001"},{"speaker":"渡辺委員","kind":"質問・要望","question":"何年かは定かじゃないんですが、５年というとかなり長く感じますので、３年未満を想定されながら発行すべきものと思うので、これは要望として。ページ数が実際、限られているのか、あるいはこれからページ数が増えることも可能なのかも含めて伺いたいと思います。","respondent":"鈴木防災課長","answer":"ご意見ありがとうあります。具体的に地図を実際のサイズでつくってみまして、目印となる施設を入れられる地図の大きさなりということを検討させていただきたいと考えております。","id":"exchange-002"},{"speaker":"武内委員","kind":"質問・要望","question":"わかりやすくするという工夫をしていただきたいのと、早い人なら１週間ぐらいすると、どこにいったかわからなくなってしまう危険性もあるわけです。自分の住んでいるところは切って張っておくこともできるみたいな、そういう工夫もしていただけないかと思うんですけれども、いかがか尋ねました。","respondent":"鈴木防災課長","answer":"貴重なご意見をありがとうあります。その辺は、切り離して必要な情報をいつも張っておいたり、目につくようにできるような形で工夫をしたいと考えます。","id":"exchange-003"},{"speaker":"井上委員","kind":"意見","question":"スケジュールのところに書かれている受託事業者と契約が済んでいるということなので、この受託事業者はどこなのかということと、あと、その受託事業者がどこかの自治体のこういったハンドブック、防災関連を経験されているのかどうかという情報をお願いしますとの意見を述べました。","respondent":"鈴木防災課長","answer":"申しわけありません。今、お答えできるのはその部分になってしまいます。","id":"exchange-004"},{"speaker":"井上委員","kind":"質問・要望","question":"まずは自分が備えるですから、今現状の自宅がどうか、それはまさしく自助の取り組みだと思うんです。区民がどう動いたらいいのかというふうに発想の転換をしていただきたいと思うんですが、この章立てについて、まだ検討の余地がありますか尋ねました。","respondent":"鈴木防災課長","answer":"項目名に出てまいりませんが、その中で、具体的にはそのときにどういう行動をしていただくということをこちらに記載する予定になっております。ご指摘いただいたのは、多分、そういうイメージでよろしいのかと考えるんですが、よろしいでしょうか。","id":"exchange-005"},{"speaker":"井上委員","kind":"質問","question":"ですから、火災が起きたときにどうしようというふうな読み物であったら、具体的に自分たちに落ちないんだと思うんです。ですから、多分、いつもいつも繰り返し目にしていただけるというものになるというふうなイメージです。","respondent":"鈴木防災課長","answer":"わかりました。私の説明で至らなかったようですが、それぞれ津波、トータルで安全な行動がとれるようにということで考えたいと思います。","id":"exchange-006"},{"speaker":"井上委員","kind":"質問・要望","question":"見た目きれいというか、文章が短くていいんですけれども、内容が落ちないんですよね。ですから、あと、あまりにも簡単に読んでいただこうというふうにされないでほしいなと思いますので。","respondent":"鈴木防災課長","answer":"すべてを網羅して表記はできませんが、基本的な考え方なり、身の安全を守るための重要な部分については記載を入れたいと考えております。タイトルがあって、もう少し文字の記載の部分はしっかりと読んでいただいた上で大事なことが理解できるというような工夫をしたいと考えてお…","id":"exchange-007"},{"speaker":"吉田委員","kind":"提案","question":"お子さんなんかも見られるような提案をしたいと思うんですけれども、そういう提案なんですけれども、いかがか尋ねました。","respondent":"鈴木防災課長","answer":"しっかりと認識していただく上で大事なことですので、いただいたような意見も含めまして、より活用される工夫をしていきたいと考えます。","id":"exchange-008"},{"speaker":"吉田委員","kind":"質問・要望","question":"英語でというわけにはなかなかいかないのかもしれないんですけれども、その辺もちょっと考えていってほしいと求めました。要望です。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-009"},{"speaker":"木村委員","kind":"質問・要望","question":"頭に入ってくるのではないかと思うんですけれども、もしそういうことができたら、やってほしいと求めました。ちょっとお答えください。","respondent":"鈴木防災課長","answer":"１点目の穴をあけてつるすようにする場合には、もう１つのほうの大きな紙１枚で重要な項目だけをわかるように掲示できるようなもの、いただいたアイデアも含めて検討させていただきたいと思います。","id":"exchange-010"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"委託費がどれぐらいなのかということを１つ教えていただきたいのと、できればこの次の１１月２９日の委員会に示していただいて、いかがか尋ねました。","respondent":"鈴木防災課長","answer":"先ほど申し上げましたように、１１月２９日までにこのような具体的な形にしてお見せできるレイアウトとか、構成を用意することは難しいかと思います。いずれにしましても、また皆様にこの場でご報告する必要があると考えておりますので…","id":"exchange-011"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"素案の段階でぜひ意見が言えるような場をつくっていただきたいと思うんですけれども、その点、後でお聞かせください。自分のところがどうなるのかということをイメージ、ぜひそのあたりをご検討いただきたいと思うんですけれども、いかがか尋ねました。","respondent":"鈴木防災課長","answer":"こういう意見をいただいたことに関してはこのような形で反映させていただきましたという説明になるのかはこちらでもう一度検討させていただきたいと…申しわけありませんが…","id":"exchange-012"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"これをどう生かして、この機会に防災意識をより高めて地震に備えるかということが求められていると思うんですけれども、荏原消防署に伺ったときに。そういう区民啓発のツールとしてこれを使って知らせていくというふうな取り組みもされたらいいんじゃないかと思ったんですが、いかがか尋ねました。","respondent":"鈴木防災課長","answer":"それともう１点、たびたび申しわけありません。先ほど申し上げましたように、区として行う啓発活動の中で、これを活用する場面も少しできないかというようなことを検討してみたいと考えております。","id":"exchange-013"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"災害からどう守るかということになりますので、どうやってやっていくかというためハンドブックというところで、この１行だけなんですよね。そういうハンドブックにしていただきたい、そこの点を１点、お聞かせほしいと求めました。","respondent":"鈴木防災課長","answer":"それは現在も考えているところでございまして、火災、ご指摘いただいた部分も取り上げたいと考えております。特に強調するということは、現在のところでは、申しわけありませんが考えていないところです。","id":"exchange-014"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"建物倒壊で亡くなったという方が８割を超えているという状況なので、また火災の出火率というのも並行している部分ということがあると思うんです。そういうことからいえば、そこら辺のところの区の認識はいかがか尋ねました。","respondent":"鈴木防災課長","answer":"ご指摘のように、確かに耐震は大切です。初期消火体制、どちらが大事ということではなくて、トータルで備えていただくという姿勢で考えているのが現在の区の考え方です。","id":"exchange-015"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"一撃で命を落とす方がこれだけたくさんいるわけですから、倒れてしまったら、そういうところでは。耐震化に一歩進むような、そういうハンドブックにしていただきたいと、その前提として耐震化というところを強調していただきたいという思いなんです。","respondent":"鈴木防災課長","answer":"それぐらい重要だということは区も認識しておりますが、「地震に備える」という中で必要な項目をそれぞれ挙げていきます。そういうことは現在考えておりませんで、身の安全の保護の仕方とか、トータルで理解いただくような形の構成にしたいと考えております。","id":"exchange-016"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"やはり私は巨大地震から命と財産を守る、そのためにどういうふうなことが大事かというところで区民が認識できるような形にしていただく、私はそのためには耐震というのは特に強調するということが本当に大事だということを改めて要望させてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-017"},{"speaker":"沢田委員","kind":"質問・要望","question":"その辺のところのご意見をお聞かせいただきたいのと、今回、こういった形での同じような大きさの同じような量なのかということをお聞かせください。全世帯配布ということで、来年の３月ということですけれども、どういうふうな形で全世帯に配布をされるのかということを説明を求めました。","respondent":"鈴木防災課長","answer":"それからページ数ですが、一応、現時点では、先ほど申し上げた主な変更点を踏まえてページ想定をして、一応、契約をしています。３点目の全戸配布ですが、きめ細やかに、１戸ずつ各世帯に配れるような形で配布したいと考えております。","id":"exchange-018"},{"speaker":"沢田委員","kind":"質問","question":"会社にも１冊、やはり必要な部分もあるんじゃないかと思うので、区内の企業に対しての配布ということはどのように考えられているんか尋ねました。","respondent":"鈴木防災課長","answer":"それは現在も区としても認識はしておりまして、あれは事業者向けのものを用意しまして、それはお配りしています。現時点では、企業の方へのこういう重要情報の提供につきましては今後の検討課題ということで検討させていただきたいと思います。","id":"exchange-019"},{"speaker":"大沢委員","kind":"質問","question":"この間の３・１１を踏まえて、課長が今し方、区民の個別世帯に云々ということのお話をいただきました。見た限りでは、そこのところをどういうふうに捉えて、どういうふうにこれは反映されていくのかをお伺いしたい。","respondent":"鈴木防災課長","answer":"先ほど説明した目次にも、実は出てまいりません。つまり、よそからの利用者の方に関してはこれを事前にお渡しすることはできませんが、しっかりと共有して対策ができるようにしたいと考えております。","id":"exchange-020"},{"speaker":"大沢委員","kind":"質問・要望","question":"鉄道事業者との関係の中で、この連絡先に鉄道事業者を考えていかれるかどうか、そこのところはどのような考えを持っているのかを教えていただきたい。","respondent":"鈴木防災課長","answer":"１つ、ＪＲ東日本テレホンセンターというものがありますが、これは個別の駅の対応窓口ではございませんので、ＪＲ全体の情報をとれるところです。先方も区民の方個別にお問い合わせをいただいても対応し切れないので、多分、災害時には適切かなと考えているところです。","id":"exchange-021"},{"speaker":"大沢委員","kind":"質問","question":"課長も計画を立てている当事者なのでおわかりになる。このところを区民の方は、どっちへどういうふうにしたらいいかということはわからないので、いかがか尋ねました。","respondent":"鈴木防災課長","answer":"確かに区民の方が災害時に適切な行動をとるためには情報は大切なものです。今いただいたようなご意見、区民の方がどういう情報をどういう手段を使って手に入れるかというところはしっかりとお知らせしたいと考えております。","id":"exchange-022"},{"speaker":"大沢委員","kind":"質問","question":"私がお伺いしたところで、目的がありまして、主な変更点が書いてあります。方針なり指針がありましたら、今、お伺いしたいです。","respondent":"鈴木防災課長","answer":"説明の中でうまく伝わらなかったのだと思いますが、身の安全を守るための情報提供、またその啓発です。全体的な方向性、レイアウト、イラスト等を変えてイメージを一新」というところが大もとの編集の上で常に立ち返る方向性だと認識しております。","id":"exchange-023"},{"speaker":"大沢委員","kind":"意見","question":"課長が認識をされていて、僕は今、説明を聞いてわからない。各論に入る前の総論であるから、これは別立てで示しておく必要があったんじゃないかと思うんですけれども、どのようにお考えになりますかとの意見を述べました。","respondent":"鈴木防災課長","answer":"主な変更点ではなくて、まず前段として目的があって、すみません。資料のつくり方が至らなかったことはおわび申し上げます。","id":"exchange-024"},{"speaker":"大沢委員","kind":"質問・要望","question":"４回、５回ということでご答弁いただきましたけれども、結構です。改めてお伺いしたいと思いますので、せっかく委員会資料ですので、そこのところはお願いをさせていただきたいと思って質問を終わります。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-025"},{"speaker":"阿久津委員","kind":"質問・要望","question":"先ほどからお話が出ているように、現行版、そして次回版にしても、内容的にはすばらしい内容だと思います。１つお伺いしたいのが、そういうところを入れていただきたいと思うんですが、その点はいかがか尋ねました。","respondent":"鈴木防災課長","answer":"実は目次にはあらわれないんですが、現在も似たような例はあるんですが、本編の中にコラムのようなものを次の版上でも考えております。例えば現在のハンドブックの６ページをご覧いただきますと、その中でご意見いただきました教訓についても取り上げていきたいと考えております。","id":"exchange-026"},{"speaker":"阿久津委員","kind":"質問・要望","question":"コラムというものが入るということで、ありがとうあります。最後、釜石の奇跡の記事を読まれるという、ぜひそういったところを魂を入れていただくというところでやってほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-027"},{"speaker":"高橋委員","kind":"質問","question":"せっかく３９ページの危険度のものがあるので、こういうふうにするかどうかは別なんですが、まとめて３９ページにあればいいのかなと思いました。それから、あと、これも私が聞き漏らしたのかもしれませんが、３７ページのハザードマップは平成１５年の東京都の調査なんか尋ねました。","respondent":"鈴木防災課長","answer":"これは３８ページの右上を見ていただきますと、この説明が書いてありますが、実は平成１６年に都で制作したものを引用しているものです。これは職員向けに今年の３月発行いたしました災害初動対応マニュアル等でも、写真はそういう新しいものにかえさせていただきたいと思います。","id":"exchange-028"},{"speaker":"向委員","kind":"質問・要望","question":"５個ぐらいしかないと思うんですけれども、なおかつ、普通の避難所でも赤い太線で囲ってあるじゃないですか。なので、すべての情報を区民が知っていればいいのかどうかだけは私は検討していただきたいと思ったので、お考えをお願いします。","respondent":"鈴木防災課長","answer":"この辺はご意見いただきました観点でもう一度必要な情報を精査して、より見ていただいて、本当に活用できる地図にするという方向で改善させていただきたいと思います。","id":"exchange-029"},{"speaker":"武内委員","kind":"質問","question":"先ほど沢田委員との質問のやりとりの中で出た防災地図、防災地図は今、もう在庫がほとんどなくなってしまっていますよね。例えば会社に行くにも、ぱっと見るみたいな意味合いがあると思うんですけれども、それは今後どう考えているのかということは。","respondent":"鈴木防災課長","answer":"今回、ハンドブックの改訂で差し替えをしますので、いずれはこの地図も更新しなければならないということは考えております。現時点、その内容も踏まえまして、防災地図も次のステップでまた更新をして配布するというようなことで考えたいと考えています。","id":"exchange-030"},{"speaker":"武内委員","kind":"意見","question":"私が思っていた防災地図というのはもう１つ古いタイプの、本当に手で持てるぐらいのものが前、あったじゃない。ポケットに入れたりとかってできたんだけれども、あれは、一切ああいうことはもう考えないということなのかとの意見を述べました。","respondent":"鈴木防災課長","answer":"現在、防災課にその折り込みの小さなタイプの携帯用の地図というのが在庫がなかったもので、イメージがなかったもので、失礼いたしました。別の使用方法を想定したものについては検討させていただいて、そういうものとあわせまして、今後の検討課題とさせていただきたいと思いま…","id":"exchange-031"},{"speaker":"木村委員","kind":"意見","question":"３・１１のときに新聞、それからテレビ、すべてにおいて想定外、想定外という言葉がものすごく多く出たと思います。今回は３・１１の場合は津波ということだったんですけれども、想定外ということとすれば、何が一体想定外だと思いますかとの意見を述べました。","respondent":"松代防災まちづくり事業部長","answer":"１つ事例を挙げるとしますと、今、津波対策をやっております。それに対して今の防潮堤の高さはＴ.Ｐ.で３.５ありますというような話でご説明をしました。","id":"exchange-032"},{"speaker":"木村委員","kind":"質問","question":"津波が来ても２.６ｍですか、多分、津波のことが心配だなと思います。ありがとうございました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-033"},{"speaker":"井上委員","kind":"質問・要望","question":"次がどうとか、そこはこれからちょっと検討していただきたいなというふうに、それがわかりやすいというところの表記だろうと思います。全体的に火災のほうが心配な項目なのかなというような気がしまして、もし意味がないのであれば、その辺もご検討いただけたらと思いました。","respondent":"鈴木防災課長","answer":"３番目と４番目の津波対策と火災対策の順番ですが、これは、すいません。資料ではこういうふうにお示ししたんですが、これは変更させていただきたいと思います。","id":"exchange-034"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"火災対策と津波対策の順番は火災対策を先にしていただきたいということだったので結構です。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-035"},{"speaker":"本多副委員長","kind":"質問・要望","question":"１点だけ質問します。それ以外、例えば水上で何かがあったときにも３桁でつながったりするところがあるじゃないか尋ねました。","respondent":"鈴木防災課長","answer":"緊急先リストの電話番号の件ですが、確かにご意見にありましたように、３桁で、本当の緊急性があるゆえに多分、３桁で設定している番号だと思いますので、それはぜひ取り入れさせていただきたいと考えております。","id":"exchange-036"},{"speaker":"阿久津委員","kind":"質問","question":"まとめていただいてありがとうあります。９月２７日の主な意見（案）の中で、今回の中からこれは削除されているんですが、そこについての削除された理由についてお伺いしたいと思います。","respondent":"南委員長","answer":"しかし、今回は大きな地域防災計画の見直しの１回目に当たって、人命を最優先にしていきたいと考えたんです。時期を見て、しっかりとそれは反映していけるようにしていきたいと考えたので、削除することにいたしました。","id":"exchange-037"},{"speaker":"阿久津委員","kind":"質問・要望","question":"まさに、今言わずしていつ言うのかという点があったものですから、私としてはこれが削除されたのは非常に残念に思っております。もしこれを復活していただけるのであれば復活していただきたいですし、私にご相談していただいた区民の方に大変申しわけないなと考えています。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-038"},{"speaker":"南委員長","kind":"質問・要望","question":"今の改めてのご意見を伺って、この委員会として判断していきたいと考えていますけれども、そういう進め方でいいですか。阿久津委員のご意見を伺った中で、皆さんは改めてどうかということで、ぜひ忌憚なくご意見を出してほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-039"},{"speaker":"大沢委員","kind":"質問","question":"進め方なんですけれども、今日、阿久津委員から話が出たのはわかるんですけれども、前回、まとめについて正副委員長に一任したんじゃないんですか。だから、それで一任して、前回、承諾をこちらの委員のほうもしているわけですから、こういうときに議論云々というのは的がずれている。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-040"},{"speaker":"井上委員","kind":"提案","question":"そういう提案があれば、それが委員会運営だと思いますので、よろしいんじゃないでしょうか。人命が最優先であり、その中で共存できるような具体的な対応というようなことを示していただけるような方向で区も検討してほしいなというところでとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-041"},{"speaker":"大沢委員","kind":"質問","question":"この委員会自体の取り決めは重いわけでして、それは一任ということを今、簡単に翻って、議論が出たから話をしようって、何のための一任なんですか。委員会の取り決め事項の重さ、軽さにもかかわることなので、そこのところは委員長、強く私はお話をして、ご理解賜りたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-042"},{"speaker":"大沢委員","kind":"質問","question":"阿久津委員のところまでは理解をしました。では委員会の取り決めって何だったんですかという、まさにその疑念を生じざるを得ないようなご発言があったので、私は発言させていただいた。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-043"},{"speaker":"渡辺委員","kind":"質問・要望","question":"冒頭の委員長の説明のように、今日という中での後のチェック、最終チェック、文言整理だという認識でよろしいんでしょうか。その確認です。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-044"},{"speaker":"武内委員","kind":"意見","question":"今回、両方入れていただいていいんですけれども、(4)の1)、2)、3)の内容を見ると、全部、津波しか言葉として入っていないんです。どうせもんでもらうなら、一緒にやったほうがいいかなと思ったんですがとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-045"},{"speaker":"渡辺委員","kind":"確認","question":"確認の上、発言します。復活といいますか、先ほどの文章、戻ってもいいのではないかと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-046"},{"speaker":"渡辺委員","kind":"質問・要望","question":"文面を確認したところ、先ほどのやりとりの趣旨に沿って、人命にかかわる部分に集約してまとめていただきたい。そこは本当にそれこそ正副委員長一任でやってほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-047"}]},{"id":"topic-02","title":"品川区地域防災計画素案概要説明","agenda":"品川区地域防災計画素案概要説明","exchanges":[{"speaker":"井上委員","kind":"質問","question":"２部、３部を一緒にして１３編に変えるということなのか、そこの説明をお願いします。","respondent":"高山防災計画担当課長","answer":"委員ご指摘の２部、３部を統合してということではございませんでして、編そのものは分けする構成でおります。それに加えて新たな検討事項、この１３編に、新たにこの機会に大きく体系を整理し直したというような意味です。","id":"exchange-048"},{"speaker":"井上委員","kind":"質問","question":"ちょっとよくわからないんですけれども、そもそも震災編というのはなかったところに、この現在ある災害予防計画というようなところに、このこれから新しく入れるところ、変更も含めて、入れ込んでいって、ここにあるほとんどが残るという意味か尋ねました。","respondent":"高山防災計画担当課長","answer":"平成１９年度版に書かれております多くのことを当然ながら踏襲するということにはなります。それぞれの該当する項目に引き続き内容を横引くような形で、必要な部分について平成２４年度版にも反映していく、そのような意味です。","id":"exchange-049"},{"speaker":"井上委員","kind":"質問","question":"災害予防計画の平成１９年度１編は、災害に強い都市づくりというところが防災機関の業務大綱とか、そういう形で変えていくというふうなことで説明をされているということか尋ねました。","respondent":"高山防災計画担当課長","answer":"引き続き平成２４年度版に踏襲されているというような意味合いでございまして、ここに盛り込むべき内容につきましては平成２４年度版にもしっかり反映されている、そのようなことです。","id":"exchange-050"},{"speaker":"井上委員","kind":"提案","question":"以前からこういうものが区民も含めて見られるように、理解できるようにという提案は何度かしているんですが、その辺はどういうふうに生かされているんか尋ねました。","respondent":"高山防災計画担当課長","answer":"次回ご説明する中で、この辺のところをそのようなご指摘を受けて手を加えたというようなことで工夫したということでご披露したいと考えております。もう１つ、ああいったもので、そのような工夫などで区民の皆様にご理解いただけるような形を考えていきたいと考えております。","id":"exchange-051"},{"speaker":"武内委員","kind":"確認","question":"今後の予定のところの確認なんですけれども、平成２５年２月の品川区防災会議のここの最終の決定のところでは出てくるのか、どの辺でこの風水害編はリンクしてくるのかということを説明を求めました。","respondent":"高山防災計画担当課長","answer":"まさに先ほどご説明の中で、素案は素案として一旦は公表して世に出していくといいますか、区民の皆様にご覧いただけるような形にまずはします。内容の大半を準用する関係で、風水害編についてのパブリックコメント等は特段予定してございませんでして…","id":"exchange-052"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"この地域防災計画の作成なんですが、これを作成するに当たっては、どこかのコンサルタント会社とかに委託されているということがあるんでしょうか。委託費がどれくらいだったのかということを１つお聞かせいただきたいのと、どういうメンバーで、そこら辺のところを説明を求めました。","respondent":"高山防災計画担当課長","answer":"それから検討の体制ですが、検討に当たってテーマを持たせまして、分科会というような形で多くの課が参加するような形で進めてまいりました。避難対策についての検討ですとか、実際に計画を動くもの、いろいろな意見をもらいながら計画に反映しているといったところの検討体制で…","id":"exchange-053"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"どんな分科会がどれくらいされてきたのか、どんな分科会があって、どれくらいの会議で今回の計画がつくられることになったのかというあたりをもうちょっと詳しくイメージできるような形でご説明いただけたらと思いますとの意見を述べました。","respondent":"高山防災計画担当課長","answer":"実は４つほど分科会を組織して、この間、検討作業を進めてまいりました。そういった部分についての説明などもさせていただきながら、避難者対策というような形での分科会、その４つを組織して進めてまいりました。","id":"exchange-054"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そういう形で今回、私はこれは区が、こういう計画があるんだということを区民にわかってもらうということがすごく大事なのではないかと思うんです。どこにどう資料を置いて、説明会とかなんかはどういうふうにするとか、そういう区民への周知ということについてお聞かせいただきたい。","respondent":"高山防災計画担当課長","answer":"この計画そのものの説明というよりは、そういったことについては折に触れてご説明の機会などがあれば、説明をさせていただいておるところです。１２月に区政モニター集会がございまして、限られた人数ではありますが…","id":"exchange-055"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そういう点で言えば、パブリックコメントも求めるわけですから、私は少なくとも１３地域センターごとに説明会を開いていただきたい。この震災対策というところでは去年の３・１１を経験して、ぜひ説明会をやっていただきたいと思うんですけれども、いかがか尋ねました。","respondent":"高山防災計画担当課長","answer":"１３地区での説明会等の、そのような形での区民への説明ということは、この計画については考えてございません。計画そのものの専門的な部分についての周知ということについて説明会を通じての必要性ということはそれほど考えておりませんので。","id":"exchange-056"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"それを見て、私は少なくとも１３町会と言いましたけれども、１回も説明会をしないでパブリックコメントをしていくという今の区の考えでしょうか。広報とホームページとその冊子を各施設に置いておくというだけしか考えていないということか尋ねました。","respondent":"高山防災計画担当課長","answer":"しかしながら、これは区長からの指示ということもあるんですが、小刻みにでも継続的に改訂を続けていくべきだというような指摘があります。区民を代表される委員の皆様におかれましては、そういった部分を十分に取り込むような形で計画に生かしてまいりたいと考えております。","id":"exchange-057"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"３・１１を特に経験した今だからこそ、３・１１を経験した初めての計画の改訂だからこそ、求められているんだと思うんです。区民の意見を聞いて、そして実効性ある中身に変えていくということで、そういう説明会をしていただきたいということを強く要望したいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-058"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/167861?Template=document&Id=6420#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=17&TermStart=2012-01-01&TermEnd=2012-12-31"}],"sourceMeta":{"pages":0,"characters":48014,"voices":127}},{"id":"h24-20121126-6","meetingId":"h24-cm11","date":"2012年11月26日","dateIso":"2012-11-26","committee":"区民委員会","time":"午前１０時００分～午後２時０９分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を22件整理しています。","topics":[{"id":"topic-01","title":"の区民集会所の利用状況","agenda":"の区民集会所の利用状況","exchanges":[{"speaker":"山内委員","kind":"意見","question":"廃止になるのかというような対象にはならない場合、改めて見させてもらって感じたんですけれども、そのあたりというのはどうなんだろうか。やはり使っている人もいるし、なくなったら不便になる人もいるだろうなと思ったりしたので、ちょっとそのあたりのところを説明を求めました。","respondent":"久保田地域活動課長","answer":"利用状況にもよりますけれども、年間にしておおむね１００万円から２００万円台ぐらいの維持管理の経費が、たしかかかっていると認識しています。耐震改修促進計画、また建て替えるかといったところも含めた検討が必要かなということで…","id":"exchange-001"},{"speaker":"武内委員","kind":"質問","question":"基本的にこの間の質疑の中でも、これの利用率を高めるには周知をしなきゃいかんと。その根本のところで予約システムに組み入れていくというのが一番の周知になると思うんだけれども、そこは考えないんか尋ねました。","respondent":"久保田地域活動課長","answer":"今、その荏原西区民集会所につきましては予約システムに入ってございません。広く利用等も見込まれるところではありますけれども、施設予約システムのほうに載せてという考えは今の時点では私どもでは持ってございません。","id":"exchange-002"},{"speaker":"武内委員","kind":"質問","question":"例えばその方たちが今までの経緯があるわけですから、優先的に最初にこの曜日のこの時間帯は使っているとわかるわけですから、そこはとりますよと。そこをとってあげた上で、それ以外の枠をシステムに載せるというような検討はできないものなんか尋ねました。","respondent":"久保田地域活動課長","answer":"載せないの検討というのは私どものほうで考えて、そういったものをやれるかどうかということは検討はしていきたいとは思っております。そうした一定の方向性、廃止も含めた検討もしていかなければならないのかなということで、私どもは考えているところです。","id":"exchange-003"},{"speaker":"武内委員","kind":"質問・要望","question":"やはりその予約システム、そこをやった上でその廃止に向けて検討していただきたいと思うので、そういう要望をさせてほしいと求めました。最初の利用率のところでもう一回確認ですが、三つ掛ける午前・午後・夜間の３通りなので、さっき説明がありましたが。","respondent":"久保田地域活動課長","answer":"ただ、その利用可能日の算出に当たりましては、保守点検の日が月に１回ありますので、その部分は利用可能日の日数から除いてあります。今、委員がおっしゃったように、そういう形でつくってあります。","id":"exchange-004"},{"speaker":"藤原委員","kind":"意見","question":"下りまして、やはりお客様は、区民の方の利用率は少ないだろうなと感じました。今、それこそ本当に本日の視察において感じているんですけれども、そのことについてはどういうふうに考えていらっしゃいますかとの意見を述べました。","respondent":"久保田地域活動課長","answer":"３階部分にあるということで、以前からエレベーターを設置してもらいたいとか昇降機をつけてもらいたいというご要望は頂いていたところですけれども。構造等からいろいろと見直しを考えているところでは、いろいろな今後の活用という検討の中で…","id":"exchange-005"},{"speaker":"藤原委員","kind":"質問","question":"これは室内じゃないですから、雨が降ったときとか事故はなかったのかなとか、滑るんじゃないかなというようなことをすごく思って降りてまいりました。だからと言って５０％、６０％に上がるという可能性もちょっと考えられないので、その辺についてはいかがか尋ねました。","respondent":"久保田地域活動課長","answer":"私どもは、やはり一番問題になっているのは耐震の関係があろうかと考えています。これにつきましては、それが今の時点では平成２６年度末までにということで、それまでには結論を出さなければならないと考えているところです。","id":"exchange-006"},{"speaker":"井上副委員長","kind":"質問・要望","question":"そういうことを事務事業評価みたいなところでやるのであると、ある程度統一するということは区の中で検討していただいたほうがいいと思うんです。その辺、全庁的にちょっと見直すなら見直すということでしていただきたいと先ほどのお話を聞いて思ったのですが、どうか尋ねました。","respondent":"久保田地域活動課長","answer":"なかなか従前の予約システムですと手計算とか、いろいろ集計が難しかったというところがございまして、平成２２年度のときに改修しているんです。１クリックというか、文化スポーツ振興課等とも話をしながら、検討はさせていただきたいとは思っているところです。","id":"exchange-007"},{"speaker":"井上副委員長","kind":"質問・要望","question":"先ほど来廃止をするかどうかという議論のときに、そういったことも含めての資料提供ということで、議論を深められるように工夫していただきたい。これは要望でお願いしたいと思います。","respondent":"久保田地域活動課長","answer":"集計表のほうの１点目のご質問について、ちょっと私の説明が足りませんで、我々が確認しているやり方はですね。今回は、より正確な数字を出すためのやり方に改めたというところでお示ししたものが、今回の資料です。","id":"exchange-008"},{"speaker":"井上副委員長","kind":"質問・要望","question":"そういうところで、そういうことがなければずっとそういう算出をされていたということのほうが、逆にちょっと問題なのかもしれないと思いました。やはりほかがどうかというのは、企画とかそういったところも含めて、やはり問題提起をしてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-009"}]},{"id":"topic-02","title":"の品川区立創業支援センターの現状","agenda":"の品川区立創業支援センターの現状","exchanges":[{"speaker":"藤原委員","kind":"質問","question":"改めてお伺いしますが、品川区がやってきている創業支援センターの目的を説明を求めました。","respondent":"福島ものづくり・経営支援課長","answer":"創業支援ということによりまして、区内の地域産業の振興を図っていくというものになります。","id":"exchange-010"},{"speaker":"藤原委員","kind":"質問","question":"まさに、今、ものづくり・経営支援課長が答弁していただいた目的がありますよね。この各支援センターが目的をどういうふうに達成しているのかというのを、区としてはどのように捉えているのか、教えていただければ。","respondent":"福島ものづくり・経営支援課長","answer":"この三つの製造業系の創業支援センターにつきましては、入居の段階で、それが寄与があるということで入居していただいているです。西大井創業支援センターの小さいところから、どのぐらい企業が拡大してきたのかということは見てみたいとは考えているところです。","id":"exchange-011"},{"speaker":"藤原委員","kind":"質問・要望","question":"けれども、創業支援ですから創業させることも目的の一つかもしれませんけれども、そこは押さえていただきたいと思っています。それと、そういうこともあって、これからの創業支援センターの課題というのは、今、考えていることは何か尋ねました。","respondent":"福島ものづくり・経営支援課長","answer":"そういうところは、先ほど言いましたように来年１０周年になりますので、その辺は全部もう一度見直していきたいと考えてはあります。どのような成果が上がってきたのか、その辺のところを総括していく時期であろうと考えていますので、平成２５年はしっかりしたいと考えています。","id":"exchange-012"},{"speaker":"武内委員","kind":"質問・要望","question":"ちょっと基本的なことを教えていただきたいんですが、インキュベーションマネージャーという方が、配置されていると捉えていいんですか。それから、あとどのくらい区がこの方に経費を払っているのかというのが大体わかれば、教えてほしいと求めました。","respondent":"福島ものづくり・経営支援課長","answer":"武蔵小山創業支援センターの施設運営の委託費用ですけれども、運営とあと施設管理におきましては、そういった委託をしている部分です。逆に西大井創業支援センターにつきましても、そういうものを差し引きまして、その者とインキュベーションマネージャーに充てる経費だろうと。","id":"exchange-013"},{"speaker":"武内委員","kind":"質問","question":"プラス、オフィスの方も受けられるんでしょうか。そうすると天王洲創業支援センターとの違いというんですか、そこのコンセプトとか考え方の違いを説明を求めました。","respondent":"福島ものづくり・経営支援課長","answer":"賃料も少し高いので、なかなかすぐそのまま、あまりそういういわゆるインキュベーション的な支援は必要とされない方が入っているというのが実態です。両方ともそういった施設運営ですとか、あるいはアドバイザーをやっているような会社…","id":"exchange-014"},{"speaker":"武内委員","kind":"質問","question":"ただ、ここに入っている方たちはそれを自分で雇う必要がないわけでしょうから、家賃プラスアルファの恩恵を得ていると考えておけばいいのかなと。天王洲創業支援センターとの関係があるのでどうなのかなと思ったら、天王洲は場所的なもので高いけれども、二つなんですけれども。","respondent":"福島ものづくり・経営支援課長","answer":"西大井創業支援センターのほうの（１）創業支援スペースの場合は、募集をしますとすぐここは埋まるという状況が続いています。実は今、そういった意味ではちょっと高いのかなと思いますが、何とか入居者を見つけていきたいとは考えてあります。","id":"exchange-015"},{"speaker":"石田（ち）委員","kind":"質問","question":"今、家賃・使用料の話があったんですけれども、近隣が下がってきているのでというその時点で、こちらも下げていく、同じようにしていくという考えはしなかったのかというのと、あと今後、周りの状況も見ながら、これが変わっていくということはあり得るんか尋ねました。","respondent":"福島ものづくり・経営支援課長","answer":"家賃につきましては上がり下がりが激しいので、それに区として対応していくというのはかなり難しいと思います。条例で決めているということもありますし、今の条件の中で行っていきたいと思っています。","id":"exchange-016"},{"speaker":"井上副委員長","kind":"質問・要望","question":"天王洲創業支援センターでは６８０万円ぐらいとすると、この辺の差というのはどういうものでこれだけの開きが出てきているのかということ。これからどういうふうにこれを考えていくのかということは、ちょっと教えてほしいと求めました。","respondent":"福島ものづくり・経営支援課長","answer":"下に平成２３年度に行いました創業塾、全１８回の塾でしたけれども、そのうち半数以上が実際にもう創業された。そういった形で実績を上げていきたいと考えているところです。","id":"exchange-017"},{"speaker":"井上副委員長","kind":"意見","question":"これから１０年たった評価ということを先ほどもおっしゃっていましたので、きちんと見ていくということをお願いしたいと思います。おおむね３年以内の法人にチャレンジショップとか賃貸オフィスとかいうんですけれども、どういった種類があるのか、どんなところがありますかとの意見を述べました。","respondent":"福島ものづくり・経営支援課長","answer":"２年たってしまったというような人の場合ですと、こういうところでおおむね３年以内にとか、このようなことをさせていただいています。やはりそういうところも入れておかないと救済ができないということもありまして、こういったものを載せている次第です。","id":"exchange-018"}]},{"id":"topic-03","title":"の行政サービスコーナーの利用状況","agenda":"の行政サービスコーナーの利用状況","exchanges":[{"speaker":"本多委員","kind":"質問","question":"この人員配置で大井町行政サービスコーナーが人員１２名、武蔵小山行政サービスコーナーが人員９名ですけれども、その募り方というのはどのようにしているんか尋ねました。","respondent":"井浦戸籍住民課長","answer":"現員の配置としては平成１９年度以降を見ますと９名ずつ配置してございまして、大井町行政サービスコーナーについては若干増加させまして、現員１２名ということで行っていたという経緯です。","id":"exchange-019"},{"speaker":"武内委員","kind":"質問","question":"どちらかというと駅に近くて、区民が忙しい中でわざわざ地域センターとか区役所まで来なくてもできる、利便性の角度からここにやっているという考えでいいんか尋ねました。","respondent":"井浦戸籍住民課長","answer":"その２カ所につきましては、武蔵小山行政サービスコーナーについては駅の周辺の場所ということで、通勤あるいは通学の途上で気軽に住民票等の行政証明を受けるということを目的にしている施設です。","id":"exchange-020"},{"speaker":"武内委員","kind":"質問","question":"今後そういう部分ではどこに視点を置いて、例えば声が出てきたときにどういうふうに考えていくのかというのは、何か指針というのはお持ちか尋ねました。","respondent":"井浦戸籍住民課長","answer":"品川区全域について、あまねく利便性の向上ということでは、等しくやっていく責務が区にはあります。ないところもありますので、その中でバランスを考えて、具体的な設置という方針でやっていきたいと考えています。","id":"exchange-021"},{"speaker":"井上副委員長","kind":"質問","question":"一つだけ、嘱託非常勤職員と専門非常勤職員、先ほど少し説明いただいたんですけれども、もう一度その違いとどういう要件なのか、お願いします。","respondent":"井浦戸籍住民課長","answer":"再任用後６４歳になった職員を１年間嘱託非常勤ということで、非常勤という形で身分を移させていただきまして、雇用するものです。この６５歳のいわゆる再任用と嘱託非常勤の任期を満了した職員について、専門非常勤ということで、戸籍住民課として雇用しているという職員です。","id":"exchange-022"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/118408?Template=document&Id=2652#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2012-01-01&TermEnd=2012-12-31"}],"sourceMeta":{"pages":0,"characters":24180,"voices":64}},{"id":"h24-20121126-7","meetingId":"h24-cm11","date":"2012年11月26日","dateIso":"2012-11-26","committee":"厚生委員会","time":"午前１０時００分～午前１１時４６分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を28件整理しています。","topics":[{"id":"topic-01","title":"平成２４年請願第１４号、ウルトラ・オーファンドラッグ（患者数が特に少ない希少疾病用医薬品）開発促進・支援のための法整備等を求める意見書の提出に関する請願","agenda":"平成２４年請願第１４号、ウルトラ・オーファンドラッグ（患者数が特に少ない希少疾病用医薬品）開発促進・支援のための法整備等を求める意見書の提出に関する請願","exchanges":[{"speaker":"中塚副委員長","kind":"質問","question":"現状、どういう仕組みになっているのか、そこを改めて伺いたい。当然、患者数が少なければ、採算性が取れないという関係になるわけですけれども、そこへの支援の現状を、改めて伺いたいと思います。","respondent":"工藤品川区保健所生活衛生課長","answer":"説明で申し上げましたように、オーファンドラッグの中にウルトラ・オーファンドラッグも定義的には全て含んでいるということになってあります。平成２２年度ベースの実績ですけれども、いわゆる支援策として６億５,０００万円ほど計上しておりますので、国の現状です。","id":"exchange-001"},{"speaker":"塚本委員","kind":"質問・要望","question":"もしわかれば教えていただきたいんですけれども、私がかつて見た範囲では、ものすごい数があったんじゃないかと思うんです。どれぐらいの数がいると、想定でもいいですけれども、もしわかれば教えていただきたいと思うんです。","respondent":"工藤品川区保健所生活衛生課長、福島品川区保健所荏原保健センター所長","answer":"品川区内における患者数ですけれども、大変申しわけございません、ちょっと私ども、そこの部分まで把握しておりません。ただ、いわゆる難病、特定疾病と言われるものは、区内ではございませんけれども、全国的には数千… 計８１疾病に関しては医療の公費負担がありまして、平成２３年度で、品川区で難病の医療費負担の申請をされた方が２,９７１人いらっしゃる。これは、認められた８１疾病に関しての医療費の公費負担ということです。","id":"exchange-002"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"一日も早く、というご要望ですので、結論を出すということです。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-003"},{"speaker":"石田（秀）委員","kind":"質問","question":"初めて勉強させていただいたというか、不勉強なところもありまして、お話を伺ったというところであります。意見書を提出してほしいということでありまして、意見書提出を含めて、採択。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-004"},{"speaker":"若林委員","kind":"質問・要望","question":"塚本委員のほうからの質問がありましたけれども、それから支援事業として８０を越える、そういうふうにとどまっていると。国のほうでしっかりと取り組んでいただきたいという、公明党といたしましては、意見書を出すというこの請願の採択をお願いしたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-005"},{"speaker":"向委員","kind":"質問・要望","question":"彼女の３２歳までの１０年ちょっとと、私のこの１０年ちょっとを考えると、やっぱり胸が詰まる思いが大変しました。今後もさらに支援を続けさせていただきたいなと、採択ということで、。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-006"},{"speaker":"中塚副委員長","kind":"意見","question":"とりわけ経済格差は直ちに正していかなければいけないと思います。市場の中で採算性が取れない、だからこそ、国の支援が必要だと思いますので、意見書を出すことも含めて採択でお願いしますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-007"}]},{"id":"topic-02","title":"平成２４年請願第１５号、軽度外傷性脳損傷についての区民への啓発・周知と、国への意見書提出に関する請願","agenda":"平成２４年請願第１５号、軽度外傷性脳損傷についての区民への啓発・周知と、国への意見書提出に関する請願","exchanges":[{"speaker":"塚本委員","kind":"質問・要望","question":"それが大体どれぐらいのものかということが、もしおわかりであれば、教えてほしいと求めました。そういったところで考えていったほうがいいのかなとも思うんですが、その点について、お伺いしたいと思います。","respondent":"福島品川区保健所荏原保健センター所長","answer":"２００７年のＷＨＯの報告では、１０万人当り１５０人から３００人、全世界では１,０００万人の患者が発生していると考えられます。外傷性脳損症の全体の９割が、この軽度の外傷性脳損症ＭＴＢＩと考えられます。","id":"exchange-008"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"区内教育機関への周知を要望とありますけれども、どういうところへの周知や取り組みを、どういうふうに思っていらっしゃるのか伺いたいと思います。１点伺いたいんですけれども、労災障害年金が支給できるようにしてほしいと書かれておりますが、どういう基準なのか。","respondent":"永尾障害者福祉課長、福島品川区保健所荏原保健センター所長","answer":"軽度外傷性脳損傷についてのきちんとした説明ができない状態でありますので、今のところは考えておりませんけれども、積極的に行っていきたいというふうに考えております。 労災基準の認定には、こういう画像診断上での診断が必要だということで、現在はオミットされていると。神経学的検査をちゃんとやれば、現在のところでは、認定基準の中にそれが用いられているということではないと聞いております。","id":"exchange-009"},{"speaker":"中塚副委員長","kind":"質問","question":"そういうところの支援というのは、現状の仕組みの中ではどういう形になっているのか、その点を伺いたいと思います。","respondent":"永尾障害者福祉課長","answer":"直接の支援というのは難しいところですけれども、生活支援センターをやっておりまして、いろいろなさまざまな相談があります。そちらに回しながら、ご家族が具体的にどういうような対応をしていったらいいのか、そういうところのお話をしていっているような状況です。","id":"exchange-010"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"その当事者の方々のご要望だったり、生活上の悩みだったりを伺って、どのようになっているのか。現状、どうなっているのか、改めて伺いたいと思います。","respondent":"永尾障害者福祉課長","answer":"生活支援センターのほうに、デイサービスの提供の相談も、またサービスも受けることは可能にはなります。就労に関していえば、就労支援センターのほうに回して、実際の訓練と障害者のサービスにのっとったものを行っているところです。","id":"exchange-011"},{"speaker":"若林委員","kind":"質問・要望","question":"中度、重度があるということだと思うんですが、そこら辺の軽度というところの内容の確認をさせていただきたい。軽度外傷性脳損傷と高次脳機能障害との関係というんですか、それをもう１回、ちょっと整理させてください。","respondent":"福島品川区保健所荏原保健センター所長","answer":"私の説明で、極端な言い方をすると、症状はひどい場合があるということ。基準に合えば軽い状況であっても、またその後に起こり得る障害は重い場合があるということで、症状が軽度という意味ではないと理解されます。","id":"exchange-012"},{"speaker":"若林委員","kind":"質問・要望","question":"教育機関への啓発というものもご要望されているので、そういう方の９割もの方々が、そのまま軽度に分類されるんだと。その９割の方が分類されても、じゃあ９割の方が、教えていただきたい。","respondent":"福島品川区保健所荏原保健センター所長","answer":"明確な数字は、今のところはないと思われます。日本での患者数も、３０万人ぐらいではないかという専門の先生たちの推察ということで、今のところはないのではないかと思います。","id":"exchange-013"},{"speaker":"若林委員","kind":"質問・要望","question":"最後にしますけど、いわゆる推計で３０万人とかいう。そういう画像以外のものでも、医者の専門的な診療というのですか、しっかりこのご要望に沿って出していくほうがいいなと思いました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-014"},{"speaker":"石田（秀）委員","kind":"質問","question":"先ほど来、軸索の話もあって、簡単に言うと、診断基準もわからなければ、どうなっちゃうのか、今、判断も非常に難しい、推測ばっかりで。その部分については賛同もいたしますので、採択で、意見書も含めて提出していけばと思っています。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-015"},{"speaker":"若林委員","kind":"質問・要望","question":"特に１点目の、また意味を、これからしっかりと啓発してほしいと求めました。労災についても、国のほうにしっかり、議会として意見を挙げていきたいということで、採択でお願いいたします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-016"},{"speaker":"鈴木（博）委員","kind":"質問・要望","question":"請願の趣旨はわかりますので、採択ということでお願いしたいんですが、とにかく行政には、適切に対応していただきたいということを、ちょっとつけ加えします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-017"},{"speaker":"中塚副委員長","kind":"意見","question":"支給の対象や支援の仕組みをつくっていく必要があると思いますので、意見書を出すことも含めて、採択でお願いしますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-018"}]},{"id":"topic-03","title":"所管事務調査","agenda":"所管事務調査","exchanges":[{"speaker":"中塚副委員長","kind":"質問・要望","question":"それぞれの事業で、ぜひいろいろ充実してもらいたいものはたくさんあるんですけれども、幾つか絞って伺いたいと思います。居住地の周囲５００ｍ以内に云々とありますけれども、どうか、そこの状況を伺いたいと思います。","respondent":"原高齢者福祉課長","answer":"民生委員から見たときに、本人が拒否したとしても、何らかのきっかけをつくりながら中に入っていくというような形で実施をしているものです。７０歳以上だから、あるいは６５歳以上だからということでやっているわけではなく、それぞれ対応するという形にしています。","id":"exchange-019"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"それからもう１点、具体的に日常生活用具等給付事業ですけれども、自動消火装置について、伺いたいんです。いろいろな程度の基準があると伺っておりますけれども、５だったり、自分の思いどおりに体が動かなくなる状況もある。","respondent":"原高齢者福祉課長","answer":"確かにいろいろな状況の中で、さまざまな形はあろうかと思いますけれども、こちらのほうは、昭和５５年から実施をしておる事業です。補助金等々ももらいながら実施をしている事業でございまして、こういった対象者を決めさせていただいたということで…","id":"exchange-020"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"補助を受けるためには、認知症高齢者のみでなければならないというのは、区民の暮らしの実態にもっと目を向けていただきたいと思うんです。今日的に充実が求められているときだから、現在どういう状況なのか、改めて伺いたいと思います。","respondent":"原高齢者福祉課長、永尾障害者福祉課長","answer":"火災報知機を高齢者の中に積極的に設置をしてほしいということで、この間、実施してきたところです。時期に合わせた取り組みの中で、今後についても、捉えていきたいと思っているところです。 障害者につきましても、自動消火装置、それから火災警報器の日常生活用具の給付があります。精神障害者保健福祉手帳が１、２級の方で、同じような支給をしています。","id":"exchange-021"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"高齢者のほうですけれども、火災警報器を義務化したことは知っています。ひとり暮らしの方だったり、やはり対象拡大を検討すべきだと思うんですけれども、そこについてご説明ほしいと求めました。","respondent":"原高齢者福祉課長","answer":"その人、ケアマネージャーがそれぞれの所管と相談しながら、こういった事故にならないような取り組みということで実施しています。安否確認系等々についても継続して検討していくという取り組みになってありますので、トータルの中で捉えていきたいと思っているところです。","id":"exchange-022"},{"speaker":"塚本委員","kind":"質問・要望","question":"地域の協力員が見つからないというお話だったんですが、もうちょっと詳細に、どういう仕組みなのかお伺いしたいんです。協力員がそれに応じて駆けつけたところで、具体的にどのようなことを協力員に求めているのかということで、お伺いしたいと思います。","respondent":"原高齢者福祉課長","answer":"本人にかわっての対応をやってもらうということで、在宅介護支援センター、この間の対応ですし。それにかわるものということで、警備会社に鍵を預けて、何かあれば警備会社が消防庁と連携をしながら対応するというのが現行の中身になってあります。","id":"exchange-023"},{"speaker":"塚本委員","kind":"意見","question":"今のご説明でいくと、消防庁型の総数がだんだん減っていって、これは切り換えも行われているということでよろしいですね。わかりましたとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-024"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"在宅支援を求めている方はどんどん増えていくということを考えると、こういう形の中のものを、区としてもやっていくという考え方なのか。もちろん違うものもあるので、そこら辺の度合を、どう考えていらっしゃるのか説明を求めました。","respondent":"原高齢者福祉課長","answer":"そういった中で、まさに地域のお力を借りて、地域の中で地域の方々を見守っていくというような一つの取り組みの中で実施をしている事業もあります。そういった意味では、バランスをとりながら、高齢者の安全確保のために実施をしているというところで捉えているところです。","id":"exchange-025"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"そういう場合のフォローというのは、どういうふうにされているのかなということを、もう一度改めて伺いたい。ここら辺の、具体的に動きをかけているものがあれば、ちょっと教えてほしいと思うんです。","respondent":"原高齢者福祉課長","answer":"そういった中で、区民の皆様に影響がないように、個々に対応していくことが基本ということで捉えているところです。そういった補助金はないけれども、財調で対応というようなことは、私どもも思っているところです。","id":"exchange-026"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"区民の方は、世帯というと、こう言われたというと、それを信じちゃうじゃないですか。これはこうなんだけと、みんながそういうふうに説明できるような部分をぜひやっていただければと思うので、それも改めて教えていただきたい。","respondent":"原高齢者福祉課長","answer":"例えば５００ｍ以内に親族がいても、そういったことで今後も実施をしていきたいと思いますので、よろしくお願いしたいと思います。ご説明させていただいているのは、そういったものを、ご理解いただければと思います。","id":"exchange-027"},{"speaker":"渡辺委員長","kind":"質問","question":"所管質問がございましたら、ご発言をお願いいたします。〔「なし」と呼ぶ者あり〕。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-028"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/594819?Template=document&Id=3340#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2012-01-01&TermEnd=2012-12-31"}],"sourceMeta":{"pages":0,"characters":29740,"voices":88}},{"id":"h24-20121126-8","meetingId":"h24-cm11","date":"2012年11月26日","dateIso":"2012-11-26","committee":"建設委員会","time":"午前１０時００分～午後４時５６分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を103件整理しています。","topics":[{"id":"topic-01","title":"第７５号議案、品川区立区民住宅条例の一部を改正する条例","agenda":"第７５号議案、品川区立区民住宅条例の一部を改正する条例","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"２０年の契約期間が切れたら、そういう区の方針なのかということを１点お聞きしたいのと、その２点を初めに教えてほしいと求めました。","respondent":"大串住宅担当課長","answer":"２０年の契約満了、これはオーナーの方とのお約束で２０年の契約ということで借上げをしています。この２０年の契約、これが順次来ましたときには、順次これはオーナーのもとに返還をしていくという方針で今後についても進めていく方向です。","id":"exchange-001"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それともう１つは、戸数は１８戸だと思いますけれども、現在の入居率がどうなっているのかということを教えてほしいと求めました。それから、入居率の高い借上型区民住宅というのがあるのかどうなのか、そこら辺のところも教えてほしいと求めました。","respondent":"大串住宅担当課長","answer":"今後とも２０年の契約満了に伴って借上げ住宅についてはオーナーのもとに返還していくという方針に変わりはございません。この数字については、ここ数カ月変わっていないといったところです。","id":"exchange-002"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"被災者が８戸入られているということなんですが、３戸の方はどういうふうになっていくのかということと、言ってみれば。機械的にそういうふうになくさないで継続というところもぜひ視野に入れて検討していただきたいなというふうに思うんですけれども、いかがか尋ねました。","respondent":"大串住宅担当課長","answer":"まだ平成１２年に開設したばかりということで、新しい建物といったところで人気が高いのかなというふうに分析をしておるところです。借上型区民住宅については、この２０年の満了とともに、オーナーのほうに返還をするといった考えに変わりはございません。","id":"exchange-003"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そういう点では、住宅が十分に若い人たちに提供されているかといえば、なかなかそういう状況ではないと思うんです。私はぜひとも若い人たちが定住できるような、そういうところで検討していただきたいということで要望をさせてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-004"},{"speaker":"須藤委員","kind":"質問・要望","question":"きちんと契約が切れたら、これをスタートにしてしっかりと終わったらもう次は再契約しないということでしっかり進めていってほしいと求めました。要望です。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-005"},{"speaker":"原副委員長","kind":"質問","question":"ですから、多分それは契約の期間の問題なのかどうか、その辺についてちょっと説明を求めました。","respondent":"大串住宅担当課長","answer":"ご説明させていただきましたが、こちらのパレスガルについては、平成４年１２月１日から借上げということで区と契約を結ばせていただいております。平成２４年１１月３０日が契約満了日でございまして…","id":"exchange-006"},{"speaker":"原副委員長","kind":"質問","question":"これでスタートですので、あと、今後いろいろ続くと思いますので、区の立場としては、かっきりはっきりやっていくと、これが誤解のないようにすっきりやって、ですからもう、非常にこのやり方としては私は大賛成ですので、今後もよろしくお願い申し上げますということで、意見です。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-007"}]},{"id":"topic-02","title":"第７６号議案、品川区手数料条例の一部を改正する条例","agenda":"第７６号議案、品川区手数料条例の一部を改正する条例","exchanges":[{"speaker":"浅野委員","kind":"質問","question":"そういう組織というんでしょうか、計画があって対応できるようになっているのかどうか、この点について説明を求めました。","respondent":"中村建築課長、野呂瀬環境課長","answer":"今現在、長期優良住宅ですとか、あるいは省エネ法に基づく届出などを行っている建築課の部署があります。そちらのほうの職員で対応するということで既に体制のほうは準備が整っております。 ５つの重点取り組みがあるんですけれども、低炭素社会の構築の実現に向けてさまざまな事業を取り組んでいく、こういうことはうたっておるところです。","id":"exchange-008"},{"speaker":"浅野委員","kind":"質問","question":"低炭素まちづくり計画というんでしょうか、これは今、答弁いただいた地域推進計画の中にそういう計画はもう既に含まれているというような考え方でよろしいのかどうかお伺いします。","respondent":"野呂瀬環境課長","answer":"はい、委員おっしゃったとおりでございまして、低炭素まちづくり計画、こういう決まった計画はございませんけれども、地域推進計画の中で低炭素社会の構築を目指していく、このようにうたっているものです。","id":"exchange-009"},{"speaker":"浅野委員","kind":"質問","question":"そういう方針も決まっていて、今回このような形で認定制度が来たということで、いい意味ではすんなりと対応ができるというふうに捉えします。積極的に低炭素化に取り組んでくださいよというようなアピールというんでしょうか、そういう広報は今後考えられているのかどうか説明を求めました。","respondent":"中村建築課長","answer":"この認定制度ですけれども、これは建物を設計する際には必ず建築課の窓口にご相談をいただくような形に今なっております。ただ、各関係団体に説明会はやっているようですけれども、さらに念のためにそういった広報を行っていきたいと考えております。","id":"exchange-010"},{"speaker":"浅野委員","kind":"質問・要望","question":"最後にしますけれども、せっかくあるルールですので、ぜひ区民の皆様にもしっかりと周知してほしいと求めました。これが適正かどうかということについては、例えば、この金額が妥当なレベルなのかどうかということについて調査した結果があれば説明を求めました。","respondent":"中村建築課長","answer":"まずは東京都のほうで今、作成をしておりまして、実はこういった手数料関係がやはり２３区あるいは東京都内で共通なのが好ましいと。それから、今まで国土交通省などの説明に基づいて想定した計算をすると、おおむね妥当であろうかというふうに考えております。","id":"exchange-011"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"これは設計の段階からこういうところで建てていきますよということで認定を取っていくという、そういうことになるんでしょうか。こういう家にもう既に住んでいるということで手続をしてこれが受けられるという、そういうことはないのか、そのことをお聞きします。","respondent":"中村建築課長","answer":"やはり認定の基準は満たさないということで、既存の建物につきましては、認定の基準を満たすものというのはほとんどないというふうに考えてあります。","id":"exchange-012"}]},{"id":"topic-03","title":"第７７号議案、品川区地区計画等の区域内における建築物の制限に関する条例の一部を改正する条例","agenda":"第７７号議案、品川区地区計画等の区域内における建築物の制限に関する条例の一部を改正する条例","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"単純な疑問なんですが、目黒駅前の開発は、これがなぜ同時期に出てきたのかというところを教えていただきたいのが１点です。ここがちょっと違っていたので、そのところが実際にどういうふうな状況なのか、地権者の中身も含めて教えてほしいと求めました。","respondent":"中村建築課長、溝口都市開発課長","answer":"確認申請の中で地区計画の意に沿わない設計で確認申請が出てきたときも、建築基準法に基づいて確認処分を行わなければいけないというのがあります。ですので、この建築確認申請に先立ちまして、条例のほうを制定するものです。 現在、組合が設立しておりまして、組合設立時の権利者の状況として７月にお答えしています。権利者につきましては、現在のところ２４人というのが正しい数字です。","id":"exchange-013"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"都市計画審議会が平成２２年に終わっていて、確認までこれだけの期間があるという、そこら辺の理由があったら教えてほしいと求めました。もう１つ、７月のところでは、東京都の権利というのがどういうふうになっていくのかというところもあわせて教えてほしいと求めました。","respondent":"中村建築課長、溝口都市開発課長","answer":"確認申請を含めました建築のスケジュールにつきましては、区のほうでは全く把握していないということではなくて、常時把握していますので、その辺につきましては、スケジュールどおりというふうにお伺いいたしております。 ５３％の敷地を、東京都交通局がどのような形で床を使っていくのかというのは、まだはっきり決まっていないというふうに聞いているところです。保育園ですとか、サービスコーナーですとか…","id":"exchange-014"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"何をどういう形で権利変換をしていくのかというのがちょっとよくわからないんですけれども、そういうふうなことはあるんでしょうか、どういうふうになっていくのかというのがちょっとわからないので……。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-015"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"ただ、地区計画というのは、その建物が建てられるための計画を決めるというふうなところなので、その建物がどういう建物になっていくのかということがわからないと、ちょっとあれだなと思っていますのでとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-016"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そういうふうなことが今まで例としてあったんでしょうか、そこら辺のところを教えてほしいと求めました。もう１つは、ここのところでは、そういうふうな中でどのような形状ですとか対策がとられたのかということについても教えてほしいと求めました。","respondent":"溝口都市開発課長","answer":"現在、詳細設計を進めていく中で、私どもとしてもしっかり対策をとらせるように指導していきたいというふうに考えております。そういったもので対応していき、外壁等のことになるとは思いますが、風環境が悪くならないような対策をしていくというふうに考えているところです。","id":"exchange-017"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"区長宛てにも要望書をずっと何度も出しているということでお聞きして、今年に入ってからも８月に要望書を出して、いかがか尋ねました。","respondent":"溝口都市開発課長","answer":"風対策につきましては、現在、詳細設計を進めていく中で十分検討しながら進めていきたいというふうに考えておりますので、それにつきましては、引き続き、周辺環境に風の悪影響を及ぼさないような対策を講じるように指導していきたいというふうに考えております。","id":"exchange-018"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"このマンションのほうに工場が入るということでお聞きしていますけれども、１５０平方メートルは超えないという、そういう工場になるのでしょうか。具体的なところで、何社、何平方メートルぐらいのところが入るのかというところを教えていただきたい。","respondent":"溝口都市開発課長","answer":"実際、具体的に先ほど質問にもありましたが、１１社１７棟の工場がある。組合設立手続を踏み、実際に具体的にどういう形で入るのかというのは、今後の計画になっていくというふうに聞いております。","id":"exchange-019"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"用途制限のところに工場以外の建築物というようなことになっているので、Ｂ地区のほうには工場も建てられるということになるということですよね。そのところがここに残るかどうかというふうな話し合いの中で、１階も含むのか、そういう考え方になるのか尋ねました。","respondent":"溝口都市開発課長","answer":"今後、権利変換をしていく中で、実際、Ｂ地区に主に建てられるところで工場がどういう形で再建されるのか。主に地下と１階等の低層部に持っていくという形で考えておりますが、それに対応した形での建築計画を今後立てていくという形になります。","id":"exchange-020"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"今の段階でどういうふうな状況になっているのかということをお聞かせいただきたいのと、３.９ヘクタールということでかなり広い場所になるわけですけれども、根拠は結構ですので教えてほしいと求めました。","respondent":"溝口都市開発課長","answer":"上に住まわれる方にも十分配慮した形での建築計画にしていきたいというふうに組合のほうも考えているように聞いておるところです。現在まだ準備組合段階で組合設立がされておりませんので、まだ事業費ですとか国費がどのぐらい入るのかというのは未定です。","id":"exchange-021"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"なぜここでは出ていないのか、補助金、わからないという状況か尋ねました。","respondent":"溝口都市開発課長","answer":"事業費の考え方です。西品川一丁目地区につきましては、まだ準備組合の段階ですので、事業費等というのははっきりわからないというのが今の現状です。","id":"exchange-022"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"この計画を決定していく都市計画審議会のところでも、当然私たちの税金が投入されていくわけですから、私はあり得ないんじゃないかなと思うんです。概算でやむを得ないというふうに思うんですけれども、私は概算でもしっかりと出していただきたいというふうに思います。","respondent":"溝口都市開発課長","answer":"今後、まちづくりがどうなるのか、そういったところをご審議していただくところだというふうに考えております。そういった制限等の中でどういったものが建てられるのか、そういったものを十分検討しながら初めて事業費が算出されるものと考えておりますので。","id":"exchange-023"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"私は本来であれば、都民のために有効活用をぜひともしていただきたいというところが、こういう形でのマンションになってしまうという。地域の方からは、全く風環境が改善されていないということで何回にもわたる要望書、賛成はできません。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-024"}]},{"id":"topic-04","title":"第７８号議案、品川区対象区域における特定工場の緑地面積率等に関する条例","agenda":"第７８号議案、品川区対象区域における特定工場の緑地面積率等に関する条例","exchanges":[{"speaker":"浅野委員","kind":"質問","question":"都から区に移管されるということで、そのまま継続という説明をいただきました。その点をお伺いしたいのと、そういうような意思というのでしょうか、そういうものはあったのかどうかということについてお尋ねしたいと思います。","respondent":"野呂瀬環境課長","answer":"ですから、都の条例で基準が決まった以降、この条件を満たす工場は昭和４９年以降出ていないです。あえて東京都の考えを一歩進めてということですけれども、もう１つは、そういう考えから都の規定をそのまま準用したです。","id":"exchange-025"},{"speaker":"浅野委員","kind":"質問","question":"相手があることですから簡単にというわけにはいかないと思うんですけれども、そういうものはあるのかどうか、この点について説明を求めました。","respondent":"野呂瀬環境課長","answer":"東京都は東京都でそういう条件の中で自前の準則を決めたという経緯がございまして、品川区としてもそれに沿って東京都の基準をそのまま移行するのが適当ではないか、こういうふうに考えたところです。","id":"exchange-026"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"この工場立地法で、ここのところに緑地をどれぐらい設けなければいけないかというふうなところで定められる工場というのは、どれぐらいの広さが対象になるのか、そして品川区でこの条例の対象になっている工場は幾つぐらいあって、どういうところなのかというところを教えてほしいと求めました。","respondent":"野呂瀬環境課長","answer":"２点目、どれぐらいあるのかというと、昭和４９年以降はこれぐらい大きなところはありません。それと日本ペイント株式会社の５工場と、先ほど申しました東京電力の２火力発電所、これで７工場です。","id":"exchange-027"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"昭和４９年以降、そんなに可能性としてはないということで考えられているのか、そこら辺のところの考え方を説明を求めました。","respondent":"野呂瀬環境課長","answer":"都が２０％以上ということで、先ほどもお答えしましたとおり、引き上げるような考えはございません。それと、今後こういうような工場が設置されるのかというお尋ねですけれども、多分可能性としてはないだろうというふうな考えでおります。","id":"exchange-028"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"品川区独自にその基準を変えていけるということであれば、そういうことも検討はしていただきたいなというふうには思います。要望で結構です。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-029"}]},{"id":"topic-05","title":"第７９号議案、品川区廃棄物の処理および再利用に関する条例の一部を改正する条例","agenda":"第７９号議案、品川区廃棄物の処理および再利用に関する条例の一部を改正する条例","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"提案","question":"５年目の値上げという提案ですけれども、この４年ごとというのは、３年目に見直しを検討するという説明がされていなかったんです。３点目、今回の値上げをすることによって、区が増収になる額というのは幾らぐらいになるかについてもお聞かせほしいと求めました。","respondent":"太田品川区清掃事務所長","answer":"４年という考え方ですけれども、先ほどご説明しましたように、こういうことです。３年目に改定するという説明が前回なかったというお話ですが、これはもともと改定後３年目に見直しを検討し、そういう方針が出ておるところです。","id":"exchange-030"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"多くの方が区のごみ収集を利用しているということで伺ったんですけれども、そういうところでの声とかなどもお聞きになられていたら、そこら辺のところをお聞かせほしいと求めました。","respondent":"太田品川区清掃事務所長","answer":"さらにごみの減量、資源化、これに取り組んでいただくことも１つのこういう手数料の改定については大きな目的であるというふうに考えてあります。これから区のほうも十分周知をしていく予定ですけれども、あわせてごみの減量…","id":"exchange-031"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"３年目に見直しをして検討するということなんですけれども、見直しというのは、値上げをしないで据え置くというふうなこともあり得るわけですよね。それともう１つは、ここら辺のこの３パターンの割合、ごみの量の割合がどれぐらいになっているのかというのがわかったら教えていただきたい。","respondent":"太田品川区清掃事務所長","answer":"全額改定をお願いするということではなくて、その半額程度の４円について改定をお願いすると、こういうことでお願いをするものです。それから、６ページの事業系ごみの配分については、申しわけございませんけれども、私どものほうでは正確な数字としての把握はできておりません。","id":"exchange-032"},{"speaker":"吉田委員","kind":"質問","question":"１つお伺いしたいんですけれども、現在持っているものは１０月中に使えというお話しなんですけれども、その辺のうまく流れをつくっていくことに関してのお考えを聞きたいんです。","respondent":"太田品川区清掃事務所長","answer":"それから２点目の区民周知につきましては、まず２３区全体で周知、広報等を使いながら十分な周知をしていく考えでおります。１１月以降についてですけれども、差額を納付していただくことによって新券に換えていく、こういうことも考えているところです。","id":"exchange-033"},{"speaker":"吉田委員","kind":"質問・要望","question":"よくわかりました。ちょっと突っ込ませていただきたいんですけれども、その辺のお考えも、いかがか尋ねました。","respondent":"太田品川区清掃事務所長","answer":"周りの方のお話を聞きながら、できることと言えば、看板を設置するなりということで対応させていただいています。区民の皆さんに訴えをしていって、個々のモラルに訴える形にして、少しでもなくすように努力はしていきたいというふうに考えております。","id":"exchange-034"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"その部分を税金で払うことになると言いますけれども、私は個人商店とかは、やっぱりそういうことで支援が必要なんじゃないかと思います。そういうところで、小さなところに大きな負担になっていくごみの値上げに対しては反対ということで態度表明をいたしますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-035"}]},{"id":"topic-06","title":"第８５号議案、専決処分の承認を求めること","agenda":"第８５号議案、専決処分の承認を求めること","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"本人に損害金の支払を求めるというのは、この方の状況をちょっと教えていただきたいんですが、その理由についてもお聞かせほしいと求めました。東急コミュニティーがどういう対応をしてきたのか、何回ぐらいの面接をしてきたのか、その点についてまずお聞かせほしいと求めました。","respondent":"大串住宅担当課長","answer":"こちらの方が居住になっているのは、先ほどご説明させていただきましたが、平成１６年５月から居住しております。あわせて東急コミュニティーの対応ですが、その月によっていろいろ変更はありますけれども、こういったことで督促を行ってきたです。","id":"exchange-036"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"東急コミュニティーが四、五回訪問したり、電話で督促をするということなんですけれども、こういう場合は、区としてはどういうふうにこの方に対してかかわっていくのか、そこら辺のところを説明を求めました。","respondent":"大串住宅担当課長","answer":"こちらにつきましては、東急コミュニティーが指定管理者として対応しておるところです。一義的にはこの方の滞納関係については、すべて東急コミュニティーのほうで対応を行っている。","id":"exchange-037"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"平成１６年５月から住み始めて、平成２３年１月までは、それまでは７年間ぐらいにわたっては普通に支払ができてきていたわけなんですよね。区のほうは最終的にこの方に対して裁判にどう訴えていくかというふうな話し合いのところまで応じない、そこら辺のところはいかがか尋ねました。","respondent":"大串住宅担当課長","answer":"ですので、基本的には東急コミュニティーのほうでこういった滞納者については対応していただく、これが第一義です。こちらのほうとしても対応はしますが、残念ながらこちらの方から区のほうに直接ご相談といったことは、この方に関してはございませんでした。","id":"exchange-038"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"もっと早い段階でこの人の生活も何とかできていけるというようなところでの、ぜひそこら辺のところは今後に向けてご検討いただけたらと思います。要望です。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-039"},{"speaker":"須藤委員","kind":"質問","question":"それに対してどうするんだというような形をしておかないと、約１年ちょっとの間に、そういう決めは区としてはどうなんだろう。こんな事例があるんだ、じゃあ、それは次のステップに移ろうとかという仕組みがどういうふうになっているのか説明を求めました。","respondent":"大串住宅担当課長","answer":"２カ月目以降、指定管理者の電話や訪問による直接的な納付催告、この段階から必要に応じて保証人も含めた対応をお願いしているという流れです。それを徴収するということになると、訴訟に訴えなければできないといったところが背景にあるということもご理解いただければと思いま…","id":"exchange-040"},{"speaker":"須藤委員","kind":"意見","question":"早めならば、このくらいならお支払いをして次の場所へ移るとかという動きができるのだろうと思うので、少し今の手順をスピードアップしていただけたらと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-041"},{"speaker":"原副委員長","kind":"質問","question":"だけれども、最終的に何年かたったときにとれませんでした、なかなかこういうケースはとれない。ですから、担当課長として、一言だけで結構なので。","respondent":"大串住宅担当課長","answer":"ただ、なかなかその辺は難しい問題も含んでいるのかなというふうに考えているところです。ご指摘いただいたことにつきましては、今後検討していきたいというふうに考えております。","id":"exchange-042"},{"speaker":"原副委員長","kind":"質問・要望","question":"やっぱり指定管理というのはプラスアルファもつけるわけですから、ですから、毅然とやってほしいと求めました。これは要望です。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-043"}]},{"id":"topic-07","title":"第８６号議案、指定管理者の指定","agenda":"第８６号議案、指定管理者の指定","exchanges":[{"speaker":"須藤委員","kind":"質問","question":"払えなくなってしまうよという人が出てこないとも限らないから、そういうときにはできるだけ区民の税金に迷惑がかからないような仕組みがきちんととれるような状況をとっておいてもらいたいと思うんだけれども、そのあたりはどういうお話をしたのか説明を求めました。","respondent":"大串住宅担当課長","answer":"滞納の関係ですが、入居者管理の中の一番大きなポイントになろうかと思います。その次善策として、１カ月目の少ない段階から、その入居者の方に対しては対応していくということでお約束をいただいているところです。","id":"exchange-044"},{"speaker":"木村委員","kind":"質問","question":"今回この指定管理者の申請者は１社ということなんですけれども、どうして１社しか来ないのか、前回などはどのような状況であったのか説明を求めました。","respondent":"大串住宅担当課長","answer":"こちら、先ほどご説明しましたが、７月２３日から公募を行いました。多分うちのほうで説明等々、会社として総合的な判断をしていただいて、応募というところには至らなかったというふうに考えているところです。","id":"exchange-045"},{"speaker":"木村委員","kind":"質問","question":"この指定管理者がちゃんとできているかどうかということ、チェックをちゃんとしているのかどうか、それがもしあれば説明を求めました。","respondent":"大串住宅担当課長","answer":"毎年毎年こちらの指定管理者につきましては、私どものほうでもヒアリングといった形で評価実績を確認しています。指定管理者のほうもそういった形で区の期待にこたえていただけるよう努力をしていただいているというふうに我々としては考えているところです。","id":"exchange-046"},{"speaker":"木村委員","kind":"意見","question":"自分のところはこういうふうにやりたい、私のところはこういうふうに管理するんだというふうな前向きなものが出てくるのではないかと思っています。将来的にそういう考えがあるかどうか、１社ではなく、競争させるような方法について何かお考えがあれば説明を求めました。","respondent":"大串住宅担当課長","answer":"こちらが出ていただくことを我々としても期待しておりまして、そういったことを踏まえまして、今年７月には公募を行ったところです。今後とも競争させて競争原理を働かせて…","id":"exchange-047"},{"speaker":"浅野委員","kind":"提案","question":"そういう前向きの提案というのがあったのかどうかということと、平成２３年が１１３.２９日と下２けたまで出ているんですけれども、回答があったのかということについてお伺いしたいと思いますとの意見を述べました。","respondent":"大串住宅担当課長","answer":"東急コミュニティーのアピールポイントですが、先ほど、冒頭説明の中でもありましたように、コミュニティー形成支援、こちらを重点目標とするです。これはちょっと実施できるかどうかは何ともというところなんですが…","id":"exchange-048"},{"speaker":"浅野委員","kind":"意見","question":"そういうふうにも言われておりますので、さらに指定管理者のほうと打ち合わせをしながら、いい方法を見つけていってほしいと求めました。先ほどの中で、金額としてはどのぐらいのレベルになったのかなというところでちょっとの意見を述べました。","respondent":"大串住宅担当課長","answer":"最終年と今現在を比較して、約２,０００万円ほど経費は下がっている。西館それぞれ、消防法の関係で２４時間防災センターを設置しなければならないんですが、このように捉えているところです。","id":"exchange-049"},{"speaker":"沢田委員","kind":"質問","question":"４年後に半分側の指定管理の終わるときが来ると思うんですけれども、５年間ということでやっていますけれども、そういうことの変更という可能性もあるんか尋ねました。","respondent":"大串住宅担当課長","answer":"どうしても１年間のずれが出てまいりますので、そうしますと、最終的には西館と東館の指定期間がちょうど合わさるという形になろうかと思います。次回の指定管理の公募のときに、またよりよいサービス…","id":"exchange-050"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"公募の周知とか、やり方というのは全く同じであるにもかかわらず、東急１社しか公募がなかったということなんでしょうか。その点、やり方の面で教えてほしいと求めました。","respondent":"大串住宅担当課長","answer":"５年前と全く同様の形で公募活動はやらせていただきました。","id":"exchange-051"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"なぜそういうふうな公募というふうな形でとったにもかかわらず来ないのかというのは、区としてはどう、考えられていることというのはないのか尋ねました。","respondent":"大串住宅担当課長","answer":"ただし、その条件を緩和するということは、入居者へのサービスの低下につながりますので、そういったことは考えてございません。次回公募の期間で何社来るかというのは非常に難しいところですが、基本的に今のやり方を変えるというふうには考えておりません。","id":"exchange-052"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"退去してから約４カ月ぐらい入らないという、そしてなぜこんなに４カ月も入らないという状況なのか、そこの点についてお聞かせいただきたい。","respondent":"大串住宅担当課長","answer":"これは早ければ早いに越したことはないんですけれども、残念ながら退去の際は、原状回復工事等々が必要になってまいります。そういったところで平均日数としてはこういった日数が出てまいりますけれども、こちらほうからは指導してまいりたいと考えています。","id":"exchange-053"},{"speaker":"原副委員長","kind":"質問・要望","question":"指定管理者ですから、ですから、これはなかなか区が訴えたとしても勝てる見込みは薄いですから。民間の場合には社員弁護士とかいたりするわけですから、ご苦労だと、これはすごいことだなと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-054"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"反対です。やっぱりそういうふうなときに、区が親身になって、区直営でやるべきだというふうに思いますので反対ですとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-055"}]},{"id":"topic-08","title":"第８７号議案、東京二十三区清掃協議会規約の変更","agenda":"第８７号議案、東京二十三区清掃協議会規約の変更","exchanges":[{"speaker":"須藤委員","kind":"質問","question":"当分の間というか、そのことが平成１８年に少し解散するというのが延ばされて、当分の間というような表現になってきた。これはちょっと一般質問で言ったように、平成１２年のときは頑張ってみんなで自治権拡充というものをやってきて、いかがか尋ねました。","respondent":"太田品川区清掃事務所長","answer":"平成１８年度の規約改正の中で、中間処理が安定的に処理できるまでは設置するという、こういう決着になった。区民の意向、各区が直接事務処理をしていくことが必要ではないかという認識で主張してきたんですけれども、最終的にはこういう結論になったです。","id":"exchange-056"},{"speaker":"須藤委員","kind":"意見","question":"実務的に区として何か問題があるという業者も勝手に区内に入ってきてしまうよということは、どういうふうに見ればいいのかなと。清掃協議会へ１回行けばすぐとれちゃうよという話になってしまうのかなと思うんだけれども、そうすると、そういうあたりはどうなんだろうとの意見を述べました。","respondent":"太田品川区清掃事務所長","answer":"事細かくこの許可事務に当たっては変更をすることになっている、そういった変更申請等で９９％、そういう形になってあります。平成２５年４月以降もこういう形でご議決いただいて管理執行になったとしても、今言った担当者の中で今後検証していくという形になっているです。","id":"exchange-057"},{"speaker":"須藤委員","kind":"意見","question":"責任がどうのなんていくと、２３区が一緒になってしまうと、そのあたりはどういうふうに考えていらっしゃるかとの意見を述べました。","respondent":"太田品川区清掃事務所長","answer":"今のお話は、いわゆる先ほど廃棄物処理手数料改定の中でご説明した清掃工場へ持ち込むごみ、これは許可業者がやります。今、８名の増の見込みということになってありますが、審査事務がおろそかになるということはないと思います。","id":"exchange-058"},{"speaker":"浅野委員","kind":"質問","question":"１月とか２月に中間まとめがあって、それが６月に行われた臨時部長会で承認されたということに変わったというんでしょうか、そのように思います。この点についてお願いします。","respondent":"太田品川区清掃事務所長","answer":"３月までで言われていなかった実施時期が急遽、部長たちがかわって、持ち越したというふうに捉えていただければよろしいかと思います。約１時間半ぐらい同様の議論をしたんですけれども、やはり最終的には多くの区が効率化の考え方に沿って進めていくという流れになったです。","id":"exchange-059"},{"speaker":"浅野委員","kind":"質問","question":"その反面、そういうような状況ですから、業者を守るという観点になってしまっているなというふうにどうしても見えるなと思うんです。２３区そろって議会のほうで了解されないということになった場合、そういうものはあるのかどうか、この点について伺いたいと思います。","respondent":"太田品川区清掃事務所長","answer":"今のご質問は、１区だけが議決を得られなかったという……。","id":"exchange-060"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"立入検査ですか、この立入検査ですか、そういうのはどこにどういうふうな形でそれができるということは担保されているのかということをお聞かせほしいと求めました。","respondent":"太田品川区清掃事務所長","answer":"横並びの処分内容というのは、これはもうできませんから、各区で起きた法令違反ならば、各区が主体的に考えて処分をしていくということになる。許可を持っている区から業者に対する何らかの処分は出てくるということですが、その色合いは当然違ってくるという中身で…","id":"exchange-061"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そういう担当者会もあるし、つかむことはできるし、つかむということも引き続いてしていくということで確認させていただいていいですよね。品川区の職員としてはどうなってしまうのか、どういう体制になるのかという、どれくらいの人数になるのかということを教えていただきたい。","respondent":"太田品川区清掃事務所長","answer":"精力的に検討をしていますけれども、今後、検討していくことになろうかと思います。この数字も今のところの見込みの数字ですので、平成２５年４月以降で各区でどうするかというのは、まだ正直言ってわからないところです。","id":"exchange-062"},{"speaker":"沢田委員","kind":"質問・要望","question":"自治権の拡充ということでもずっと区が求めてきて、そこでまとめて２３区でやるということだったかと思うんですけれども、自治権を品川区に戻していくという方向で引き続き主張され続けるのか。","respondent":"太田品川区清掃事務所長","answer":"さらに具体的に検討に入っていき、その時点で清掃協議会は廃止する、これは変わらないかと。許可事務を今度はどうするかというのは、その時点で許可事務を今度どこの組織が担うかは別途検討する、こういう仕切りになっているものです。","id":"exchange-063"},{"speaker":"沢田委員","kind":"質問","question":"２３区が共通で持っていなくてはいけなかったものが、変わってきてしまうということで、所長が改めて各区にもそういった働きかけを今後も引き続きやっていかれるということでよろしいか尋ねました。","respondent":"太田品川区清掃事務所長","answer":"やはり基礎的自治体として特別区が直接執行していく必要があるということについては、継続的に訴えていきたいというふうに思います。今回いろいろ区の考え方を申し上げましたけれども、総意としての決定になっているですので、どうぞよろしくお願いいたします。","id":"exchange-064"},{"speaker":"須藤委員","kind":"質問・要望","question":"そのあたりを、明日でもまた皆さんにお願いしたいんですけれども、皆さんで賛成してもらいたいなという思いでお話をさせていただきました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-065"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"その附帯決議は、ぜひ文章で出していただいて、やっぱり会派でこの条例についての態度を話し合って決めていますので、会派で検討するという時間をぜひとらせてほしいと求めましたので、よろしくお願いしたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-066"},{"speaker":"須藤委員","kind":"意見","question":"明日か今日の遅くになってしまうと思うので、それでよろしければ、明朝に皆さんに見ていただいてという形になろうかとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-067"},{"speaker":"須藤委員","kind":"提案","question":"今お話ししたように、附帯決議を建設委員会の皆さんで、定例会最終日に提案をお願いしたいと。案文については、明日、正副のほうへ出しますのでとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-068"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"私、その文章も含めて、文章を検討させていただいて、附帯決議をつけるかどうかというふうなところも検討させてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-069"},{"speaker":"須藤委員","kind":"意見","question":"それ以外の変なものは、変なものというのもおかしいけれども、どのあたりが入ってしまうとうまくないとかというのはありますか。そうしたら、やはりみんなで一致できるような文章にしておきたいなと思うので、どういうことが入ってしまうとまずいだろうということはありますかとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-070"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"どういうことが入ってしまうとまずいというところは特にないんですけれども、そして区としても責任を持てるような、そういう体制というのをぜひ担保できるようなものにはしたいというふうな思いはありますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-071"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"その附帯決議を付すかどうかというのも、そういうふうなことというのは、今日までは問われていなかったじゃないですか。持ち帰らせていただきたいということなので、そのことそのものを明日決定していただくということで仕切りは可能だと思うんですけれども。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-072"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"附帯決議を付すかどうかということも含めて、その文章を見て決定をさせていただきたいと思うんです。附帯決議を付しますかどうしますかと言われても、それで結構です、附帯決議を付すということに賛成ですという態度を決められないということなんです。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-073"},{"speaker":"須藤委員","kind":"質問","question":"やはり平成１２年、それから平成１８年というものは、平成１８年のときもたしかそんなような形で決議してきたと思うので。ですから、そうしないと僕らもつけますということでこれから会派で文章を整理します。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-074"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"じゃあ、私が今日、保留というふうな形にして、明日その文章はやっぱり会派で賛成していこうということになったら、賛成というふうにできるんか尋ねました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-075"},{"speaker":"須藤委員","kind":"提案","question":"だから、全部名前を書けばいいんだから。賛成なら、提案者なんだからとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-076"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"だから、それをとる意味というのがあるんですか。この条例に対してしかしていないので。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-077"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"だから、今からそれそのものを決をとられるというふうに言われても、私一人では判断できないので、持ち帰らせていただきたい。そして、そのことも含めて、明日、決をとっていただければ、全然今日の段階できちっと……。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-078"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"私は、事前に地域の方の意見をぜひとも聞いて、そこでさまざまな不安や疑問、心配の思いもあると思いますので、その声にこたえるような審議をぜひともしていきたいと思いますので、ぜひ審議の前に意見陳述をしてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-079"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"ぜひ事前にやっていきたいという私の思いですので、意見ですので、そういうふうな思いを皆さんに諮ってほしいと求めましたけれども。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-080"},{"speaker":"浅野委員","kind":"質問","question":"２９号線と３１号線、今の段階で区民の皆さんに具体的な事業の計画が一切説明されていないという状況というふうに区の方からも伺っております。なぜここまで区のほうの説明が遅れてしまったのか、どういう理由なのかということと、ある意味では私も懸念せざるを得ないかなとも思っております。","respondent":"藤田都市計画課長","answer":"東京都が説明していくものを地元の区としてサポート、支援するような形での説明を行う、これが基本かなというふうに考えてあります。本来は東京都としてはそれがはっきりしないと説明会の予定も組めないんだと思うんですけれども、何地区で、いつぐらいに説明会をやるべきだとい…","id":"exchange-081"},{"speaker":"浅野委員","kind":"質問・要望","question":"やはり今現在の区民の皆さんのご意見を伺う意味でも、これについてのお考えはどうなのかということが１つご答弁いただきたいのと、３１号線。これはできるのであろうと私は考えるけれども、これはどのようにお考えなのかということを２点目、品川区の考えを教えてほしいと求めました。","respondent":"藤田都市計画課長","answer":"整備を進めていく、あるいは検討を進める、いつまでに具体的にどうするかというものを現段階で立てているものではございません。そういったわけで、地元に対して、昭和２１年に決まってから具体的な説明というのが、今のところ行われたこともありません。","id":"exchange-082"},{"speaker":"浅野委員","kind":"質問・要望","question":"３１号線については、本来ですとこういう状況だよというふうに話していただきたいというのは、要求したいところなんです。都市計画道路３１号線、こちらについて区民の皆様にきっちりと説明をしてほしいという、こういう要望書を提出させていただきました。","respondent":"藤田都市計画課長","answer":"私どもも１日も早くやはりまちに出て説明ができるような形にはしていきたいというふうに思ってあります。そういう機会を１日でも早くつくることが実際の早い説明会の開催につながると思っています。","id":"exchange-083"},{"speaker":"浅野委員","kind":"質問・要望","question":"今回の件につきましては、やはりこれだけの反響があるし、私どもも当然聞いていますし、他の議員も多分同じだと思います。やはり漏れのないような、そういうような告知方法をぜひとも区のほうで精いっぱい考えて取り組んでいただきたい、このように要望しておきます。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-084"},{"speaker":"須藤委員","kind":"質問","question":"これをどうのという、また３・１１で区民の関心が非常に強いので、安心のまちづくりをしてほしいという総論的なものはある。ただ、もう少し全体の防災というものを東京都がどういうふうに考えているのか、そのあたりを知らせてもらいたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-085"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"木密１０年プロジェクトとして都がどういうふうに進めていきたいのかという、その上で、そういう形で説明会に入るべきだと思うんです。３１号線なんですが、それは終わったのかどうなのか、事業計画というのはどのようにされているのかお聞かせほしいと求めました。","respondent":"藤田都市計画課長","answer":"それから、その２つの策を合わせることで、その辺の事業の中身をしっかり説明していくのかなというふうに私どものほうでは考えているところです。もちろんその具体的な検討がなされるわけですけれども、今…","id":"exchange-086"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"３１号線は、それに続けて３１号線も整備をしていきたいという、その区の姿勢は変わらないということで確認をさせてほしいと求めました。その考え方を１つ確認をしたいと思いますけれども、いかがか尋ねました。","respondent":"藤田都市計画課長","answer":"延焼遮断帯の考え方ですけれども、東京都が示している１つは、木密地域不燃化１０年プロジェクトの実施方針の中にも記載があります。約１キロのメッシュが一般延焼遮断帯の記載になっている、全体的な把握をする中でその辺を考えているところなのかなというふうに考えてあります。","id":"exchange-087"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"何カ所でも火が起こったわけですけれども、神戸市内で全部合わせても９０数ヘクタールしかないというわけなんです。１キロメッシュで延焼遮断帯で道路をつくったとしても、そういう点の効果というふうなところについては、区としてはどう考えられているのか尋ねました。","respondent":"藤田都市計画課長","answer":"これまでも何度もご説明差し上げていますが、今回の木密１０年プロジェクトは、延焼遮断帯をつくるためだけの事業ではございません。特定整備路線、そのことだけでこの事業を進めていこうという考えでは、東京都もないし、私どももないです。","id":"exchange-088"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"私は、東京都が出した今回の被害想定の中で、品川区の出火件数というのは４０件なんです。そういう中で、それこそこの間のまちづくりマスタープランの講演会のときにも質問者から出されて、そこら辺の考え方についてはいかがか尋ねました。","respondent":"藤田都市計画課長","answer":"延焼遮断帯、あわせて不燃化の事業についても進めていく、そのことでまちを燃えないまちにしていこうというふうに考えております。燃えないまちとしての不燃化を進めるための事業、街頭消火器の配備、この辺の増設等についても区のほうとしてあわせて進めているところです。","id":"exchange-089"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"それで、出火件数４０件のところが２万１,６００棟まで燃え広がるという、そういう想定なわけです。そして区民の命と財産を守るために、一体何が一番最優先でやらなければならない課題なのか、そこら辺のところについてはいかがか尋ねました。","respondent":"藤田都市計画課長、片田都市環境事業部長","answer":"繰り返しになりますが、もう１つの枠組みである不燃化特区、これについては先行実施地区で品川区内にも既に１カ所選ばれております。来年度からは、これに加えて、本格実施地区、これの選定にも入っていくわけです。 私のほうからも一言説明させていただきたいと思いますけれども、ご案内のとおり、昭和２１年から道路の計画は実はあったんですね。それをきちっと丁寧な説明と、東京都と連携して進めさせていただきたいと…","id":"exchange-090"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"根拠というのはこれしかないのでしょうか。私はこれで根拠と言えないのではないかなというふうに思うんですけれども、そのところはいかがか尋ねました。","respondent":"片田都市環境事業部長","answer":"被害想定としてどういう対策を講ずるかといったような対応を検討して計画の中に盛り込んできたといったような経過があります。今現時点で、その中で東京都が進めるということを区としてもきちっと支援して連携をとって進めていきたいというような考え方です。","id":"exchange-091"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"この間、去年の３・１１のときの都内の「超」渋滞現象（グリッドロック）ということで質問したときに、検討・分析が本当に必要なんだと思うんです。ぜひ検討・分析していただきたいと思うんですけれども、ぜひそうしていただきたいと思うんですけれども、いかがか尋ねました。","respondent":"藤田都市計画課長","answer":"このまちをいかに安全・安心なまちにしていかなければいけないのかというのは、１つの大きな課題であるというふうに区のほうでは考えてあります。そうではなく、これは東京都なり国土交通省が…","id":"exchange-092"},{"speaker":"須藤委員","kind":"質問・要望","question":"ですから、僕自身はここで継続をしていただきたいと思っていますので、よろしくどうぞ。さっきから理事者の答弁が、前から聞いていて同じものなので、新しい答えが出てくるなら参考にしようと思うんだけれども、同じ答弁ばかりなので。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-093"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"これだけたくさんの署名も添えられて３つの地域から請願が出されているわけですから、それから要望、この委員会でやりとりがあります。だけど、そこの中で改めて審査をしていくというのは当たり前のことだと思いますので、ぜひとも私はまだ引き続いて聞かせてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-094"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"私が総括質問したときに、この交通量予測というのは、この２９号線についてもされるのでしょうか。補助２９号線、３１号線というのは、アセスメントの対象になるのか尋ねました。","respondent":"藤田都市計画課長","answer":"もちろん整備を検討する中で、どれぐらいの交通量があるから何車線必要なんだと、そういうような形の整理をしていくことになります。それだけで１２メートルなので、３１号線については、今の段階ではそのような道路には当たらないのかなというふうに考えてあります。","id":"exchange-095"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"こういうふうなことだからということで、整備決定の前にぜひやっていただいて、地域の方にも説明をしていただきたいというふうに思います。初期消火で５００人、これで８％、ここにこそ私は最優先で進めるべきだと思うんです。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-096"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"道路の前に。区民の命と財産を守る最も防災対策の要になると思うんですけれども、そこの考え方はいかがかというふうなことをお聞かせほしいと求めました。","respondent":"藤田都市計画課長","answer":"交通量をにらむ中で車線構成を決めていくというふうに考えますので、東京都を見守っていかなければいけないのかなというふうに考えてあります。その中で今回も木密地域不燃化１０年プロジェクトというぐらい、こういうような形で進めるものかなというふうに考えてあります。","id":"exchange-097"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"最後に、私は、そうするところで命と財産を守る対策というところに最優先で取り組んでいただきたいということを強く要望しておきます。これでもなんでそのきずなが断ち切られないで、町会が３つに分かれてしまって、そこのところを改めてお聞かせほしいと求めました。","respondent":"藤田都市計画課長","answer":"３１号線については、繰り返しになりますけれども、整備の検討をしていくとしているもの。不燃化は進める、それは進めなければいけないというふうに区のほうでも考えてありますが、不燃化を進めるんだというお話をしているところです。","id":"exchange-098"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そういうところを心配しているからこそ、この道路づくりはやめてほしいと言っているんだと思います。３１号線は、しばらく白紙に戻しますとぜひとも言っていただきたいと思うんですけれども、いかがか尋ねました。","respondent":"藤田都市計画課長","answer":"すみません、ちょっとはずみで１００年後とか言いましたけれども、あくまでも長期基本計画であり、マスタープランの中で整備の検討をするというような形でしている道路ですので、これについては整備の時期についてはしっかり見守りながら進めていく路線です。","id":"exchange-099"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"私は、ぜひとも意見陳述を受けていきたいと思います。これを指定をして計画を進めていくという考え方ははっきりと出されているわけですから、そしてそれを参考にして結論を出していくべきだと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-100"},{"speaker":"浅野委員","kind":"意見","question":"このような状況で結論を出すということは、これは私ども、ある意味では無責任になってしまうのではないかなと、そういう危惧を持っております。そういう意味では、この件につきましては、継続ということにしたいと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-101"},{"speaker":"木村委員","kind":"意見","question":"私たちは、道路も大事だと思っていますし、また、区民の皆さんの命や財産、そういうものも大変大事だと思っています。そういう意味で、軽々に結論を出すよりも、継続審議としたいと思っていますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-102"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"私は、結論を出すべきだと思います。議会としてこういう意思を東京都にも伝えていく、こういう行動に移っていくためにも、ぜひ結論を今日出してほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-103"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/142731?Template=document&Id=4058#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2012-01-01&TermEnd=2012-12-31"}],"sourceMeta":{"pages":0,"characters":88894,"voices":318}},{"id":"h24-20121126-9","meetingId":"h24-cm11","date":"2012年11月26日","dateIso":"2012-11-26","committee":"文教委員会","time":"午前１０時００分～午後１時２２分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を46件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"阿部委員","kind":"質問・要望","question":"教えていただきたいんですが、この短時間就労型保育室の設置というのは、条例とはかかわらない事業内容ということですよね。これは根拠というのは、なしなんでしょうか、おさらいの話、これは。","respondent":"伊崎待機児童対策担当課長","answer":"事業の要綱で運営をしておりまして、こちらは長期基本計画、実施計画で５カ所まで設置するということを定めしています。こちらが５カ所目ということで、それで一応目標は達するということになります。","id":"exchange-001"},{"speaker":"南委員","kind":"質問・要望","question":"１歳、そういうあたりの音の問題というのはどういうふうに解消できているのか、ちょっとその辺について伺いたいと思います。子ども未来事業部としては、この辺の検討を設計図の段階でどういうふうに了解して、その辺についてもしっかりと伺っておきたいと思います。","respondent":"伊崎待機児童対策担当課長","answer":"豊葉の杜学園の中に併設をするということが決まりましてから、時間をかけて教育委員会、あと施設整備課のほうと保育課で検討を重ねてまいりました。保育課の意見を反映していただきながら、全体のつくりを考えて、こういう形で開設したいと思います。","id":"exchange-002"},{"speaker":"南委員","kind":"質問","question":"例えば、日照が確保できているというふうにおっしゃるけども、１日の生活時間として何時間確保できているんですか。どうなんだとか、そういうことも検証したうえでのことなんだろうと私は思うんですけども、その辺はどうなんか尋ねました。","respondent":"伊崎待機児童対策担当課長","answer":"四季によりまして変わってまいりますので、今手元に資料はございませんが、施設整備課のほうできちっとそれは調べてやっていることと考えております。今何デシベルまでという数字は持っておりませんが、通常の保育園が…","id":"exchange-003"},{"speaker":"南委員","kind":"質問・要望","question":"それぞれの部署に任せているという、ここが一番の責任の部分ではないんですか。そういうことで条例をつくって、それを信じていただきたいと、そういうことはちょっと改善をしっかり求めていきたいというふうに思います。","respondent":"金子子ども未来事業部長","answer":"品川区、この都会の中でさまざまな事業を展開しておりまして、なかなか日照を万全に確保するというのは非常に難しいところがあります。今までも荏原第三中学校には日常的な連携、それからイベント等については生徒にさまざまなボランティアとしてご支援をいただておりまして。","id":"exchange-004"},{"speaker":"南委員","kind":"質問","question":"同じなんですか、その辺の見解はどうなんでしょうか。伺いたいと思います。","respondent":"伊崎待機児童対策担当課長","answer":"保育課、施設整備課と協議を重ねまして、子どもの生活に支障がないように設計をしていただいております。そのあたりは、より一層子どもたちの生活の環境を整えていけるように検討すると、こういうふうに考えています。","id":"exchange-005"},{"speaker":"南委員","kind":"質問・要望","question":"質問していますので、できるだけまとめていきたいとは思いますが、お伺いします。静かな環境が求められる、不十分という、やはりそれは問題だというふうに言わなければいけないというふうに思うんですね。","respondent":"金子子ども未来事業部長","answer":"そして地域センターというものと、その敷地を活用した上で新しい施設として、さらに上の機能を目指してつくった施設であります。そういうフラッグシップ的な機能も持ちながら、先ほども申し上げたとおり充実した内容を目指して今後展開していきたいと考えているところです。","id":"exchange-006"},{"speaker":"伊藤委員","kind":"確認","question":"最初に確認なんですけど、先ほど定員の訂正がありましたよね。お願いします。","respondent":"伊崎待機児童対策担当課長","answer":"４歳児が、正しくは６０名、５歳児が６４名、合計１２４名で、二葉すこやか園としての合計が１９０名です。失礼いたしました。","id":"exchange-007"},{"speaker":"伊藤委員","kind":"確認","question":"そうしたら、まず今の説明を聞いていて、私たち文教委員会の公的な資料に入っていないということは非常に疑問があるなということを指摘します。再度確認するのは、あるいは同水準以上のものをつくっていったと思うんだけれども、そのことの説明をぜひもう一回答弁をお願いいたします。","respondent":"伊崎待機児童対策担当課長","answer":"豊葉の杜学園の図面をご提供させていただいたときに入っておりますので、申しわけございませんが、資料として添付はしておりません。当然のことながら最善の対応で進めておりますので、最善の子どもの利益を尊重した形で計画設計し、建設したものであります。","id":"exchange-008"},{"speaker":"伊藤委員","kind":"確認","question":"万が一そんなことがあったら、そうでない部分が確認できたわけですから、そのための社会の中のさまざまな制約の中で施設というものがあるわけです。あれば、それを教えてほしいですが、私はないと記憶しているんですが、いかがか尋ねました。","respondent":"伊崎待機児童対策担当課長","answer":"保育園の日照時間につきましては、特に規定はございません。日照時間につきましては規定はございませんが、建築基準法の採光については規定があります。","id":"exchange-009"},{"speaker":"伊藤委員","kind":"質問・要望","question":"ですから、今品川区のこういう都市的な環境の中で、これは議会として進めていくべきだと思います。万が一それが他から指摘されたような間違いだとするならば、これは指摘をしていきたいんだけども、もう一回だけ、その部分の確認だけお願いします。","respondent":"金子子ども未来事業部長","answer":"騒音、あるいはさまざまなそういった自然的条件についても、子どもの施設として最善なものになるように設計をして建設しているものです。日々の運営というのは、そういった条件のもとの中でさまざまに工夫してやっている…","id":"exchange-010"},{"speaker":"伊藤委員","kind":"質問・要望","question":"最後に要望ですけど、待機児童対策というのは、対策を進めることによって、これは定員が増えるわけです。これは私たちとしてはぜひ進めていっていただきたいし、それから建設、待機児童対策を進めていっていただくようお願いしておきます。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-011"},{"speaker":"阿部委員","kind":"質問・要望","question":"ただ、かつ待機児童の解消ということも早期に求められている中で、今限られた資源の中での最善という意味だと解釈しております。当たり前の保育をきちんとやっていく一つの施設という位置づけでやっていただきたいなと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-012"},{"speaker":"南委員","kind":"質問","question":"私、理事者より、むしろ委員のほうに伺いたいんですけども、先ほどもちょっと紹介したんですけど、４歳児、５歳児室は、北西に向いているんですね。その辺も含めて、どんな見解を持っておられるのか、改めてちょっとさまざまな会派の皆さんに伺いたいなというふうに思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-013"},{"speaker":"伊藤委員","kind":"意見","question":"それを限られた品川区というこの都市化の中で、どういうふうに合致していくかということを審査する。つくったほうがいいでしょう、そういうところで、私は議会として指摘すべきだと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-014"},{"speaker":"南委員","kind":"質問","question":"いいんですか、そんなので。反対です。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-015"},{"speaker":"阿部委員","kind":"質問","question":"平成２２年に所得制限を緩和し、それから３３万４,１００円にした、もう一度教えてください。それぞれ対象者が実際に私立幼稚園在籍者の何パーセントに当たっていたかというのをそれぞれ説明を求めました。","respondent":"立川保育課長","answer":"平成２２年に２１万６,７００円までだったものを、２６万３,５００円まで対象を広げました。今年度から３３万円４,１００円までの方が対象になりまして、全体で６５％程度の方に交付するという形になりました。","id":"exchange-016"},{"speaker":"阿部委員","kind":"質問","question":"今年度は昨年度以外に数字はそこまでですか。都はどれだけで、区はどのくらいあるのか、それをお知らせください。","respondent":"立川保育課長","answer":"生活保護世帯と特別区民税非課税世帯につきましては、東京都の補助が月額で６,２００円、区の上乗せ分が７,０００円あります。区が７,０００円、次の階層が３３万４,１００円までということで、区の上乗せ分のみの７,０００円となっております。","id":"exchange-017"},{"speaker":"阿部委員","kind":"質問・要望","question":"本当に逆に何て言ったらいいんですか、ある程度逆進傾向があるような制度が積み重なっているというのは、本当に負担が大きいと考えています。やはり補助金の所得制限というのは、そういった方向でぜひ検討いただきたいなと思っているんですが、区としてのお考えはどのようなものか尋ねました。","respondent":"立川保育課長","answer":"やはり平均の保育料というのは、若干平均を上回っていますので、どうしてもその辺は十分に注視していく。平成２２年、平成２４年も所得制限に関しましては、対象者につきまして拡大をしています。","id":"exchange-018"},{"speaker":"阿部委員","kind":"質問・要望","question":"あるいは子育て家庭の中で、それだけではないと、それは現実をぜひ見て判断してほしいと求めました。しかも３歳から入れようと思ったら私立しかないとか、幼稚園、そこは前向きに考えてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-019"},{"speaker":"伊藤委員","kind":"質問","question":"何ていうんですか、月謝というんですか、保育料か。さまざまだと思いますが、平均的なところで結構です。","respondent":"立川保育課長","answer":"区立幼稚園の保育料ですが、月額８,０００円です。","id":"exchange-020"},{"speaker":"伊藤委員","kind":"質問","question":"同じ子どもを養育している品川区の家庭ですから、何らかの対応があってしかるべきだろうという思いがあるわけですから、わからないですか。私立幼稚園に対するさまざまな助成金を厚くしていったほうが、私としては効果があると思うんですけれども、お考えを説明を求めました。","respondent":"立川保育課長","answer":"区のコストと、区だけのコストですと、私立につきましては、公立とは違う。私立の補完ということでこの間説明させていただいているところなんですけれども、公立、どちらも選択していただけるよう対応しているのが。","id":"exchange-021"},{"speaker":"伊藤委員","kind":"質問・要望","question":"品川区だって税でさまざま所得を使うわけですから、それから乳幼児人口の動向、さまざまな観点からそのこともやはりみていく必要がある。ですから、要望になってしまいますけれども、そのことはぜひ要望したいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-022"},{"speaker":"南委員","kind":"質問","question":"私立幼稚園に子どもが通っておられる世帯の６５％というのは、ちょっと驚き、少ないんだなというふうな驚きでしたね。伺いたいのは、ちょっとそのあたりの基本的な考え方、そこをちょっと伺いたいと思います。","respondent":"立川保育課長","answer":"そういう意味で、やはり保護者の方の子どもに対してよりよい教育環境で生活させたいというところで選択されているというところだと思います。やはり子育て支援というか、保育園の質の高い保育につきまして、いろいろ施策を打ってきました。","id":"exchange-023"},{"speaker":"南委員","kind":"質問","question":"あまりよくわからなかったので、もう一回伺いたいんですけども、子育て支援というのは、いろいろな名目があると思うんですね。この補助金を増やしてほしいとか、考え方は、子育て支援なんか尋ねました。","respondent":"立川保育課長","answer":"大もとといいますと、子育て支援というか、乳児、本人に対してよりよい環境を形成してもらうということで、私立幼稚園に対して補助し、ここに通うお子さんに対しましても経済的な支援です。","id":"exchange-024"},{"speaker":"南委員","kind":"質問","question":"幼稚園に通わせる方へ、安心して通園できるようにということでの経済的な支援をしながら子育てを支援していくと、こういうことでいいんですか。ちょっと、しつこくて悪いんですけど。","respondent":"立川保育課長","answer":"保護者への子育て支援という部分と、あとやはり、幼児ご本人の教育というところの充実した支援。","id":"exchange-025"},{"speaker":"南委員","kind":"質問","question":"２番目について、本当に運営そのものが、園運営そのものが大変だというふうに思うんですよね。私は引き上げるべき、少なくとも平均額までは引き上げるべきだと思っているんですけども、その辺についての見解というのはどうなんか尋ねました。","respondent":"立川保育課長","answer":"入園料の補助金も含めますと、平均額にかなり近い水準で補助は出しているというふうに認識しております。","id":"exchange-026"},{"speaker":"南委員","kind":"質問","question":"国の補助金を含めると平均額に近いというお話ですね。さっきの２３区との比較との関係では、それはどういうふうに評価したらいいんか尋ねました。","respondent":"立川保育課長","answer":"区で上乗せしている合計で考えたときに、２３区の平均からすると、それほど下回ってはいないです。","id":"exchange-027"},{"speaker":"南委員","kind":"質問","question":"都と品川区独自のこの補助金のところの比較をされて、２３区でかなり全ての階層で下回っているという説明でしたよね。先ほど紹介した２３区との、各階層で下回っている、そのことは事実か尋ねました。","respondent":"立川保育課長","answer":"国制度の補助金につきましては、各区共通で運営されておりまして、同額です。それに対して区が上乗せしているという意味で、月々の保育料につきましては先ほどお話ししました、先ほど数字を挙げさせていただいたとおりです。","id":"exchange-028"},{"speaker":"南委員","kind":"質問・要望","question":"みんなが安心して選べるような、教育を受けられるような、そういう条件整備をするべきだというふうに思っています。これは意見ですから、答弁は要らないです。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-029"},{"speaker":"伊藤委員","kind":"質問・要望","question":"今日、結論を出してほしいと求めました。それから、請願は採択ということで、。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-030"},{"speaker":"南委員","kind":"質問・要望","question":"私も今日出してほしいと求めました。態度は賛成をしたいと考えています。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-031"},{"speaker":"阿部委員","kind":"意見","question":"３年ぐらいの適切な学級規模というのは、３０人学級を定数とするような仕組みをつくるよりも、もっと現実的な方策があるのであろうと考えています。やはり３０人学級というだけだといいように聞こえるんですけれども、実際にやろうとすると…","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-032"},{"speaker":"南委員","kind":"質問・要望","question":"２年生の３５人に今年度なったその部分なんですけれども、それを一つ教えていただきたいのと、あえてそこのところをお伺いしておきたいと思います。そういうところでの公的責任というのを、やはり品川区としてはどういうふうに考えているのか、その辺の見解を伺いたいと思います。","respondent":"和氣学務課長、安井子育て支援課長、伊崎待機児童対策担当課長","answer":"さらに、少人数学習の問題ですが、５人ずつの班行動というのは、既に、品川の学校を見ていただければ、やってあります。… 経験年数をやはり持っている人でないと、急に来られては対応できませんので、そこら辺を確認しています。特に周知し、そのような内容をとって… 品川区では、当然のことながら児童福祉法に基づき、区の実施責任のもとに保育行政を進めております。したがいまして、株式会社だから公的責任を果たせない…","id":"exchange-033"},{"speaker":"南委員","kind":"質問・要望","question":"しかし、その少人数教育の効果は、どういうふうに教育委員会としては見ているのか、ちょっとその辺を改めて伺いたい。そういう事態に対して、どのような評価をされているのか、その辺を伺いたいなというふうに思っているんです。","respondent":"太田指導課長、安井子育て支援課長、伊崎待機児童対策担当課長","answer":"そういったさまざまな条件に合わせて、教員は効果的な人数編制というか、学習規模というのを考えて指導しています。人に教えたり… さまざまな中高生の対応であるとか、親御さんの指導、そういったことについての研修を行っております。委託館も必ず参加するようにという形で… 記憶は定かではないんですが、他府県で、経営母体である株式会社の主たる事業の経営が影響して破綻をしたというふうに記憶をしております。…","id":"exchange-034"},{"speaker":"南委員","kind":"質問・要望","question":"ある日突然ファクス１枚で閉園しますということで、そんな株式会社であってはならないわけですから、そういうのは。だから、そういうことを大事にしていただきたいということを要望として私は、意見としても述べておきたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-035"},{"speaker":"伊藤委員","kind":"確認","question":"請願項目、何点か確認します。１点目の公的責任による保育行政の推進というのは、一応品川区は公的責任において保育行政を展開していますよねという答弁をもう一回だけ。","respondent":"伊崎待機児童対策担当課長","answer":"品川区では、児童福祉法に基づきまして公的責任のもと、保育行政を展開しております。","id":"exchange-036"},{"speaker":"伊藤委員","kind":"確認","question":"２番目ですけど、「続けて参加したときに、実は保育園の行財政改革の請願と全く同じ意味合いの文章ですよ。ある程度、ある意味質は担保されていると思うんだけれども、もう一回そのところの確認をお願いいたします。","respondent":"安井子育て支援課長","answer":"専門的な知識を持ち、経験を持った職員を配置しておりますので、そこら辺については問題のないような形になってあります。","id":"exchange-037"},{"speaker":"伊藤委員","kind":"意見","question":"今の保育園の方々は相当努力されていらっしゃって、情報を共有して、さまざまな問題を解決していると思っている。そういう連携を十分とって、その筋から解決をしていくと思うんだけれども、その考え方について答弁をお願いいたしますとの意見を述べました。","respondent":"安井子育て支援課長","answer":"品川区では、安心ネットワークというものがございまして、そこの席にも委託館の職員が入っておりまして、そういった連携は常にとれるような体制をとってありますので、他館の連携等も十分に問題なく行われているというふうに考えてあります。","id":"exchange-038"},{"speaker":"伊藤委員","kind":"提案","question":"３０人学級のことをずっと、わかりました」と言ってくれるかどうでしょうかということが、まず確認していきたいというのが１点と。その財務を議会に提案されたときに、うちが３０人学級をやるから、果たして東京都はそれを受け入れてくれるかどうかの確認をまずお願いしますとの意見を述べました。","respondent":"和氣学務課長","answer":"言った場合、一切ないと思います。今、大変厳しくて、もちろん都も国が出している部分とあわせてやりますので、お願いしたとしても、まず不可能だというふうに考えております。","id":"exchange-039"},{"speaker":"伊藤委員","kind":"質問","question":"ですから、私たちのほうとしては、３０人学級に絶対しなければいけないと私たちは思っていません。目の前の課題をどう対処して、いかにいい環境にすべきかということのほうがはるかに大事だと思いますけども、品川区の考え方を説明を求めました。","respondent":"和氣学務課長","answer":"例えば、全国で一遍に３０人学級をやりますと、１万人以上の教員を確保しないとできないという話になります。それを考えますと、それらの条件の中で最大限の教育効果を発揮できるような形にしてまいりたいというふうに考えております。","id":"exchange-040"},{"speaker":"伊藤委員","kind":"意見","question":"今日、結論を出すということをお願いしたいと思います。それから、私たち自民党は不採択で意見を表明しますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-041"},{"speaker":"阿部委員","kind":"質問・要望","question":"いろいろなことが、ちょっと話が出てくるような体制というのは、ぜひ児童センターの中でもより求めてほしいと求めました。これはちょっと請願そのものではありませんけれども、つけ足していただきます。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-042"},{"speaker":"南委員","kind":"提案","question":"ずっと生き続けていくということになるわけですから、そういう点でも、そういう教育環境を整えるという点で３０人学級というこの要望は。以上が私の提案ですとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-043"}]},{"id":"topic-02","title":"の３、その他","agenda":"の３、その他","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"受けとめていただいて、場を設けていただきたいなというふうに思っております。そのことについて。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-044"},{"speaker":"金野委員長","kind":"提案","question":"いじめ等の調査状況についての中で、阿部委員から正副委員長に今後に向けての議論をする場の機会を設けてほしいとう要望について、お答えいたします。今後のそうした状況を早急に私どもの提案に報告をまとめていただいて、ご報告をいただくという形で進めていきたい…","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-045"},{"speaker":"南委員","kind":"質問","question":"２月と４月しかないかなと思うんですけども、果たしてそういうペースでいいかなというのは、ちょっとあると思うんですね。ですから、３カ月先になってしまうので、その辺についてどうか尋ねました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-046"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/162678?Template=document&Id=4776#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2012-01-01&TermEnd=2012-12-31"}],"sourceMeta":{"pages":0,"characters":39697,"voices":125}},{"id":"h24-20121126-5","meetingId":"h24-cm11","date":"2012年11月26日","dateIso":"2012-11-26","committee":"総務委員会","time":"午前１０時００分～午後１時２９分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を24件整理しています。","topics":[{"id":"topic-01","title":"はじめに(1)の「第８１号議案 東品川橋架替工事（下部工その１）請負契約の変更」","agenda":"はじめに(1)の「第８１号議案 東品川橋架替工事（下部工その１）請負契約の変更」","exchanges":[{"speaker":"石田（慎）委員","kind":"質問・要望","question":"変更の概要の３番に記されている、コンクリートに木片がまざっていて、含まれた手法でやらなきゃいけなくなったと。そのことを教えてほしいと求めました。","respondent":"稲田道路課長","answer":"五年たっておりまして、なかなかもう追及もできないし、もう引き継ぎでじかに品川区がやってというところでございました。原因追及というところはないということです。","id":"exchange-001"},{"speaker":"石田（慎）委員","kind":"質問・要望","question":"これは要望になってしまうんですが、やはりそういった初めの工事のときのそういった状況において、次の工事がこういうような結果が出てしまうと。そういう余分なことを次につながなくても済むので、そこは品川区としてもしっかり今後お取り組みいただければと思っています。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-002"},{"speaker":"飯沼委員","kind":"質問","question":"そこの大旺建設との関係をまず一つお伺いしたいのと、今日、ご説明いただいてありがとうあります。この違いを教えてほしいのと、工法が全部撤去しないで行うというあたりがどういうことなのか、ちょっと工法がわかる方がいたら説明を求めました。","respondent":"平澤経理課長、稲田道路課長","answer":"質問の第１点目、共同企業体の１つは、同じ事業者です。 これはミスプリントでございまして、茶色い色ということでご認識願いたいんです。ただ、先ほど現場でご説明いたしましたように被圧地下水があるので… 申しわけございませんでした。こちらはきちんとした工事をやっているということで、このままの事業者に引き続き工事を続けさせるという判断に至った次第で…","id":"exchange-003"},{"speaker":"飯沼委員","kind":"質問・要望","question":"正しい工事をしていただきたいという意味では、これからもきちんとチェックをよろしくお願いしたいのと、了解します。基礎杭のところなんですが、新しい杭のところだけ撤去してというのは、具体的にこの図で言うとどこがどういうふうになるのか、もっと具体的に。","respondent":"稲田道路課長","answer":"撤去する部分の絵は載せておりませんで、ちなみにもともとあった杭といいますのは、斜めに裾を広げるような形で杭が打たれているんですね。だからその範囲が広がることを極力抑えようという状況です。","id":"exchange-004"},{"speaker":"阿久津委員","kind":"質問","question":"私からは一点だけお伺いします。今の変更の概要の１番のところの、それともこういう工事ではよくあることなのか、少しその辺をお伺いしたいです。","respondent":"稲田道路課長","answer":"地層がつながっているもので、いざ上のけたをとってみて直近のジャストポイントで土質を調査してみたら、土質の内容が違っていたと。それから市街地、１度もう工事をやったところにおきましては、こういうことがあり得るということです。","id":"exchange-005"},{"speaker":"阿久津委員","kind":"質問","question":"今回、ちょっと変更内容が、ちょっとそこのところが気になったので質問させていただきました。よくある例ではないということがわかりましたので、運が悪かったのかということで、了解いたしました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-006"},{"speaker":"大沢委員","kind":"質問・要望","question":"延びたからといって、延びて契約も成立しているわけですから、作業員の安全確保だけはしっかりしていただきたいと。そこのところだけひとつ十分に留意をしていただきながら、工事を進めてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-007"},{"speaker":"飯沼委員","kind":"質問・要望","question":"本当に調査をきちんとして、不正が行われないように厳しくやってほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-008"}]},{"id":"topic-02","title":"の「第８２号議案 旧荏原平塚中学校跡地多目的広場整備工事請負契約」","agenda":"の「第８２号議案 旧荏原平塚中学校跡地多目的広場整備工事請負契約」","exchanges":[{"speaker":"石田（慎）委員","kind":"意見","question":"以前の契約と金額の差異があるのかどうかということと、工期についても、どのような方向が許されたのか、その２点をあわせてお知らせくださいとの意見を述べました。","respondent":"平澤経理課長","answer":"工期につきましては、前回では７月１７日までが工期だったところを、８月２０日までの工期です。議決の関係がございまして、こちらの工期につきましてはおおむね１カ月ほど短くなってあります。","id":"exchange-009"},{"speaker":"石田（慎）委員","kind":"質問","question":"その４００万円増加というのは、どのような理由で増額がされたのかを説明を求めました。","respondent":"平澤経理課長","answer":"一点目は、先ほどご説明申し上げましたとおり、工期が１カ月ほど短くなってしまったということがあります。そういったところが影響して、こういう金額になったものです。","id":"exchange-010"},{"speaker":"飯沼委員","kind":"質問・要望","question":"１つは、ここの理由を一つお聞かせいただきたいのと、ご説明があった労務単価の件なんでしょうか。３番と４番と７番、前回と同じく入札をされているようなんですが、ちょっとその辺の金額的なところを説明を求めました。","respondent":"平澤経理課長","answer":"２億７,１０９万円ということで、前回が２億７,０００万円ですので、１００万円ほど金額が上がっているです。こちらにつきましては、先ほどの繰り返しで恐縮ですが、労務単価の増加ということと工期が短くなった関係です。","id":"exchange-011"},{"speaker":"飯沼委員","kind":"質問","question":"一点目なんですが、工期が大幅におくれるということでわかりました。前回契約のことをちょっと学ばせていただいたんですが、業者のチェック機能という面ではどういうふうに違うのか、ちょっとその辺を説明を求めました。","respondent":"平澤経理課長","answer":"選定につきましては、不正も当然ですが、何ら変わるものではございません。厳しく選定をしています。","id":"exchange-012"},{"speaker":"阿久津委員","kind":"確認","question":"一点だけ確認で、地域の方のご理解をいただいているのかどうかだけ、確認させてください。","respondent":"平澤経理課長","answer":"先ほどのことで１カ月おくれるですが、地域のイベントにつきましては９月を予定しているです。前回、すぐに町会等にご説明に参上いたしまして、１カ月ほどおくれる可能性が出てきたということでお話をさし上げました。","id":"exchange-013"}]},{"id":"topic-03","title":"の「第８３号議案 専決処分の承認を求めることについて」","agenda":"の「第８３号議案 専決処分の承認を求めることについて」","exchanges":[{"speaker":"飯沼委員","kind":"質問・要望","question":"ちょっとその点を一点教えていただきたいのと、具体的に８ページの中身、わからなかったのがこの９ページの個人演説会経費と臨時啓発費という中身をちょっと説明を求めました。","respondent":"諸岡選挙管理委員会事務局長、本城企画財政課長","answer":"対応人員につきましては職員だけですと２８０名程度を予定していまして、大幅に変わってまいりますが、そのような金額になっております。そういうことに要する、具体的にこの選挙にかかわる費用を臨時啓発と区別しております。 先ほど委員のご指摘がございましたように、今回のように予定されなかったものについては補正予算対応となります。今回は特に補正予算ですが、議会に諮る時間的余裕がなかったので…","id":"exchange-014"},{"speaker":"飯沼委員","kind":"質問・要望","question":"さっきのところで職員が２８０名というのは、これは職員ですか。臨時というのは急に募集する部分があるんか尋ねました。","respondent":"諸岡選挙管理委員会事務局長","answer":"開票用の職員についての、投票所のほうでは職員とそれからアルバイト、人材派遣等を合わせて約４００人ぐらいということです。開票事務のほうを人材派遣で、この時点では３０人ぐらい使う予定でおりましたけれども、実際にはまた追加をしております。","id":"exchange-015"}]},{"id":"topic-04","title":"の「第８４号議案 土地付建物の売払いについて」","agenda":"の「第８４号議案 土地付建物の売払いについて」","exchanges":[{"speaker":"飯沼委員","kind":"質問","question":"二点お伺いします。売却ですから高く売れたほうがいいに越したことはないんですが、その辺をどう判断したらいいのかということを説明を求めました。","respondent":"平澤経理課長","answer":"１点目、売却予定価格１億８,０００万円の根拠です。財産価格審議会に諮問いたしまして、答申を頂いた数字をもとに、予定価格を算出しています。","id":"exchange-016"},{"speaker":"飯沼委員","kind":"意見","question":"これをどう理解したらいいのかなと思っていたんですけれども、こちらの予定価格というのは適正に算定をされていたということのご説明を受けました。いろいろ考えたら場所的にはぜひ活用してほしいと思っていたので、売却については引き続き反対ということで…","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-017"},{"speaker":"鈴木（真）委員","kind":"確認","question":"わかりました。この台帳のほうはどういう状況で見直しをするのか、そこだけ確認をさせてください。","respondent":"平澤経理課長","answer":"３年ごとに通常の路線価をもとに計算しています。","id":"exchange-018"}]},{"id":"topic-05","title":"の「第８８号議案 平成２４年度品川区一般会計補正予算について」","agenda":"の「第８８号議案 平成２４年度品川区一般会計補正予算について」","exchanges":[{"speaker":"石田（慎）委員","kind":"質問・要望","question":"例えば２つの選挙を同時にやると、これで行くとどれくらい変化というものがあるのだろうかというのが、もしわかれば教えてほしいと求めました。","respondent":"本城企画財政課長","answer":"２つの選挙が同時ということで、同時に同じ業務をできるということで、全般的には一定の効率が図られるということと考えております。２つのものを今回計上するに当たりましても、ご説明させていただいたような重複部分とかを精査した上で、提案させていただいていることになりま…","id":"exchange-019"},{"speaker":"石田（慎）委員","kind":"質問","question":"例えば投票の事務費も３,６００万円が都知事選挙で、衆議院議員選挙のほうは３,３００万円ですか。この経費は同日でも同日じゃなくても、もうあまり変化がないということでよろしいんか尋ねました。","respondent":"諸岡選挙管理委員会事務局長","answer":"一番見込まれるのは国が７割、予算の裏づけがないとこういうことは請求できませんので、若干７割という多めに提示させていただいているところです。都のほうが先ほどご審議いただきました予算のほうでほぼ１０割見ていますので…","id":"exchange-020"},{"speaker":"飯沼委員","kind":"質問","question":"先ほども都知事選挙のときの職員の数をお伺いしたんですが、合計でいいので、ちょっと職員数がどのくらいか。この個人演説会費って具体的にどういうことなのか、少し説明を求めました。","respondent":"諸岡選挙管理委員会事務局長","answer":"ですので、職員の３人に１人くらいが選挙に従事していただくということになります。各課に割り振りでお願いしたりというような方法をとって、今、募集をかけてお願いをしているという状況です。","id":"exchange-021"},{"speaker":"飯沼委員","kind":"質問","question":"一点、８ページの歳入の都の委託金のところの１１の衆議院議員選挙開票速報費というのはどういうことなんでしょうか、説明を求めました。","respondent":"諸岡選挙管理委員会事務局長","answer":"これは速報ということで出しますが、その間のパソコンによりまして、それを迅速に速報を行ったり、あるいは東京都のほうへ送付したりというようなことで、そういった機器類等の経費が主な経費です。","id":"exchange-022"},{"speaker":"飯沼委員","kind":"質問","question":"ということは、これの費用は東京都の委託金ということで、東京都の段階の集計のということですか。都の委託ということで、わかったら説明を求めました。","respondent":"諸岡選挙管理委員会事務局長","answer":"両方とも東京都を経由して、東京都が取りまとめますので、衆議院議員選挙、それから都知事選挙、両方とも同じような流れで行っております。","id":"exchange-023"},{"speaker":"鈴木（真）委員","kind":"意見","question":"一点だけ。都知事選挙は１９款諸収入で社会保険料が出ていますが、なぜこっちの会計には社会保険料が入ってないのかということの意見を述べました。","respondent":"本城企画財政課長","answer":"社会保険料についてはそこの範囲の職員ということで、追加的には新たに衆議院議員選挙で独自に社会保険料負担が必要になる職員がプラスで入ってこない関係で、もっぱら都知事選挙のほうにこの分を計上しています。","id":"exchange-024"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/579213?Template=document&Id=1930#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2012-01-01&TermEnd=2012-12-31"}],"sourceMeta":{"pages":0,"characters":18877,"voices":115}},{"id":"h24-20121127-6","meetingId":"h24-cm11","date":"2012年11月27日","dateIso":"2012-11-27","committee":"区民委員会","time":"午前９時５９分～午前１１時０６分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を20件整理しています。","topics":[{"id":"topic-01","title":"の１、「報告事項」を聴取いたします。 はじめに、(1)の「第１３回中学生の主張大会について」","agenda":"の１、「報告事項」を聴取いたします。 はじめに、(1)の「第１３回中学生の主張大会について」","exchanges":[{"speaker":"武内委員","kind":"質問","question":"冊子にして皆さんに配る以外に、何かいろいろなふさわしい場でやってもらうみたいなこととかというのは、今まではあったのか。何か活用を検討と言ったらおかしいのですけれども、どのぐらいあるのか尋ねました。","respondent":"久保田地域活動課長","answer":"うまく表現ができないのですけれども、去年最優秀賞を受けた方に来てもらって、今の中学生たちを激励してもらうという機会も設けてあります。今、委員がおっしゃったようなことは、今後もそういう受賞された方の励みになるような取り組みを進めていきたいと思います。","id":"exchange-001"},{"speaker":"武内委員","kind":"質問・要望","question":"何か逆に今度、そういうものを大人に感じてもらえるような場に、無理がない程度にうまく活用してもらえるといいかなと。これは要望です。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-002"}]},{"id":"topic-02","title":"の「品川区施設予約システムバージョンアップについて」","agenda":"の「品川区施設予約システムバージョンアップについて」","exchanges":[{"speaker":"山内委員","kind":"質問","question":"これを見ますと平成１５年から導入して１０年、じゃあ、一体何をしていたのですかという話になってくると思うのです。この費用をまず具体的に伺いたいのですが、それから、バージョンアップすることについての費用はかからないということでいいのか尋ねました。","respondent":"安藤文化スポーツ振興課長","answer":"それが、大体それに対して８０％以下に抑えられるということで、１,１００万円程度の予算を見込んでおります。そんな形でイニシャルコストは３,７００万円余を計上させていただきまして、ランニングコストについては８０％以下に抑えていくです。","id":"exchange-003"},{"speaker":"山内委員","kind":"提案","question":"そうなると日立のほうからこういうものがありますという提案は多分されていると思うのです。区民に対して、そこでちゅうちょしてしまったというのは何か理由があると思うのですけれども、そのあたりを伺いたいと思いますとの意見を述べました。","respondent":"安藤文化スポーツ振興課長","answer":"５年間やって、品川区の場合はその５年間のリース契約が済んで、そこでバージョンアップしなかった。そんな中で１０年間引っ張ってきて、ここでバージョンアップをしてという引き継ぎになったところであります。","id":"exchange-004"},{"speaker":"山内委員","kind":"提案","question":"そうすると、５年契約でまずやるということなわけですか。５年たちましたといったときに、こういうサービスはどうですかという提案はあろうかと思うのですけれども、そのあたりを説明を求めました。","respondent":"安藤文化スポーツ振興課長","answer":"契約自体は１年契約で更新していきますけれども、操作性と申しましょうか、それを違う業者のパッケージにすると全く変わってしまう中身だと思います。区民に親しんで引き続いて使っていただくのも一つの利便性でありますので…","id":"exchange-005"},{"speaker":"山内委員","kind":"提案","question":"やっぱりいろいろな提案があると思うのですが、今の課長の答弁ですと、そのあたりはどのようにお考えなのか。それが区民のためのサービスになっていくという観点から、今後の流れをどのように考えているのか、最後に伺いますとの意見を述べました。","respondent":"安藤文化スポーツ振興課長","answer":"我々もこの提案を受けまして、これで自庁サービスから環境でやっていく中では、今考えられる現状では非常に効率的な方法だと我々も認識しました。そんな意味も含めまして、当面、今のシステムを使いこなしていきたいと思っています。","id":"exchange-006"},{"speaker":"武内委員","kind":"確認","question":"今の確認ですけれども、そうすると、今までずっと日立とのつながりの中で、継続性だとか、また今後の新しいものについても先を考えてもこれはいいだろうということで、基本的には随意契約でやられたということですよね。","respondent":"安藤文化スポーツ振興課長","answer":"そうです。","id":"exchange-007"},{"speaker":"武内委員","kind":"質問","question":"その上で、私の質問としては、サーバーを自庁から移行したときに、セキュリティー対策というか、セキュリティーは今までと比べて危険度が増すとか、もしくはそれはあまり変わらない、もしくは日立という大きいところでやるから逆に安全になるのだとか、その辺の認識はどうか尋ねました。","respondent":"安藤文化スポーツ振興課長","answer":"今回はそういう専門の環境で一括して管理できるということで、セキュリティーの部分についても非常に高いセキュリティーが実現されたと考えています。日立をそこに配置して管理もしていたところですけれども、専門の環境を借りるということで…","id":"exchange-008"},{"speaker":"武内委員","kind":"質問・要望","question":"そうでなくても有名どころでセキュリティーが漏れただ何だとしょっちゅう週刊誌にも出ているわけですから、そこはしっかり意識した上で、じゃあ。要望です。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-009"},{"speaker":"井上副委員長","kind":"質問","question":"さらにこの３,７００万円ではいかないことがわかっていてそういうことなのか、その辺がよくわからないのですけれども、そこはどうか尋ねました。","respondent":"安藤文化スポーツ振興課長","answer":"いろいろな機能をそこに組み込んでいくバージョンアップの機能ということで、従来行っていた日立を継続してシステムを使っていくと。そんな中で、日立の従来のやり方を踏襲していくという判断に至ったわけです。","id":"exchange-010"},{"speaker":"井上副委員長","kind":"質問","question":"より確実に費用がかかっているのかどうかというところで、契約は５年ごとにやっていくということで、業者にとってはすごく楽なわけですよね。そういったところの経費削減みたいなところは、入札によって確実に上がるという判断があったのかどうかということはどうか尋ねました。","respondent":"安藤文化スポーツ振興課長","answer":"品川区独自のやり方をこの１０年間、一つひとつの仕様変更、これを構築してずっと来ているわけです。そんなこともありまして、今回は日立を継続するです。","id":"exchange-011"},{"speaker":"井上副委員長","kind":"提案","question":"改善提案があったとすれば、一緒にそういう検討をしていただけたらなと思っていたのですけれども、その辺はどういう感じか尋ねました。","respondent":"安藤文化スポーツ振興課長","answer":"大半が一つひとつの施設について条例を設置して、条例に基づいて何週間以内に入ってしまったら変更できませんだとか、そういう部分は条例に基づいて。仕様変更をしていくためにはお金、先ほどからご説明させていただいていますが、経費はかけずにできますです。","id":"exchange-012"},{"speaker":"武内委員","kind":"質問・要望","question":"今みたいな個別の比較的細かい要望を出したときに、日立がそれを無料で、必ずその都度応えてくれるという理解でいいのか尋ねました。","respondent":"安藤文化スポーツ振興課長","answer":"変わるのは、もっと大きなところで変わった場合に、それが単なる仕様変更だけで済まないようなものは経費がかかります。今まで一つひとつ仕様の変更になると、こちらで仕様書を書いて、こういう形にバージョンアップしてくださいと。","id":"exchange-013"}]},{"id":"topic-03","title":"の「大井町再開発ビル駐輪場について」","agenda":"の「大井町再開発ビル駐輪場について」","exchanges":[{"speaker":"井上副委員長","kind":"質問","question":"駐輪可能台数なのですけれども、ラック数が７２台ということではないと思うのですが、ラック数が何台で、駐輪可能台数は何台なのか説明を求めました。","respondent":"安藤文化スポーツ振興課長","answer":"その７２台という原因ですけれども、平成元年にできたビルなので、その中で駐輪の幅がその当時非常に狭くて、１台１台が非常に狭いと。足のプロテクターにかなりの幅がとられているということで、１台ずつだと非常に危険なので、一つ置きに置かせて７２台となっているです。","id":"exchange-014"},{"speaker":"井上副委員長","kind":"質問・要望","question":"これは要望でいいです。附置義務があるわけですから、そういう形での対策をぜひ要望してほしいと求めましたが、いかがか尋ねました。","respondent":"安藤文化スポーツ振興課長","answer":"しかし、平成１３年以前のものについては附置義務はなかったということなのです。きゅりあんとしたら従来の経緯から、諸室について５台、それから大ホールとかそういうものについては１０台という形にさせていただいたところです。","id":"exchange-015"},{"speaker":"井上副委員長","kind":"提案","question":"区民の利便性を考えれば、区も組合に入っているわけですから、組合が決めましたという話ではないと思うのです。利用実績を見た上で、改善が必要であればそういった提案をぜひしてほしいと求めましたので、対応してほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-016"},{"speaker":"本多委員","kind":"質問","question":"区の要請を受けて、管理組合も西友も協力的にいろいろ措置をとってくれたというのがわかりました。お聞きしたいのは、自転車が通行の妨げやバス乗降客の通行の障害になっていたという課題が解決されたのか、その辺の成果を説明を求めました。","respondent":"安藤文化スポーツ振興課長","answer":"そうすると、全くありません。その中で一定の成果は必ず出ていると確信しております。","id":"exchange-017"}]},{"id":"topic-04","title":"の「劇団四季新作ミュージカルおよび区との連携について」","agenda":"の「劇団四季新作ミュージカルおよび区との連携について」","exchanges":[{"speaker":"石田（ち）委員","kind":"意見","question":"劇団四季と区との連携では、商店街振興もあったと思うのですけれども、サンピアの通りをずらずら通られているのを結構見かけるようになったのですが、この辺の商店街の実績というか、どうだったのかなと思うのですけれどもとの意見を述べました。","respondent":"米田商業・観光課長、安藤文化スポーツ振興課長","answer":"そういった意味では、機会を捉えて集客につなげていく、これは今後も継続して行っていく。もちろん劇団四季との連携も定期的に図っていきますので、区も関与しながら進めていければと思っているところです。 劇団四季で、『ラ・アルプ』という月刊誌を出しています。過去のバックナンバーから４本、５本コピーしましたけれども、そういうところで劇団四季のほうも商店街をＰＲしていただいております。","id":"exchange-018"},{"speaker":"石田（ち）委員","kind":"意見","question":"平成２６年３月３１日に広町集合住宅が立ち退かされて開発地になっていくと思うのですが、それとも別の場所に移すのか。そういったまちの中でも、四季が来たということでいろいろな利用を広げ方もあると思うのですけれども、四季はどうなってしまうのかなとの意見を述べました。","respondent":"安藤文化スポーツ振興課長","answer":"私の知る限りの情報では、一切そういうことはなくて、１月２７日まで最終公演をやって、それからその後も「リトルマーメイド」を春から上演をしていくと私は聞いています。","id":"exchange-019"},{"speaker":"武内委員","kind":"意見","question":"２番の2)の「美しい日本語の話し方教室」というところで、これは四季の単独でやっていただいているのか、文化庁とかいろいろな助成金が出ますよね、そういうのを活用されているのか、それとも単独なのか、わかればとの意見を述べました。","respondent":"安藤文化スポーツ振興課長","answer":"これにつきましては、私の知る限りの情報では、劇団四季が全く独自に俳優が発音だとかそういうものを教えたというお話でして、単独でやられたと伺っています。","id":"exchange-020"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/118408?Template=document&Id=2654#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2012-01-01&TermEnd=2012-12-31"}],"sourceMeta":{"pages":0,"characters":19769,"voices":69}},{"id":"h24-20121127-7","meetingId":"h24-cm11","date":"2012年11月27日","dateIso":"2012-11-27","committee":"厚生委員会","time":"午前１０時００分～午前１０時４７分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を12件整理しています。","topics":[{"id":"topic-01","title":"ふれあい作業所の仮移転","agenda":"ふれあい作業所の仮移転","exchanges":[{"speaker":"石田（秀）委員","kind":"質問・要望","question":"お伺いをしたいことがあります。それはしようがないことだと考えていますが、一つ教えていただきたいのは、どういう形で使っていたのかというのが一つ。","respondent":"永尾障害者福祉課長","answer":"現状では、畳やふすまなどの大物を予定して考えていたところでしたけれども、そこの面積を全部使うまでの需要はなかったと聞いております。計画的なこういう使用の方法についての連携ですけれども、そういうところを分析した結果…","id":"exchange-001"},{"speaker":"石田（秀）委員","kind":"意見","question":"我々もいろいろもう１回勉強させていただいて、今度、企画部と話せるところでやりたいと思っています。それだけですとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-002"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"機能がどのように変わっていくのか、同じなのか、そこも伺いたいと思います。荏原分室を残さなかった理由と伺えばよろしいのでしょうか、残せなかったと伺えばよろしいのでしょうか、そこの状況をご説明ほしいと求めました。","respondent":"永尾障害者福祉課長","answer":"今後の規模ですけれども、西大井作業所のほうが３０人、西品川作業所が２０人ということで、合計５０人ということで、１０人プラスにする予定です。それとともに、新しい高齢者施設につきましても、できるだけ広く活用したいということから、こういう形式で決定したところです。","id":"exchange-003"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"それから、この変更に伴っての利用者への説明、保護者への説明や、具体的に挙がっているご意見などがありましたら、ご紹介ほしいと求めました。設計とか、完成とか、今後のスケジュールをご説明ほしいと求めました。","respondent":"永尾障害者福祉課長","answer":"１２月１２日ですけれども、八潮の町会・自治会会長会議のほうでご説明をする予定になっております。その後、調整等を考えまして、平成２７年４月から西大井の本部を開所しようと予定しています。","id":"exchange-004"},{"speaker":"塚本委員","kind":"質問","question":"１点目は、ないのか、お伺いしたいと思います。２点目なんですけれども、作業所の定員が１０名増えるということでお伺いいたしまして、お伺いしたいと思います。","respondent":"永尾障害者福祉課長","answer":"もう一つの就労継続支援Ｂ型の話ですけれども、実は、現在、ふれあい作業所は法外の小規模作業所という位置づけにやっております。まだ自立支援法内の施設になっておりませんので、広げることによって、就労継続支援Ｂ型のほうの事業所に移行する予定になっております。","id":"exchange-005"}]},{"id":"topic-02","title":"自殺予防・うつ病予防対策事業職員相談対応マニュアル","agenda":"自殺予防・うつ病予防対策事業職員相談対応マニュアル","exchanges":[{"speaker":"中塚副委員長","kind":"質問","question":"よく伺うのは、どうしてもやっぱり、そういう受けとめをされる方も実際にいらっしゃるんですよね。困っているからきているわけですから、ちょっと全体的な話ですけれども、状況を伺いたいと思います。","respondent":"福島品川区保健所荏原保健センター所長","answer":"眠れていますか、窓口対応ができることを目標に、今後もゲートキーパー研修というものは続けていくという予定にしております。この職員相談対応マニュアルというのをその中で使って、ゲートキーパー研修に成果を挙げたいと考えているというのが、今の現状です。","id":"exchange-006"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"結果も見えない中でやっていかざるを得ない部分もあると思うので、それは大変だろうけれども、続けていただきたいということが一つ。よほど私はいいと思うので、そういうことも気をつかっていただきたいと、これはお願いだけにしておきます。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-007"},{"speaker":"鈴木（博）委員","kind":"質問","question":"その質の保証というか、具体的に効果がどうだったかという検証というのは、どういう形で入っているんでしょうか。そうでないと、やりましたということで終わっちゃうんじゃないかと思うんです。","respondent":"福島品川区保健所荏原保健センター所長","answer":"連携すること、庁内の２４課の窓口職場の人たちに集まってもらって、どういうことを連携しなければいけないかということをしています。どういうところにこの方を支援してあげればいいかというところ、また地域の人々との連携ということを考えて、今のところはないと思います。","id":"exchange-008"},{"speaker":"鈴木（博）委員","kind":"意見","question":"例えば、研修を職員の何人が受けましたと、研修を受けたから、その研修のとおりにできるとは限らないと思うんですよね。そういうことがあるのかどうかということは、フィードバックの視点も入れて、今後の展開というのをよろしくお願いしたいと思いますとの意見を述べました。","respondent":"福島品川区保健所荏原保健センター所長","answer":"そういう事態をその場でとらえられるというのは、なかなか難しいということを、感想としては述べています。これからはこういうことに積極的に取り組んでいかなければいけないという積極的な意見もまたあったということが、感想として述べられていました。","id":"exchange-009"},{"speaker":"若林委員","kind":"質問","question":"大事な視点の質疑がありまして、私も、前の委員の質問と答弁の中はほんとうに大事だなと思っています。今のお話の中では、いわゆる理事者、職場のリーダーは受けていらっしゃるのかなと思ったんですが。","respondent":"福島品川区保健所荏原保健センター所長","answer":"この研修に興味を持って、ゲートキーパー研修に参加を希望している方には全員、門戸を開いておるということです。１回にせいぜい５０名とか、６０名ぐらいしかできませんので、全職員がその研修を受けてくれるまでずっと続けていきたいと考えております。","id":"exchange-010"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"形骸化しないでほしいと言ったんだけれども、そこの職員は１０年、その前に岡山に行ったときには３０年やっていると。我々が行政視察に行くということは、ある程度資料で、全国でそこが有名だから行こうとなるわけじゃないか尋ねました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-011"}]},{"id":"topic-03","title":"意見書（案）","agenda":"意見書（案）","exchanges":[{"speaker":"若林委員","kind":"質問","question":"３点あるうちの２点目は、下から３段目、通常いらないのではないでしょうかという指摘をします。以上、３点ありますので、理事者も含めて。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-012"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/594819?Template=document&Id=3342#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2012-01-01&TermEnd=2012-12-31"}],"sourceMeta":{"pages":0,"characters":12834,"voices":51}}]);
